        private static void PreviewVersionMetadataIsConsistent()
        {
            string repo = FindRepositoryRoot();
            string props = File.ReadAllText(Path.Combine(repo, "Directory.Build.props"));
            string authority = File.ReadAllText(Path.Combine(repo, "tools", "release", "dtmapi-runtime-version.props"));
            string release = File.ReadAllText(Path.Combine(repo, "tools", "scripts", "release-common.ps1"));
            string installer = File.ReadAllText(Path.Combine(repo, "tools", "scripts", "install-to-game.ps1"));
            string manifest = File.ReadAllText(Path.Combine(repo, "products", "first-party", "AutoFishing", "manifest.json"));
            string official = File.ReadAllText(Path.Combine(repo, "products", "first-party", "AutoFishing", "official-info.json"));
            string publish = File.ReadAllText(Path.Combine(repo, "tools", "release", "dtmapi-mod-publish-zh.json"));
            string catalogPath = Path.Combine(repo, "tools", "release", "dtmapi-product-catalog.json");
            string catalogChecker = File.ReadAllText(Path.Combine(repo, "tools", "scripts", "check-product-catalog.ps1"));
            string releaseContractChecker = File.ReadAllText(Path.Combine(repo, "tools", "scripts", "check-release-contract.ps1"));

            Assert(authority.Contains("<DtmApiReleaseVersion>0.6.1</DtmApiReleaseVersion>", StringComparison.Ordinal) &&
                authority.Contains("<DtmApiBinaryFileVersion>0.6.1.0</DtmApiBinaryFileVersion>", StringComparison.Ordinal) &&
                authority.Contains("<DtmApiAssemblyCompatibilityVersion>0.5.3.0</DtmApiAssemblyCompatibilityVersion>", StringComparison.Ordinal),
                "The tracked Runtime authority should separate release, file and frozen assembly-identity versions.");
            Assert(props.Contains("tools\\release\\dtmapi-runtime-version.props", StringComparison.Ordinal) &&
                props.Contains("<AssemblyVersion>$(DtmApiAssemblyCompatibilityVersion)</AssemblyVersion>", StringComparison.Ordinal) &&
                props.Contains("<FileVersion>$(DtmApiBinaryFileVersion)</FileVersion>", StringComparison.Ordinal) &&
                props.Contains("<Version>$(DtmApiReleaseVersion)</Version>", StringComparison.Ordinal),
                "Shared Runtime assembly/package metadata should project the tracked version authority.");
            Assert(release.Contains("Import-DtmApiRuntimeVersionAuthority", StringComparison.Ordinal) &&
                release.Contains("$script:DtmApiReleaseVersion = $script:DtmApiVersionAuthority.ReleaseVersion", StringComparison.Ordinal) &&
                release.Contains("$script:DtmApiBinaryVersion = $script:DtmApiVersionAuthority.BinaryFileVersion", StringComparison.Ordinal),
                "Release variables should be loaded from the tracked authority instead of copied literals.");
            Assert(!installer.Contains("$manifest.MinimumDTMApiVersion =", StringComparison.Ordinal), "The installer must validate product minimums without silently rewriting source manifests.");
            Assert(manifest.Contains("\"Version\": \"1.0.0\"", StringComparison.Ordinal) &&
                manifest.Contains("\"MinimumDTMApiVersion\": \"0.6.0\"", StringComparison.Ordinal) &&
                manifest.Contains("\"CodeModKind\": \"Advanced\"", StringComparison.Ordinal) &&
                manifest.Contains("\"EntryType\": \"Yuuka.DTMAPI.AutoFishing.ModEntry\"", StringComparison.Ordinal) &&
                manifest.Count(text => text == '\n') > 0,
                "AutoFishing should project product version 1.0.0 and its truthful 0.6.0 Runtime floor while compiling against the frozen Author SDK API target.");
            Assert(manifest.Split(new[] { "\"MinimumVersion\": \"0.5.5\"" }, StringSplitOptions.None).Length - 1 == 1 &&
                manifest.Contains("\"UniqueID\": \"DTMAPI.ModConfigMenu\"", StringComparison.Ordinal) &&
                !manifest.Contains("DTMAPI.GameBridge.DolocTown", StringComparison.Ordinal),
                "Self-contained AutoFishing should retain only its 0.5.5 ModConfigMenu dependency and no GameBridge dependency.");
            Assert(official.Contains("\"version\": \"1.0.0\"", StringComparison.Ordinal), "AutoFishing official metadata should match its projected product version.");
            Assert(publish.Contains("\"uniqueId\": \"DTMAPI.Runtime\"", StringComparison.Ordinal) && publish.Contains("\"version\": \"0.6.1\"", StringComparison.Ordinal) && publish.Contains("\"uniqueId\": \"Yuuka.DTMAPI.AutoFishing\"", StringComparison.Ordinal) && publish.Contains("\"version\": \"1.0.0\"", StringComparison.Ordinal), "Publish metadata should align the Runtime authority and projected AutoFishing source version.");
            using JsonDocument catalogDocument = JsonDocument.Parse(File.ReadAllText(catalogPath));
            JsonElement runtimeCatalog = catalogDocument.RootElement.GetProperty("runtime");
            JsonElement currentSource = runtimeCatalog.GetProperty("currentSourceBaseline");
            JsonElement currentPublished = runtimeCatalog.GetProperty("currentPublishedArtifact");
            Assert(currentSource.GetProperty("releaseVersion").GetString() == "0.6.1" &&
                currentSource.GetProperty("candidateInfoJsonBytes").GetInt32() == 9192 &&
                currentSource.GetProperty("candidateInfoJsonSha256").GetString() == "5d7e4538d34621efffa91b190535e2e274e237c97070aeaf2f46ea2ab17f1171" &&
                currentSource.GetProperty("candidateInfoJsonState").GetString() == "DeterministicSourceProjectionNotPublishedArtifact" &&
                currentPublished.GetProperty("releaseVersion").GetString() == "0.5.5" &&
                currentPublished.GetProperty("treeDigestNormalization").GetString() == "Exclude subscription-generated Content/.tools/bepinex/extract/**. Sort files by forward-slash relative path using StringComparer.Ordinal. Each row is lowercase file SHA-256, two spaces, then relative path. Join rows with LF and no final LF; hash UTF-8 without BOM using SHA-256." &&
                currentPublished.GetProperty("steamDeliveredTreeSha256").GetString() == "d7275bccc06207929de4ea62c8976bf20723ed33dd81666149a35289d29d5ebf" &&
                currentPublished.GetProperty("playerPayloadTreeSha256").GetString() == "571793091b47d5d2db909059b17c478bdebd60cc53a262bf88ff00e9e4becd63" &&
                currentPublished.GetProperty("infoJsonSha256").GetString() == "4ab3d471747a7e2ec37bda01884a604dcc63b0b74b764c6d34412b4dae905144",
                "Catalog must keep the deterministic 0.6 source-candidate info projection separate from the frozen exact 0.5.5 Steam-published artifact.");
            JsonElement[] publicProducts = catalogDocument.RootElement.GetProperty("products")
                .EnumerateArray()
                .Where(product => product.GetProperty("role").GetString() == "PublishedProduct")
                .ToArray();
            using JsonDocument publishDocument = JsonDocument.Parse(publish);
            JsonElement[] publishedTextRows = publishDocument.RootElement.GetProperty("mods")
                .EnumerateArray()
                .Where(row => row.GetProperty("scope").GetString() == "published")
                .ToArray();
            Assert(publishedTextRows.Length == publicProducts.Length,
                "The publish-text projection must contain exactly one row for each Catalog PublishedProduct.");
            foreach (JsonElement product in publicProducts)
            {
                string catalogId = product.GetProperty("catalogId").GetString() ?? string.Empty;
                string uniqueId = product.GetProperty("uniqueId").GetString() ?? string.Empty;
                JsonElement[] matchingRows = publishedTextRows
                    .Where(row => row.GetProperty("uniqueId").GetString() == uniqueId)
                    .ToArray();
                Assert(matchingRows.Length == 1,
                    "The publish-text projection must contain exactly one row for " + catalogId + ".");

                string sourceRoot = product.GetProperty("sourceRoot").GetString() ?? string.Empty;
                string sourceManifest = product.GetProperty("sourceManifest").GetString() ?? string.Empty;
                using JsonDocument officialInfoDocument = JsonDocument.Parse(File.ReadAllText(
                    Path.Combine(repo, sourceRoot.Replace('/', Path.DirectorySeparatorChar), "official-info.json")));
                using JsonDocument sourceManifestDocument = JsonDocument.Parse(File.ReadAllText(
                    Path.Combine(repo, sourceManifest.Replace('/', Path.DirectorySeparatorChar))));
                JsonElement row = matchingRows[0];
                JsonElement officialInfo = officialInfoDocument.RootElement;
                JsonElement sourceManifestRoot = sourceManifestDocument.RootElement;
                Assert(row.GetProperty("author").GetString() == officialInfo.GetProperty("author").GetString() &&
                    row.GetProperty("version").GetString() == officialInfo.GetProperty("version").GetString() &&
                    row.GetProperty("modName").GetString() == officialInfo.GetProperty("name").GetString() &&
                    row.GetProperty("gameDescription").GetString() == officialInfo.GetProperty("description").GetString() &&
                    !string.IsNullOrWhiteSpace(row.GetProperty("steamName").GetString()) &&
                    !string.IsNullOrWhiteSpace(row.GetProperty("steamDescription").GetString()) &&
                    row.GetProperty("manifestName").GetString() == sourceManifestRoot.GetProperty("Name").GetString(),
                    "Published game text for " + catalogId + " must mirror current source metadata while its independent Steam review copy remains non-empty.");
            }
            Assert(publicProducts.Length == 11 &&
                publicProducts.Count(product =>
                    new[] { "auto-fishing", "y-console", "more-equipment-slots", "more-saves" }.Contains(product.GetProperty("catalogId").GetString(), StringComparer.Ordinal) &&
                    product.GetProperty("targetMinimumDtmApiVersion").GetString() == "0.6.0") == 4 &&
                publicProducts.Count(product =>
                    !new[] { "auto-fishing", "y-console", "more-equipment-slots", "more-saves" }.Contains(product.GetProperty("catalogId").GetString(), StringComparer.Ordinal) &&
                    product.GetProperty("targetMinimumDtmApiVersion").GetString() == "0.5.5") == 7,
                "Only AutoFishing, Y-console, MoreEquipmentSlots and MoreSaves may require the 0.6.0 Runtime; the other seven authorized public updates retain their independently reviewed 0.5.5 floor.");
            Assert(publicProducts.Count(product =>
                    product.GetProperty("catalogId").GetString() == "more-saves" &&
                    product.GetProperty("targetVersion").GetString() == "1.0.1") == 1 &&
                publicProducts.Count(product =>
                    product.GetProperty("catalogId").GetString() != "more-saves" &&
                    product.GetProperty("targetVersion").GetString() == "1.0.0") == 10 &&
                releaseContractChecker.Contains("$expectedMigrationTargetVersion = if ($catalogId -eq 'more-saves') { '1.0.1' } else { '1.0.0' }", StringComparison.Ordinal) &&
                Regex.IsMatch(releaseContractChecker, @"migration target version[^\r\n]*-Expected \$expectedMigrationTargetVersion", RegexOptions.CultureInvariant),
                "The release contract must preserve MoreSaves 1.0.1 as the sole post-migration patch version while the other ten public products remain at 1.0.0.");
            Assert(releaseContractChecker.Contains("$expectedMoreSavesTags = @('Mod', 'Utility', 'Functional', 'DTMAPI', 'Save', 'Chinese')", StringComparison.Ordinal) &&
                releaseContractChecker.Contains("more-saves official-info exact tags", StringComparison.Ordinal) &&
                releaseContractChecker.Contains("more-saves Author SDK publish exact tags", StringComparison.Ordinal),
                "The release contract must lock MoreSaves official metadata and Author SDK publish tags to the same exact Functional product taxonomy without opening unrelated tag debt.");
            Assert(releaseContractChecker.Contains("publish manifest name", StringComparison.Ordinal) &&
                releaseContractChecker.Contains("publish author", StringComparison.Ordinal) &&
                releaseContractChecker.Contains("publish mod name", StringComparison.Ordinal) &&
                releaseContractChecker.Contains("publish Steam name", StringComparison.Ordinal) &&
                releaseContractChecker.Contains("publish game description", StringComparison.Ordinal) &&
                releaseContractChecker.Contains("publish Steam description", StringComparison.Ordinal),
                "The release contract must fail closed when published player-facing text drifts from the current product metadata.");
            Assert(Regex.IsMatch(releaseContractChecker, @"\$productMigrationTargetMinimum\s*=\s*'0\.5\.5'", RegexOptions.CultureInvariant) &&
                releaseContractChecker.Contains("$expectedMigrationTargetMinimum = if ($catalogId -in @('auto-fishing', 'y-console', 'more-equipment-slots', 'more-saves')) { '0.6.0' } else { $productMigrationTargetMinimum }", StringComparison.Ordinal) &&
                Regex.IsMatch(releaseContractChecker, @"migration target minimum[^\r\n]*-Expected \$expectedMigrationTargetMinimum", RegexOptions.CultureInvariant) &&
                !Regex.IsMatch(releaseContractChecker, @"migration target minimum[^\r\n]*-Expected \$releaseVersion", RegexOptions.CultureInvariant),
                "The release contract must project the four exact 0.6 product floors without deriving every first-party migration floor from the Runtime release version.");
            Assert(catalogChecker.Contains("Built Runtime info.json candidate version", StringComparison.Ordinal) &&
                catalogChecker.Contains("matches current candidate stable-form SHA-256", StringComparison.Ordinal) &&
                catalogChecker.Contains("Unpublished Runtime candidate info.json remains distinct from the frozen published artifact.", StringComparison.Ordinal) &&
                !catalogChecker.Contains("Built Runtime info.json matches published stable-form", StringComparison.Ordinal),
                "Package validation must bind a built Runtime to the current source candidate without rewriting or comparing against the frozen published artifact identity.");
        }

        private static void PublicApiStatusMetadataMatchesMatrix()
        {
            foreach ((Type Type, string Since) row in new[]
                     {
                         (typeof(IModRegistry), "0.1.0"),
                         (typeof(ITranslationHelper), "0.1.12"),
                         (typeof(IDtmConfigMenuApi), "0.1.0")
                     })
            {
                DtmApiStatusAttribute status = row.Type.GetCustomAttribute<DtmApiStatusAttribute>()
                    ?? throw new InvalidOperationException(row.Type.Name + " must publish explicit stability metadata.");
                Assert(status.Status == DtmApiStatus.StableCandidate && status.Since == row.Since,
                    row.Type.Name + " must mechanically match the public API matrix StableCandidate status without rewriting its historical Since value.");
            }

            DtmApiStatusAttribute keybindDefaults = typeof(IDtmConfigMenuKeybindDefaultsApi).GetCustomAttribute<DtmApiStatusAttribute>()
                ?? throw new InvalidOperationException(nameof(IDtmConfigMenuKeybindDefaultsApi) + " must publish explicit stability metadata.");
            Assert(keybindDefaults.Status == DtmApiStatus.Experimental,
                "The optional config-menu keybind Reset capability must remain Experimental when the primary config-menu surface becomes StableCandidate.");
        }

        private static void DependencyVersionApiVersionAndCircularDependencyDiagnostics()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                Assert(DtmApiRuntime.ApiVersion == "0.6.1", "DTMAPI runtime API version should project the 0.6.1 release authority.");
                Assert(DtmApiRuntime.BinaryVersion == "0.6.1.0", "DTMAPI binary/plugin file version should remain numeric and project the 0.6.1 authority.");
                WriteManifest(dir, "Base", "{ \"Name\": \"Base\", \"Author\": \"DTMAPI\", \"Version\": \"1.0.0\", \"UniqueID\": \"DTMAPI.Tests.Base\", \"Type\": \"ContentPack\" }");
                WriteManifest(dir, "NeedsBase2", "{ \"Name\": \"Needs Base 2\", \"Author\": \"DTMAPI\", \"Version\": \"1.0.0\", \"UniqueID\": \"DTMAPI.Tests.NeedsBase2\", \"Type\": \"ContentPack\", \"Dependencies\": [ { \"UniqueID\": \"DTMAPI.Tests.Base\", \"MinimumVersion\": \"2.0.0\", \"Required\": true } ] }");
                WriteManifest(dir, "OptionalNeedsBase2", "{ \"Name\": \"Optional Needs Base 2\", \"Author\": \"DTMAPI\", \"Version\": \"1.0.0\", \"UniqueID\": \"DTMAPI.Tests.OptionalNeedsBase2\", \"Type\": \"ContentPack\", \"Dependencies\": [ { \"UniqueID\": \"DTMAPI.Tests.Base\", \"MinimumVersion\": \"2.0.0\", \"Required\": false } ] }");
                WriteManifest(dir, "NeedsCurrentApi", "{ \"Name\": \"Needs Current API\", \"Author\": \"DTMAPI\", \"Version\": \"1.0.0\", \"UniqueID\": \"DTMAPI.Tests.CurrentApi\", \"Type\": \"ContentPack\", \"MinimumDTMApiVersion\": \"0.5.5\" }");
                WriteManifest(dir, "Legacy042Api", "{ \"Name\": \"Legacy 0.4.2 API\", \"Author\": \"DTMAPI\", \"Version\": \"1.0.0\", \"UniqueID\": \"DTMAPI.Tests.Legacy042Api\", \"Type\": \"ContentPack\", \"MinimumDTMApiVersion\": \"0.4.2\" }");
                WriteManifest(dir, "Legacy031Api", "{ \"Name\": \"Legacy 0.3.1 API\", \"Author\": \"DTMAPI\", \"Version\": \"1.0.0\", \"UniqueID\": \"DTMAPI.Tests.Legacy031Api\", \"Type\": \"ContentPack\", \"MinimumDTMApiVersion\": \"0.3.1\" }");
                WriteManifest(dir, "NeedsFutureAlphaApi", "{ \"Name\": \"Needs Future Alpha API\", \"Author\": \"DTMAPI\", \"Version\": \"1.0.0\", \"UniqueID\": \"DTMAPI.Tests.FutureAlphaApi\", \"Type\": \"ContentPack\", \"MinimumDTMApiVersion\": \"0.6.2-alpha\" }");
                WriteManifest(dir, "NeedsFutureApi", "{ \"Name\": \"Needs Future API\", \"Author\": \"DTMAPI\", \"Version\": \"1.0.0\", \"UniqueID\": \"DTMAPI.Tests.FutureApi\", \"Type\": \"ContentPack\", \"MinimumDTMApiVersion\": \"99.0.0\" }");
                WriteManifest(dir, "CycleA", "{ \"Name\": \"Cycle A\", \"Author\": \"DTMAPI\", \"Version\": \"1.0.0\", \"UniqueID\": \"DTMAPI.Tests.CycleA\", \"Type\": \"ContentPack\", \"Dependencies\": [ { \"UniqueID\": \"DTMAPI.Tests.CycleB\", \"Required\": true } ] }");
                WriteManifest(dir, "CycleB", "{ \"Name\": \"Cycle B\", \"Author\": \"DTMAPI\", \"Version\": \"1.0.0\", \"UniqueID\": \"DTMAPI.Tests.CycleB\", \"Type\": \"ContentPack\", \"Dependencies\": [ { \"UniqueID\": \"DTMAPI.Tests.CycleA\", \"Required\": true } ] }");

                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                runtime.Start();
                RuntimeSnapshot snapshot = runtime.CreateSnapshot();
                Assert(snapshot.LoadedMods.Any(m => m.Manifest.UniqueID == "DTMAPI.Tests.Base"), "Base dependency should load.");
                Assert(!snapshot.LoadedMods.Any(m => m.Manifest.UniqueID == "DTMAPI.Tests.NeedsBase2"), "Required dependency version mismatch should block loading.");
                Assert(snapshot.LoadedMods.Any(m => m.Manifest.UniqueID == "DTMAPI.Tests.OptionalNeedsBase2"), "Optional dependency version mismatch should warn but not block loading.");
                Assert(snapshot.LoadedMods.Any(m => m.Manifest.UniqueID == "DTMAPI.Tests.CurrentApi"), "MinimumDTMApiVersion 0.5.5 should load on the current Runtime.");
                Assert(snapshot.LoadedMods.Any(m => m.Manifest.UniqueID == "DTMAPI.Tests.Legacy042Api"), "Legacy MinimumDTMApiVersion 0.4.2 should still load on the current Runtime.");
                Assert(snapshot.LoadedMods.Any(m => m.Manifest.UniqueID == "DTMAPI.Tests.Legacy031Api"), "Legacy MinimumDTMApiVersion 0.3.1 should still load on the current Runtime.");
                Assert(!snapshot.LoadedMods.Any(m => m.Manifest.UniqueID == "DTMAPI.Tests.FutureAlphaApi"), "Future MinimumDTMApiVersion 0.6.2-alpha should block loading.");
                Assert(!snapshot.LoadedMods.Any(m => m.Manifest.UniqueID == "DTMAPI.Tests.FutureApi"), "Future MinimumDTMApiVersion should block loading.");
                Assert(!snapshot.LoadedMods.Any(m => m.Manifest.UniqueID == "DTMAPI.Tests.CycleA"), "CycleA should be blocked and must not load.");
                Assert(!snapshot.LoadedMods.Any(m => m.Manifest.UniqueID == "DTMAPI.Tests.CycleB"), "CycleB should be blocked and must not load.");
                IContentQueryHelper content = GetContent(runtime);
                Assert(!content.FindAssets("json").Any(asset => asset.SourceModId.Equals("DTMAPI.Tests.NeedsBase2", StringComparison.OrdinalIgnoreCase)), "A required-dependency failure must not publish the blocked owner's content.");
                Assert(!content.FindAssets("json").Any(asset => asset.SourceModId.Equals("DTMAPI.Tests.CycleA", StringComparison.OrdinalIgnoreCase) || asset.SourceModId.Equals("DTMAPI.Tests.CycleB", StringComparison.OrdinalIgnoreCase)), "Dependency-cycle failures must not publish either inactive owner's content.");
                Assert(content.FindAssets("json").Any(asset => asset.SourceModId.Equals("DTMAPI.Tests.OptionalNeedsBase2", StringComparison.OrdinalIgnoreCase)), "An optional-dependency warning must preserve the active owner's content publication.");
                Assert(snapshot.Errors.Any(e => e.Owner == "DTMAPI.Tests.NeedsBase2" && e.Message.Contains("依赖版本")), "Dependency version mismatch should be diagnosed.");
                Assert(!snapshot.Errors.Any(e => e.Owner == "DTMAPI.Tests.OptionalNeedsBase2"), "Optional dependency version mismatch should not be recorded as an error.");
                Assert(snapshot.Warnings.Any(w => w.Owner == "DTMAPI.Tests.OptionalNeedsBase2" && w.Message.Contains("可选依赖版本过低")), "Optional dependency version mismatch should be recorded as a structured warning.");
                Assert(snapshot.Errors.Any(e => e.Owner == "DTMAPI.Tests.FutureAlphaApi" && e.Message.Contains("前置版本过旧") && e.Details.Contains("Run 1_install_dtmapi.bat")), "Future alpha MinimumDTMApiVersion mismatch should tell players to update DTMAPI.");
                Assert(snapshot.Errors.Any(e => e.Owner == "DTMAPI.Tests.FutureApi" && e.Message.Contains("前置版本过旧") && e.Details.Contains("Run 1_install_dtmapi.bat")), "MinimumDTMApiVersion mismatch should tell players to update DTMAPI.");
                Assert(snapshot.Errors.Any(e => e.Message.Contains("依赖循环") && e.Details.Contains("DTMAPI.Tests.CycleA") && e.Details.Contains("DTMAPI.Tests.CycleB")), "Circular dependencies should be diagnosed with the cycle path.");
                Assert(snapshot.Errors.Any(e => e.Owner == "DTMAPI.Tests.CycleA" && e.Message.Contains("依赖循环阻止加载")), "CycleA should have an owner-specific blocked diagnostic.");
                Assert(snapshot.Errors.Any(e => e.Owner == "DTMAPI.Tests.CycleB" && e.Message.Contains("依赖循环阻止加载")), "CycleB should have an owner-specific blocked diagnostic.");
                IDtmDiagnosticsSnapshot diagnosticsSnapshot = runtime.CreateDiagnosticsSnapshot();
                Assert(diagnosticsSnapshot.Mods.Single(m => m.UniqueID == "DTMAPI.Tests.Base").StatusCode == "loaded", "Loaded dependency should expose loaded status code.");
                Assert(diagnosticsSnapshot.Mods.Single(m => m.UniqueID == "DTMAPI.Tests.NeedsBase2").StatusCode == "missing-dependency", "Dependency version failures should expose a dependency status code.");
                Assert(diagnosticsSnapshot.Mods.Single(m => m.UniqueID == "DTMAPI.Tests.OptionalNeedsBase2").Loaded && diagnosticsSnapshot.Mods.Single(m => m.UniqueID == "DTMAPI.Tests.OptionalNeedsBase2").StatusCode == "loaded", "Optional dependency warnings should leave loaded mods in loaded status.");
                Assert(diagnosticsSnapshot.Warnings.Any(w => w.Owner == "DTMAPI.Tests.OptionalNeedsBase2"), "Diagnostics snapshot should include optional dependency warnings.");
                Assert(diagnosticsSnapshot.Mods.Single(m => m.UniqueID == "DTMAPI.Tests.CurrentApi").StatusCode == "loaded", "Current MinimumDTMApiVersion should expose loaded status code.");
                Assert(diagnosticsSnapshot.Mods.Single(m => m.UniqueID == "DTMAPI.Tests.Legacy042Api").StatusCode == "loaded", "Legacy 0.4.2 MinimumDTMApiVersion should expose loaded status code.");
                Assert(diagnosticsSnapshot.Mods.Single(m => m.UniqueID == "DTMAPI.Tests.Legacy031Api").StatusCode == "loaded", "Legacy 0.3.1 MinimumDTMApiVersion should expose loaded status code.");
                Assert(diagnosticsSnapshot.Mods.Single(m => m.UniqueID == "DTMAPI.Tests.FutureAlphaApi").StatusCode == "api-too-new", "Future alpha MinimumDTMApiVersion should expose api-too-new status code.");
                Assert(diagnosticsSnapshot.Mods.Single(m => m.UniqueID == "DTMAPI.Tests.FutureApi").StatusCode == "api-too-new", "Future MinimumDTMApiVersion should expose api-too-new status code.");
                Assert(diagnosticsSnapshot.Mods.Single(m => m.UniqueID == "DTMAPI.Tests.CycleA").StatusCode == "dependency-cycle", "CycleA should expose dependency-cycle status code.");
                Assert(diagnosticsSnapshot.Mods.Single(m => m.UniqueID == "DTMAPI.Tests.CycleB").StatusCode == "dependency-cycle", "CycleB should expose dependency-cycle status code.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

