            IInputHelper ownerB = input.CreateOwnerBound("DTMAPI.Tests.OwnerScopedB");
            ownerA.RegisterKeybind("toggle", "F6", DtmInputScope.Gameplay);
            ownerB.RegisterKeybind("toggle", "Y", DtmInputScope.Gameplay);

            input.RecordFrame(
                DtmInputScope.Gameplay,
