        private static void ModLoadCheckpointsRollbackAllOwnerRoots()
        {
            foreach (ModLoadCheckpoint checkpoint in Enum.GetValues(typeof(ModLoadCheckpoint)))
            {
                string? previousRoot = UseTempPersistentRoot();
                try
                {
                    string dir = NewTempGameDir();
                    string ownerId = "DTMAPI.Tests.Atomic." + checkpoint;
                    var menu = new ConfigMenuRegistry();
                    var runtime = CreateAtomicProbeRuntime(dir, ownerId, menu);
                    var participant = new AtomicCheckpointCleanupParticipant();
                    runtime.RegisterRuntimeApi<IAtomicCheckpointParticipantApi>(new ManifestModel
                    {
                        Name = "Atomic Checkpoint Participant",
                        Author = "DTMAPI",
                        Version = DtmApiRuntime.ApiVersion,
                        UniqueID = AtomicCheckpointCleanupParticipant.ProviderId,
                        Type = "RuntimeApi"
                    }, participant);
                    runtime.RegisterModOwnerCleanupParticipant(participant);
                    runtime.ConfigureModLoadCheckpointForTests(current =>
                    {
                        if (current == checkpoint)
                            throw new InvalidOperationException("checkpoint-" + checkpoint);
                    });
                    AtomicOwnerProbeMod.DisposeCount = 0;
                    AtomicOwnerProbeMod.DisposeFailuresRemaining = 0;
                    runtime.Start();

                    Assert(!runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == ownerId), checkpoint + " failure must not publish loaded state.");
                    Assert(runtime.ModRegistry.GetApi<IUnitProbeApi>(ownerId) == null, checkpoint + " failure must remove API roots.");
                    Assert(((IConfigMenuRuntime)menu).GetPage(ownerId) == null, checkpoint + " failure must remove config callbacks.");
                    Assert(runtime.Config.CountOwner(ownerId) == 0, checkpoint + " failure must remove config migration roots.");
                    Assert(!runtime.Input.GetRegisteredButtons().Contains("F12", StringComparer.OrdinalIgnoreCase), checkpoint + " failure must dispose input roots.");
                    Assert(runtime.Events.GetHandlerCleanupSnapshot().Slots.All(slot => !slot.ByOwner.ContainsKey(ownerId)), checkpoint + " failure must remove event roots.");
                    Assert(!GetContent(runtime).FindAssets("json").Any(asset => asset.SourceModId.Equals(ownerId, StringComparison.OrdinalIgnoreCase)), checkpoint + " failure must not publish owner content assets.");
                    Assert(runtime.ModOwnerLedgerSnapshot.ActiveTransactions == 0, checkpoint + " failure must close the owner transaction.");
                    Assert(runtime.OwnerRequiresRestart(ownerId), checkpoint + " failure after assembly-load attempt should require restart.");
                    Assert(participant.CountOwnerResources(ownerId) == 0, checkpoint + " failure must leave zero participant roots.");
                    bool entryRan = (int)checkpoint >= (int)ModLoadCheckpoint.EntryReturned;
                    bool instanceCreated = (int)checkpoint >= (int)ModLoadCheckpoint.InstanceCreated;
                    Assert(AtomicOwnerProbeMod.DisposeCount == (instanceCreated ? 1 : 0), checkpoint + " rollback must dispose every constructed instance, including failures before Entry publication.");
                    Assert(participant.RegisterCalls == (entryRan ? 1 : 0), checkpoint + " should create a participant root exactly when Entry completed registration.");
                    Assert(participant.CleanupCalls == 1 && participant.RemovedResources == (entryRan ? 1 : 0), checkpoint + " rollback must invoke participant cleanup and remove every post-Entry root.");
                }
                finally
                {
                    RestorePersistentRoot(previousRoot);
                }
            }
        }

        private static void CompletionLogFailureDoesNotReverseSuccessfulEntry()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                const string ownerId = "DTMAPI.Tests.CompletionLog";
                var runtime = CreateAtomicProbeRuntime(dir, ownerId, new ConfigMenuRegistry());
                runtime.ConfigureModCompletionLogForTests(_ => throw new IOException("completion-log-failure"));
                AtomicOwnerProbeMod.EntryCount = 0;
                runtime.Start();
                Assert(runtime.LoadedMods.Count(mod => mod.Manifest.UniqueID == ownerId) == 1, "Completion logging failure must not reverse successful Entry publication.");
                Assert(AtomicOwnerProbeMod.EntryCount == 1, "Completion logging failure must not repeat Entry.");
                Assert(runtime.ModRegistry.GetApi<IUnitProbeApi>(ownerId) != null, "Completion logging failure must preserve the committed owner API.");
                Assert(GetContent(runtime).FindAssets("json").Any(asset => asset.SourceModId.Equals(ownerId, StringComparison.OrdinalIgnoreCase)), "A successfully committed owner must publish its content assets.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void TransactionDiagnosticFailuresCannotLeakOrReverseSuccessfulLoad()
        {
            foreach (string phase in new[] { "begin", "commit" })
            {
                string? previousRoot = UseTempPersistentRoot();
                try
                {
                    string ownerId = "DTMAPI.Tests.TransactionDiagnostic." + phase;
                    var runtime = CreateAtomicProbeRuntime(NewTempGameDir(), ownerId, new ConfigMenuRegistry());
                    int hookCalls = 0;
                    Action throwingDiagnostic = () =>
                    {
                        hookCalls++;
                        throw new IOException("transaction-" + phase + "-diagnostic-failure");
                    };
                    runtime.ConfigureModTransactionDiagnosticsForTests(
                        phase.Equals("begin", StringComparison.Ordinal) ? throwingDiagnostic : null,
                        phase.Equals("commit", StringComparison.Ordinal) ? throwingDiagnostic : null);
                    AtomicOwnerProbeMod.EntryCount = 0;

                    runtime.Start();

                    ModOwnerLedgerSnapshot ledger = runtime.ModOwnerLedgerSnapshot;
                    Assert(hookCalls == 1, "The injected transaction " + phase + " diagnostic should run exactly once.");
                    Assert(runtime.LoadedMods.Count(mod => mod.Manifest.UniqueID == ownerId) == 1 && AtomicOwnerProbeMod.EntryCount == 1, "A transaction " + phase + " diagnostic failure must not reverse or repeat a successful Entry.");
                    Assert(runtime.ModRegistry.GetApi<IUnitProbeApi>(ownerId) != null, "A transaction " + phase + " diagnostic failure must preserve committed owner API roots.");
                    Assert(ledger.ActiveTransactions == 0 && ledger.CommittedTransactions == 1 && ledger.RolledBackTransactions == 0, "A transaction " + phase + " diagnostic failure must still close and commit the owner transaction exactly once.");
                    Assert(!runtime.OwnerRequiresRestart(ownerId), "A best-effort transaction " + phase + " diagnostic failure must not deactivate a successfully loaded owner.");
                }
                finally
                {
                    RestorePersistentRoot(previousRoot);
                }
            }
        }

        private static DtmApiRuntime CreateAtomicProbeRuntime(string gameDir, string ownerId, ConfigMenuRegistry menu)
        {
            WriteAtomicProbePackage(gameDir, ownerId, string.Empty);
            return new DtmApiRuntime(new FakeHost(gameDir), menu);
        }

        private static string WriteAtomicProbePackage(string gameDir, string ownerId, string dependenciesJson)
        {
            string modDir = Path.Combine(gameDir, "Mods", ownerId.Replace('.', '_'));
            Directory.CreateDirectory(modDir);
            Assembly probeAssembly = typeof(AtomicOwnerProbeMod).Assembly;
            string probeTargetFramework = probeAssembly
                .GetCustomAttribute<System.Runtime.Versioning.TargetFrameworkAttribute>()?
                .FrameworkName ?? string.Empty;
            Assert(!ReferenceEquals(probeAssembly, typeof(Program).Assembly) &&
                   probeTargetFramework.Equals(".NETStandard,Version=v2.0", StringComparison.Ordinal),
                "Runtime CodeMod probes must remain in their independent netstandard2.0 fixture assembly, never the net8 unit-test host.");
            string assemblyPath = probeAssembly.Location;
            string assemblyName = Path.GetFileName(assemblyPath);
            File.Copy(assemblyPath, Path.Combine(modDir, assemblyName), overwrite: true);
            File.WriteAllText(
                Path.Combine(modDir, "manifest.json"),
                "{ \"Name\": \"Atomic Owner Probe\", \"Author\": \"DTMAPI\", \"Version\": \"1.0.0\", \"UniqueID\": \"" + ownerId + "\", \"EntryDll\": \"" + assemblyName + "\", \"EntryType\": \"" + (typeof(AtomicOwnerProbeMod).FullName ?? nameof(AtomicOwnerProbeMod)) + "\", \"Type\": \"CodeMod\", \"CodeModKind\": \"Strict\"" + dependenciesJson + " }");
            return modDir;
        }

        private static ManifestModel RegisterReservedRuntimeProviderProbe(DtmApiRuntime runtime, string uniqueId, string version)
        {
            var manifest = new ManifestModel
            {
                Name = "Reserved Runtime Provider Probe",
                Author = "DTMAPI",
                Version = version,
                UniqueID = uniqueId,
                Type = "RuntimeApi"
            };
            runtime.RegisterRuntimeApi<IUnitProbeApi>(manifest, new UnitProbeApi(uniqueId));
            return manifest;
        }

        private static void RegistryAndConfigFacadesEnforceOwnerLifetime()
        {
            var registry = new ModRegistryService();
            var provider = new ManifestModel { Name = "Provider", Author = "DTMAPI", Version = "1.0.0", UniqueID = "DTMAPI.Tests.Provider" };
            var consumer = new ManifestModel { Name = "Consumer", Author = "DTMAPI", Version = "1.0.0", UniqueID = "DTMAPI.Tests.Consumer" };
            var spoof = new ManifestModel { Name = "Spoof", Author = "DTMAPI", Version = "1.0.0", UniqueID = "DTMAPI.Tests.Spoof" };
            var dual = new DualProbeApi(provider.UniqueID);
            registry.RegisterApiForOwner<IUnitProbeApi>(provider, dual);
            AssertThrows(() => registry.RegisterApiForOwner<IUnitProbeApi>(provider, new UnitProbeApi("replacement")), "Duplicate provider/contract registration must throw instead of replacing the original API.");
            Assert(ReferenceEquals(registry.GetApi<IUnitProbeApi>(provider.UniqueID), dual), "Duplicate registration failure must preserve the original provider object.");
            registry.RegisterApiForOwner<ISecondProbeApi>(provider, dual);
            Assert(ReferenceEquals(registry.GetApi<ISecondProbeApi>(provider.UniqueID), dual), "One object may register distinct API contracts for the same owner.");

            var menu = new ConfigMenuRegistry();
            var menuProvider = new ManifestModel { Name = "Menu", Author = "DTMAPI", Version = "1.0.0", UniqueID = "DTMAPI.ModConfigMenu" };
            registry.RegisterApiForOwner<IDtmConfigMenuApi>(menuProvider, menu);
            bool consumerActive = true;
            IModRegistry consumerRegistry = registry.CreateOwnerBoundRegistry(consumer, () =>
            {
                if (!consumerActive)
                    throw new InvalidOperationException("consumer inactive");
            });
            IDtmConfigMenuApi facade = consumerRegistry.GetApi<IDtmConfigMenuApi>(menuProvider.UniqueID) ?? throw new InvalidOperationException("Owner-bound config facade missing.");
            Assert(ReferenceEquals(facade, consumerRegistry.GetApi<IDtmConfigMenuApi>(menuProvider.UniqueID)), "Owner-bound API facade should be stable for a consumer/provider/contract tuple.");
            Assert(facade is IDtmConfigMenuKeybindDefaultsApi, "Owner-bound primary config facade should retain optional keybind-default capability.");
            Assert(facade is IOwnerBoundApiFacade, "Owner-bound config facade should support explicit cache deactivation so stale third-party references can't retain its provider and owner graph.");
            AssertThrows(() => facade.Register(spoof, () => { }, () => { }), "Config facade must reject a forged owner manifest.");
            facade.Register(consumer, () => { }, () => { });
            AssertThrows(() => facade.Register(consumer, () => { }, () => { }), "Config pages must reject duplicate registration.");
            registry.RemoveOwner(menuProvider.UniqueID);
            AssertThrows(() => facade.AddParagraph(consumer, () => "stale"), "A stale facade must reject mutations after its provider is inactive.");
            consumerActive = false;
            registry.RemoveOwner(consumer.UniqueID);
            AssertThrows(() => consumerRegistry.IsLoaded(provider.UniqueID), "A stale Registry helper must reject IsLoaded queries after consumer deactivation.");
            AssertThrows(() => consumerRegistry.Get(provider.UniqueID), "A stale Registry helper must reject manifest queries after consumer deactivation.");
            AssertThrows(() => consumerRegistry.GetAll(), "A stale Registry helper must reject registry snapshots after consumer deactivation.");

            string? previousRoot = UseTempPersistentRoot();
            try
            {
                var config = new ConfigService(new RuntimePaths(NewTempGameDir(), NewTempGameDir()), new DiagnosticsService(new RuntimePaths(NewTempGameDir(), NewTempGameDir())));
                bool active = true;
                IConfigHelper bound = config.CreateOwnerBound(consumer, () => { if (!active) throw new InvalidOperationException("inactive"); });
                AssertThrows(() => bound.GetConfigPath(spoof), "Owner-bound config helper must reject another manifest.");
                bound.RegisterMigration<HotLoadProbeConfig>(consumer, _ => { });
                AssertThrows(() => bound.RegisterMigration<HotLoadProbeConfig>(consumer, _ => { }), "Duplicate owner/config migration registration must throw.");
                Assert(config.RemoveOwner(consumer.UniqueID) == 1 && config.CountOwner(consumer.UniqueID) == 0, "Config migration owner cleanup must leave zero roots.");
                active = false;
                AssertThrows(() => bound.GetConfigPath(consumer), "Stale config helper must reject access after owner deactivation.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void StructuredOwnerKeysDoNotCollideOrOverClean()
        {
            var registry = new ModRegistryService();
            var providerOne = new ManifestModel { Name = "Provider One", Author = "DTMAPI", Version = "1.0.0", UniqueID = "C" };
            var providerTwo = new ManifestModel { Name = "Provider Two", Author = "DTMAPI", Version = "1.0.0", UniqueID = "B|C" };
            var consumerOne = new ManifestModel { Name = "Consumer One", Author = "DTMAPI", Version = "1.0.0", UniqueID = "A|B" };
            var consumerTwo = new ManifestModel { Name = "Consumer Two", Author = "DTMAPI", Version = "1.0.0", UniqueID = "A" };
            registry.RegisterApiForOwner<IDtmConfigMenuApi>(providerOne, new ConfigMenuRegistry());
            registry.RegisterApiForOwner<IDtmConfigMenuApi>(providerTwo, new ConfigMenuRegistry());

            IDtmConfigMenuApi first = registry.CreateOwnerBoundRegistry(consumerOne, () => { }).GetApi<IDtmConfigMenuApi>(providerOne.UniqueID)
                ?? throw new InvalidOperationException("First structured-key facade missing.");
            IDtmConfigMenuApi second = registry.CreateOwnerBoundRegistry(consumerTwo, () => { }).GetApi<IDtmConfigMenuApi>(providerTwo.UniqueID)
                ?? throw new InvalidOperationException("Second structured-key facade missing.");
            Assert(!ReferenceEquals(first, second), "Facade keys must distinguish consumer=A|B/provider=C from consumer=A/provider=B|C.");
            registry.RemoveOwner(providerOne.UniqueID);
            second.Register(consumerTwo, () => { }, () => { });

            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string gameDir = NewTempGameDir();
                var paths = new RuntimePaths(gameDir, gameDir);
                var config = new ConfigService(paths, new DiagnosticsService(paths));
                config.RegisterMigration<HotLoadProbeConfig>(consumerOne, _ => { });
                config.RegisterMigration<HotLoadProbeConfig>(consumerTwo, _ => { });
                Assert(config.RemoveOwner(consumerTwo.UniqueID) == 1, "Removing owner A should remove exactly its migration.");
                Assert(config.CountOwner(consumerOne.UniqueID) == 1, "Removing owner A must not prefix-match and remove owner A|B.");
                Assert(config.RemoveOwner(consumerOne.UniqueID) == 1 && config.TotalMigrationCount == 0, "Structured migration keys should still clean the exact pipe-containing owner.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void InputNativeEdgeLatchRetainsAndConsumesShortTapOnce()
        {
            ReflectedUnityInput.ClearTransientState();
            var samples = new[] { new InputButtonSample("F6", false, true, true) };
            ReflectedUnityInput.LatchInputSamplesForTest(samples);

            InputButtonSample first = ReflectedUnityInput.SampleButtonCached("F6");
            Assert(first.PressedEdge && first.ReleasedEdge && !first.IsDownNow, "The frame latch should retain both edges of a short tap until Core consumes it.");

            InputButtonSample consumed = ReflectedUnityInput.SampleButtonCached("F6");
            Assert(!consumed.PressedEdge && !consumed.ReleasedEdge, "A latched edge should be consumed exactly once.");

            ReflectedUnityInput.LatchInputSamplesForTest(samples);
            ReflectedUnityInput.LatchInputSamplesForTest(new[] { new InputButtonSample("F7", false, false, false) });
            InputButtonSample expired = ReflectedUnityInput.SampleButtonCached("F6");
            Assert(!expired.PressedEdge && !expired.ReleasedEdge, "A button omitted by the next watched frame should not retain a stale edge.");
            ReflectedUnityInput.ClearTransientState();
        }

        private static void InputNativeEdgeLatchRejectsDuplicateSourcesAndHeldPress()
        {
            ReflectedUnityInput.ClearTransientState();
            bool firstSource = ReflectedUnityInput.LatchInputSamplesForFrameForTest(
                new[] { new InputButtonSample("F6", true, true, false) },
                100);
            bool duplicateSource = ReflectedUnityInput.LatchInputSamplesForFrameForTest(
                new[] { new InputButtonSample("F6", true, true, false) },
                100);
            Assert(firstSource && !duplicateSource, "Only one input source should latch registered buttons for a Unity frame.");

            InputButtonSample first = ReflectedUnityInput.SampleButtonCached("F6");
            Assert(first.PressedEdge && first.IsDownNow, "The first source should deliver the physical press.");

            ReflectedUnityInput.LatchInputSamplesForFrameForTest(
                new[] { new InputButtonSample("F6", true, true, false) },
                101);
            InputButtonSample repeated = ReflectedUnityInput.SampleButtonCached("F6");
            Assert(!repeated.PressedEdge && repeated.IsDownNow, "A repeated backend pressed flag before release must not become a second physical press.");

            ReflectedUnityInput.LatchInputSamplesForFrameForTest(
                new[] { new InputButtonSample("F6", false, false, true) },
                102);
            InputButtonSample released = ReflectedUnityInput.SampleButtonCached("F6");
            Assert(released.ReleasedEdge && !released.IsDownNow, "The held cycle should close on release.");

            ReflectedUnityInput.LatchInputSamplesForFrameForTest(
                new[] { new InputButtonSample("F6", true, true, false) },
                103);
            InputButtonSample nextPress = ReflectedUnityInput.SampleButtonCached("F6");
            Assert(nextPress.PressedEdge && nextPress.IsDownNow, "A new press after release must still dispatch normally.");
            ReflectedUnityInput.ClearTransientState();
        }

        private static void InputHelperSnapshotMethodsSupportKeybindLists()
        {
            var input = new InputService(() => true);
            IInputHelper owner = input.CreateOwnerBound("DTMAPI.Tests.HelperSnapshot");
            DtmKeybindList toggle = DtmKeybindList.Parse("Ctrl+F6");

            input.RecordFrame(
                DtmInputScope.Gameplay,
                new[]
                {
                    new InputButtonSample("LeftControl", true, true, false),
                    new InputButtonSample("F6", true, true, false)
                },
                _ => true,
                _ => { },
                _ => { },
                _ => { },
                _ => { });

            DtmButtonState f6 = owner.GetState(DtmButton.Parse("F6"));
            Assert(f6.Button.Equals(DtmButton.Parse("F6")) && f6.IsDown && f6.WasPressed && !f6.WasReleased, "IInputHelper.GetState should expose typed button down/pressed/released state.");
            Assert(toggle.IsDown(owner), "DtmKeybindList.IsDown(input) should match generic modifier aliases against physical side keys.");
            Assert(toggle.JustPressed(owner), "DtmKeybindList.JustPressed(input) should detect a pressed chord through the helper snapshot.");
            Assert(!toggle.JustReleased(owner), "Pressed chord should not report released in the same frame.");
            Assert(!DtmKeybindList.None.IsDown(owner) && !DtmKeybindList.None.JustPressed(owner) && !DtmKeybindList.None.JustReleased(owner), "None keybind lists should remain inert for helper-friendly methods.");

            input.ClearFrame();
            input.RecordFrame(
                DtmInputScope.Gameplay,
                new[]
                {
                    new InputButtonSample("LeftControl", true, false, false),
                    new InputButtonSample("F6", false, false, true)
                },
                _ => true,
                _ => { },
                _ => { },
                _ => { },
                _ => { });

            Assert(!owner.GetState(DtmButton.Parse("F6")).IsDown && owner.WasReleased(DtmButton.Parse("F6")), "IInputHelper.WasReleased(DtmButton) should expose typed release edges.");
            Assert(toggle.JustReleased(owner), "DtmKeybindList.JustReleased(input) should detect a chord release while the modifier is still down.");

            input.ClearTransientState();
            input.RecordFrame(
                DtmInputScope.Gameplay,
                new[]
                {
                    new InputButtonSample("RightShift", true, true, false),
                    new InputButtonSample("A", true, true, false)
                },
                _ => true,
                _ => { },
                _ => { },
                _ => { },
                _ => { });
            Assert(DtmKeybindList.Parse("Shift+A").IsDown(owner), "Generic Shift aliases should match either physical shift key through helper-friendly keybind queries.");
        }

        private static void InputLocalSnapshotQueriesSampleNextFrameWithoutRegisteredRoots()
        {
            var input = new InputService(() => true);
            IInputHelper owner = input.CreateOwnerBound("DTMAPI.Tests.LocalSnapshot");
            DtmKeybindList toggle = DtmKeybindList.Parse("F6");

            Assert(input.GetRegisteredButtons().Count == 0, "Local snapshot helper queries should not create registered input roots.");
            Assert(input.GetButtonsToSample(DtmInputScope.Gameplay).Count == 0, "No local snapshot button should be sampled until a mod queries it.");

            Assert(!toggle.JustPressed(owner), "An unobserved local snapshot key should be false on the warm-up frame.");
            input.ClearFrame();
            Assert(input.GetRegisteredButtons().Count == 0, "Warm-up local snapshot queries should still not create registered roots.");
            Assert(input.GetButtonsToSample(DtmInputScope.Gameplay).SequenceEqual(new[] { "F6" }), "A helper query should request the key for the next input frame.");

            input.RecordFrame(
                DtmInputScope.Gameplay,
                new[] { new InputButtonSample("F6", true, true, false) },
                _ => true,
                _ => { },
                _ => { },
                _ => { },
                _ => { });
            Assert(toggle.JustPressed(owner), "Local snapshot keybind helpers should consume sampled pressed edges without KeybindPressed registration.");
            Assert(input.GetRegisteredButtons().Count == 0, "Local snapshot keybind helpers should remain absent from the registered button union.");

            int removed = input.RemoveOwner("DTMAPI.Tests.LocalSnapshot");
            Assert(removed == 1, "Owner cleanup should remove local snapshot button watches.");
            Assert(
                input.GetRegisteredButtons().Count == 0 &&
                input.GetButtonsToSample(DtmInputScope.Gameplay).SequenceEqual(new[] { "F6" }),
                "Owner cleanup should remove the watch/root immediately while retaining a physically held button only until its release is sampled.");
            input.RecordFrame(
                DtmInputScope.Gameplay,
                new[] { new InputButtonSample("F6", false, false, true) },
                _ => true,
                _ => { },
                _ => { },
                _ => { },
                _ => { });
            input.ClearFrame();
            Assert(
                input.GetButtonsToSample(DtmInputScope.Gameplay).Count == 0,
                "A released button with no owner watch, rearm requirement or settlement ledger must leave the physical sample set.");
        }

        private static void InactiveOwnerBoundInputQueriesCannotRecreateLocalWatch()
        {
            const string ownerId = "DTMAPI.Tests.LocalSnapshot.Inactive";
            bool ownerActive = true;
            var input = new InputService(() => true);
            IInputHelper helper = input.CreateOwnerBound(ownerId, () =>
            {
                if (!ownerActive)
                    throw new InvalidOperationException("owner inactive");
            });
            DtmButton button = DtmButton.Parse("F6");

            helper.GetState(button);
            InputOwnerSnapshot active = input.GetOwnerSnapshot();
            Assert(active.OwnerCount == 1 && active.OwnerRegistrations == 1 && active.ButtonsByOwner.TryGetValue(ownerId, out int activeRoots) && activeRoots == 1, "Owner root counting must include a demand-local typed input watch.");
            Assert(input.GetLocalSnapshotDiagnostics().OwnerCount == 1 && input.GetLocalSnapshotDiagnostics().WatchCount == 1, "Typed input warm-up should create exactly one owner-local watch.");

            Assert(input.RemoveOwner(ownerId) == 1, "Owner cleanup should remove the demand-local typed input watch.");
            ownerActive = false;
            AssertThrows(() => helper.GetState(button), "A stale owner-bound input helper must reject typed state queries after deactivation.");
            AssertThrows(() => DtmKeybindList.Parse("F6").JustPressed(helper), "A stale owner-bound input helper must reject typed keybind-list queries after deactivation.");

            InputOwnerSnapshot inactive = input.GetOwnerSnapshot();
            InputLocalSnapshotDiagnostics diagnostics = input.GetLocalSnapshotDiagnostics();
            Assert(inactive.OwnerCount == 0 && inactive.OwnerRegistrations == 0 && !inactive.ButtonsByOwner.ContainsKey(ownerId) && diagnostics.OwnerCount == 0 && diagnostics.WatchCount == 0, "Rejected stale typed input queries must not recreate an owner-local snapshot root.");
            Assert(input.GetButtonsToSample(DtmInputScope.Gameplay).Count == 0, "Rejected stale typed input queries must not re-add a button to the sampled union.");
        }

        private static void InputLocalSnapshotWarmPathDoesNotAllocate()
        {
            var input = new InputService(() => true);
            IInputHelper owner = input.CreateOwnerBound("DTMAPI.Tests.LocalSnapshot.Allocation");
            DtmKeybindList toggle = DtmKeybindList.Parse("F6");
            var samples = new[] { new InputButtonSample("F6", false, false, false) };
            Func<DtmInputScope, bool> allow = _ => true;
            Action<string> ignoreButton = _ => { };
            Action<InputKeybindDispatch> ignoreKeybind = _ => { };

            toggle.JustPressed(owner);
            input.ClearFrame();
            for (int index = 0; index < 256; index++)
            {
                Assert(input.GetButtonsToSample(DtmInputScope.Gameplay).Count == 1, "Warm local snapshot should keep exactly one sampled button.");
                input.RecordFrame(DtmInputScope.Gameplay, samples, allow, ignoreButton, ignoreButton, ignoreKeybind, ignoreKeybind);
                toggle.JustPressed(owner);
                input.ClearFrame();
            }

            InputLocalSnapshotDiagnostics before = input.GetLocalSnapshotDiagnostics();
            IReadOnlyList<string> cachedBefore = input.GetButtonsToSample(DtmInputScope.Gameplay);
            GC.Collect();
            GC.WaitForPendingFinalizers();
            GC.Collect();
            long allocatedBefore = GC.GetAllocatedBytesForCurrentThread();
            for (int index = 0; index < 10000; index++)
            {
                input.GetButtonsToSample(DtmInputScope.Gameplay);
                input.RecordFrame(DtmInputScope.Gameplay, samples, allow, ignoreButton, ignoreButton, ignoreKeybind, ignoreKeybind);
                toggle.JustPressed(owner);
                input.ClearFrame();
            }
            long allocated = GC.GetAllocatedBytesForCurrentThread() - allocatedBefore;
            InputLocalSnapshotDiagnostics after = input.GetLocalSnapshotDiagnostics();
            IReadOnlyList<string> cachedAfter = input.GetButtonsToSample(DtmInputScope.Gameplay);
            Assert(allocated == 0, "Warm local snapshot polling should allocate zero bytes; allocated=" + allocated.ToString(CultureInfo.InvariantCulture) + ".");
            Assert(ReferenceEquals(cachedBefore, cachedAfter), "Stable local snapshot membership should preserve the cached sampled-button array instance.");
            Assert(before.CacheRebuildCount == after.CacheRebuildCount, "Stable local snapshot membership should not rebuild the active union cache.");
            Assert(after.OwnerCount == 1 && after.WatchCount == 1 && after.ActiveButtonCount == 1, "Warm local snapshot diagnostics should remain bounded to one owner/watch/button.");

            input.ClearFrame();
            Assert(input.GetButtonsToSample(DtmInputScope.Gameplay).Count == 0, "A local snapshot watch not queried in the previous update should leave the active sample union.");
            input.ClearFrame();
            input.ClearFrame();
            InputLocalSnapshotDiagnostics expired = input.GetLocalSnapshotDiagnostics();
            Assert(expired.OwnerCount == 0 && expired.WatchCount == 0 && expired.ExpiredWatchCount == 1, "Dormant local snapshot watches should be pruned after two inactive generations.");
        }

