            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        [MethodImpl(MethodImplOptions.NoInlining)]
        private static WeakReference CreateAndQuarantineCapturedHandler(DtmApiRuntime runtime)
        {
            var payload = new WeakPayload();
            var weak = new WeakReference(payload);
            IEventsHelper events = CreateEventsProxy(runtime, "DTMAPI.Tests.QuarantineWeak");
            events.GameLoop.UpdateTicked += (_, _) =>
            {
                GC.KeepAlive(payload);
                throw new InvalidOperationException("quarantine-weak-probe");
            };
            runtime.Update();
            runtime.Update();
            runtime.Update();
            return weak;
        }

        private static void EventQuarantineOwnerMetadataIsBoundedAndCleanable()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                var runtime = new DtmApiRuntime(new FakeHost(NewTempGameDir()), new ConfigMenuRegistry());
                runtime.Start();
                const int ownerCount = 140;
                WeakReference captured = RegisterQuarantineOwnerStress(runtime, ownerCount);
                runtime.Update();
                runtime.Update();
                runtime.Update();

                EventSlotSnapshot slot = runtime.Events.GetHandlerCleanupSnapshot().Slots.Single(current =>
                    current.EventName == "GameLoop.UpdateTicked");
                Assert(slot.ActiveHandlers == 0 && slot.QuarantinedHandlers == 128, "Only the 128 named quarantine owners should count as current removable roots after all stress delegates are released.");
                Assert(slot.ByOwner.Count == 128 && !slot.ByOwner.ContainsKey("other"), "Overflow quarantine owners must not create a synthetic current-root bucket.");
                Assert(slot.TrimmedQuarantineCount == ownerCount - 128 && runtime.Events.GetHandlerCleanupSnapshot().TrimmedQuarantineCount == ownerCount - 128, "Overflow quarantines should remain only as a bounded historical trimmed scalar.");

                for (int i = 0; i < 8 && captured.IsAlive; i++)
                {
                    GC.Collect();
                    GC.WaitForPendingFinalizers();
                    GC.Collect();
                }
                Assert(!captured.IsAlive, "Bounded multi-owner quarantine must release captured delegates, not just aggregate their failure counts.");

                int trimmedRemoved = runtime.Events.RemoveOwner("DTMAPI.Tests.QuarantineOwner.139");
                EventSlotSnapshot afterTrimmedCleanup = runtime.Events.GetHandlerCleanupSnapshot().Slots.Single(current =>
                    current.EventName == "GameLoop.UpdateTicked");
                Assert(trimmedRemoved == 0 && afterTrimmedCleanup.QuarantinedHandlers == 128 && afterTrimmedCleanup.TrimmedQuarantineCount == ownerCount - 128, "Cleanup of a trimmed historical owner must remove no current root and must not mutate the trimmed scalar.");

                int removed = runtime.Events.RemoveOwner("DTMAPI.Tests.QuarantineOwner.000");
                EventSlotSnapshot afterCleanup = runtime.Events.GetHandlerCleanupSnapshot().Slots.Single(current =>
                    current.EventName == "GameLoop.UpdateTicked");
                Assert(removed == 1 && !afterCleanup.ByOwner.ContainsKey("DTMAPI.Tests.QuarantineOwner.000"), "Owner cleanup should delete its named quarantine aggregate.");
                Assert(afterCleanup.ByOwner.Count == 127 && afterCleanup.QuarantinedHandlers == 127 && afterCleanup.TrimmedQuarantineCount == ownerCount - 128, "Named owner cleanup must remove exactly one current root without changing bounded historical trimmed counts.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        [MethodImpl(MethodImplOptions.NoInlining)]
        private static WeakReference RegisterQuarantineOwnerStress(DtmApiRuntime runtime, int ownerCount)
        {
            var payload = new WeakPayload();
            var weak = new WeakReference(payload);
            for (int i = 0; i < ownerCount; i++)
            {
                string ownerId = "DTMAPI.Tests.QuarantineOwner." + i.ToString("000", CultureInfo.InvariantCulture);
                IEventsHelper events = CreateEventsProxy(runtime, ownerId);
                if (i == 0)
                {
                    events.GameLoop.UpdateTicked += (_, _) =>
                    {
                        GC.KeepAlive(payload);
                        throw new InvalidOperationException("quarantine-owner-captured-probe");
                    };
                }
                else
                {
                    events.GameLoop.UpdateTicked += (_, _) => throw new InvalidOperationException("quarantine-owner-probe");
                }
            }
            return weak;
        }

        private static void SaveAndTitleBoundariesPreserveProcessLifetimeOwnerServices()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                var menu = new ConfigMenuRegistry();
                var runtime = new DtmApiRuntime(new FakeHost(dir), menu);
                runtime.Start();
                var owner = new ManifestModel { Name = "Process Owner", Author = "DTMAPI", Version = "1.0.0", UniqueID = "DTMAPI.Tests.ProcessOwner" };
                CreateEventsProxy(runtime, owner.UniqueID).GameLoop.UpdateTicked += (_, _) => { };
                IInputHelper ownerInput = runtime.Input.CreateOwnerBound(owner.UniqueID);
                ownerInput.RegisterButton("F13");
                runtime.ModRegistry.RegisterApiForOwner<IUnitProbeApi>(owner, new UnitProbeApi(owner.UniqueID));
                runtime.Config.RegisterMigration<HotLoadProbeConfig>(owner, _ => { });
                menu.Register(owner, () => { }, () => { });
                runtime.RecordInputFrame(new[]
                {
                    new InputButtonSample("F13", true, true, false),
                    new InputButtonSample("F14", true, true, false),
                    new InputButtonSample("F15", false, false, true)
                });
                ownerInput.IsDown(DtmButton.Parse("F14"));
                ownerInput.WasReleased(DtmButton.Parse("F15"));
                ownerInput.WasPressed(DtmButton.Parse("F16"));
                Assert(runtime.Input.CountOwnerResources(owner.UniqueID) == 4 && runtime.Input.GetLocalSnapshotDiagnostics().WatchCount == 3, "The SaveLoaded fixture should contain one persistent registration and three transient owner-local snapshot watches.");
                Assert(runtime.Input.IsDown("F13") && runtime.Input.IsDown("F14") && runtime.Input.WasPressed("F13") && runtime.Input.WasPressed("F14") && runtime.Input.WasReleased("F15"), "The SaveLoaded fixture should contain transient down, pressed, and released state.");

                runtime.NotifySaveLoaded(isNewGame: false);

                Assert(runtime.Input.CountOwnerResources(owner.UniqueID) == 1 && runtime.Input.GetLocalSnapshotDiagnostics().WatchCount == 0, "SaveLoaded must remove owner-local snapshot watches while retaining exactly the persistent registration root.");
                Assert(!ownerInput.IsDown("F13") && !ownerInput.IsDown("F14") && !ownerInput.WasPressed("F13") && !ownerInput.WasPressed("F14") && !ownerInput.WasReleased("F15"), "SaveLoaded must hide held/edge state behind neutral rearm without erasing physical truth.");
                Assert(runtime.Input.GetRegisteredButtons().Contains("F13", StringComparer.OrdinalIgnoreCase), "SaveLoaded must preserve persistent input registrations.");
                Assert(runtime.ModRegistry.GetApi<IUnitProbeApi>(owner.UniqueID) != null &&
                    ((IConfigMenuRuntime)menu).GetPage(owner.UniqueID) != null &&
                    runtime.Config.CountOwner(owner.UniqueID) == 1 &&
                    runtime.Events.GetHandlerCleanupSnapshot().Slots.Any(slot => slot.ByOwner.ContainsKey(owner.UniqueID)),
                    "SaveLoaded must preserve process-lifetime Event, API, ConfigPage, and migration services.");

                runtime.RecordInputFrame(new[]
                {
                    new InputButtonSample("F14", true, true, false),
                    new InputButtonSample("F15", false, false, true)
                });
                ownerInput.IsDown(DtmButton.Parse("F14"));
                ownerInput.WasReleased(DtmButton.Parse("F15"));
                ownerInput.WasPressed(DtmButton.Parse("F16"));
                Assert(runtime.Input.CountOwnerResources(owner.UniqueID) == 4 && runtime.Input.GetLocalSnapshotDiagnostics().WatchCount == 3, "Transient input watches should be able to rebuild after SaveLoaded without duplicating the persistent registration.");
                runtime.NotifyReturnedToTitle();

                Assert(runtime.ModRegistry.GetApi<IUnitProbeApi>(owner.UniqueID) != null, "Save/title boundaries must preserve process-lifetime APIs.");
                Assert(((IConfigMenuRuntime)menu).GetPage(owner.UniqueID) != null, "Save/title boundaries must preserve config pages.");
                Assert(runtime.Config.CountOwner(owner.UniqueID) == 1, "Save/title boundaries must preserve config migrations.");
                Assert(runtime.Input.GetRegisteredButtons().Contains("F13", StringComparer.OrdinalIgnoreCase), "Save/title boundaries must preserve persistent input registrations.");
                Assert(runtime.Events.GetHandlerCleanupSnapshot().Slots.Any(slot => slot.ByOwner.ContainsKey(owner.UniqueID)), "Save/title boundaries must preserve event registrations.");
                Assert(runtime.Input.CountOwnerResources(owner.UniqueID) == 1 && runtime.Input.GetLocalSnapshotDiagnostics().WatchCount == 0, "ReturnedToTitle must clear rebuilt local snapshot watches while retaining the persistent registration.");
                Assert(!ownerInput.IsDown("F13") && !ownerInput.IsDown("F14") && !ownerInput.WasPressed("F13") && !ownerInput.WasPressed("F14") && !ownerInput.WasReleased("F15"), "ReturnedToTitle must require neutral before exposing a new input cycle.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void DiagnosticGraphsAndLogOnceKeysAreBounded()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                var paths = new RuntimePaths(dir, dir);
                var diagnostics = new DiagnosticsService(paths);
                diagnostics.SetHookStatus("other/trimmed", "user-value", "test", "ordinary hook ID");
                diagnostics.SetFeatureStatus("other/trimmed", "user-value", "test", true, 0, string.Empty, "ordinary feature ID");
                for (int i = 0; i < 700; i++)
                {
                    diagnostics.SetHookStatus("hook-" + i, "ok", "test", string.Empty);
                    diagnostics.SetFeatureStatus("feature-" + i, "ok", "test", true, 0, string.Empty, string.Empty);
                    diagnostics.RecordError("owner-" + i, "message-" + i, "scalar");
                }
                Assert(diagnostics.RetainedHookStatusCount <= 512 && diagnostics.TrimmedHookStatusCount > 0, "Hook status graph must have a fixed retained cap and trimmed aggregate.");
                Assert(diagnostics.RetainedFeatureStatusCount <= 512 && diagnostics.TrimmedFeatureStatusCount > 0, "Feature status graph must have a fixed retained cap and trimmed aggregate.");
                Assert(diagnostics.RetainedDiagnosticAggregateCount <= 512 && diagnostics.TrimmedDiagnosticAggregateCount > 0, "Diagnostic aggregate graph must have a fixed retained cap and trimmed aggregate.");
                Assert(diagnostics.GetHookStatuses().Any(status => status.HookId == "other/trimmed" && status.Status == "user-value") && diagnostics.GetHookStatuses().Any(status => status.HookId == "other/trimmed" && status.Status == "trimmed"), "Hook overflow aggregation must not overwrite an ordinary caller using the display ID.");
                Assert(diagnostics.GetFeatureStatuses().Any(status => status.FeatureId == "other/trimmed" && status.Status == "user-value") && diagnostics.GetFeatureStatuses().Any(status => status.FeatureId == "other/trimmed" && status.Status == "trimmed"), "Feature overflow aggregation must stay outside the ordinary caller key space.");

                var monitor = new FileMonitor(new FakeHost(dir), "DTMAPI.Tests.LogOnceCap", Path.Combine(dir, "logonce.log"));
                for (int i = 0; i < 400; i++)
                    monitor.LogOnce("key-" + i, "message-" + i);
                Assert(monitor.RetainedLogOnceKeyCount == 256 && monitor.SuppressedLogOnceKeyCount == 144, "Each monitor must retain at most 256 LogOnce keys and count suppressed unique keys.");

                var ledger = new ModOwnerLedgerService();
                ledger.RecordCleanup("owner-success", "GameBridgeOwnerResource", 1, "phase", "failedSteps=none");
                Assert(ledger.GetSnapshot().CleanupFailures == 0, "Successful cleanup details containing a word like failedSteps must not be inferred as a cleanup failure.");
                ledger.RecordCleanup("owner-failure", "GameBridgeOwnerResource", 0, "phase", "explicit failure", success: false);
                Assert(ledger.GetSnapshot().CleanupFailures == 1, "Cleanup failures must be recorded through an explicit structured signal.");
                for (int i = 0; i < 300; i++)
                {
                    ledger.RecordRegistration("owner-" + i, "UniqueKind-" + i, "key", "phase", "cleanup");
                    ledger.RecordNeedsRestart("owner-" + i, "key", "phase", "failure-" + i);
                }
                ModOwnerLedgerSnapshot snapshot = ledger.GetSnapshot();
                Assert(snapshot.Entries.Count == 64 && snapshot.RegistrationCounts.Count == 1 && snapshot.RegistrationCounts.ContainsKey("Other"), "Owner ledger must retain only 64 scalar failures and fixed registration-kind counters.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void DiagnosticRetainedStringsAndTrimmedBytesAreBounded()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                var paths = new RuntimePaths(dir, dir);
                paths.Ensure();
                var diagnostics = new DiagnosticsService(paths);
                string ownerPrefix = new string('O', 4096);
                string messagePrefix = new string('M', 8192);
                string detailsPrefix = new string('D', 16384);
                string ownerA = ownerPrefix + "owner-tail-A";
                string ownerB = ownerPrefix + "owner-tail-B";
                string messageA = messagePrefix + "message-tail-A";
                string messageB = messagePrefix + "message-tail-B";
                string detailsA = detailsPrefix + "details-tail-A";
                string detailsB = detailsPrefix + "details-tail-B";

                var directError = new DtmErrorInfo(ownerA, messageA, detailsA);
                var directWarning = new DtmWarningInfo(ownerA, messageA, detailsA);
                var directHook = new HookStatusInfo(new string('H', 4096), new string('S', 4096), new string('R', 4096), detailsA);
                var directFeature = new DtmFeatureStatusInfo(new string('F', 4096), new string('T', 4096), new string('P', 4096), false, 1, messageA, detailsA);
                Assert(directError.Owner.Length <= BoundedDiagnosticScalar.OwnerIdChars && directError.Message.Length <= BoundedDiagnosticScalar.MessageChars && directError.Details.Length <= BoundedDiagnosticScalar.DetailsChars &&
                    directWarning.Owner.Length <= BoundedDiagnosticScalar.OwnerIdChars && directWarning.Message.Length <= BoundedDiagnosticScalar.MessageChars && directWarning.Details.Length <= BoundedDiagnosticScalar.DetailsChars &&
                    directHook.HookId.Length <= BoundedDiagnosticScalar.IdentifierChars && directHook.Status.Length <= BoundedDiagnosticScalar.ShortTextChars && directHook.Source.Length <= BoundedDiagnosticScalar.ShortTextChars && directHook.Details.Length <= BoundedDiagnosticScalar.DetailsChars &&
                    directFeature.FeatureId.Length <= BoundedDiagnosticScalar.IdentifierChars && directFeature.Status.Length <= BoundedDiagnosticScalar.ShortTextChars && directFeature.LastOperation.Length <= BoundedDiagnosticScalar.ShortTextChars && directFeature.LastError.Length <= BoundedDiagnosticScalar.MessageChars && directFeature.Details.Length <= BoundedDiagnosticScalar.DetailsChars,
                    "Direct diagnostic DTO construction must defensively apply the same centralized scalar bounds as the retained service path.");
                var foreignError = new UnboundedErrorInfo(ownerA, messageA, detailsA);
                var defensiveSnapshot = new DtmDiagnosticsSnapshot(
                    DateTimeOffset.Now,
                    Array.Empty<IDtmLoadedModInfo>(),
                    Array.Empty<IDtmModStatusInfo>(),
                    Enumerable.Repeat<IDtmErrorInfo>(foreignError, BoundedDiagnosticScalar.MaxDiagnosticRows + 25).ToArray(),
                    Array.Empty<IDtmWarningInfo>(),
                    Array.Empty<IHookStatusInfo>(),
                    Array.Empty<IDtmFeatureStatusInfo>(),
                    new string('L', 4096),
                    new string('R', 4096));
                Assert(defensiveSnapshot.Errors.Count == BoundedDiagnosticScalar.MaxDiagnosticRows && !ReferenceEquals(defensiveSnapshot.Errors[0], foreignError), "Diagnostics snapshots must cap and defensively project caller-supplied interface rows instead of retaining their arbitrary object graph.");
                Assert(defensiveSnapshot.Errors.All(error => error.Owner.Length <= BoundedDiagnosticScalar.OwnerIdChars && error.Message.Length <= BoundedDiagnosticScalar.MessageChars && error.Details.Length <= BoundedDiagnosticScalar.DetailsChars) &&
                    defensiveSnapshot.LatestLogPath.Length <= BoundedDiagnosticScalar.DetailsChars && defensiveSnapshot.LatestReportPath.Length <= BoundedDiagnosticScalar.DetailsChars,
                    "Diagnostics snapshot rows and path fields must remain bounded even when a foreign implementation supplies long values.");

                diagnostics.RecordError(ownerA, messageA, detailsA);
                diagnostics.RecordError(ownerB, messageB, detailsB);
                MethodInfo recordWarning = diagnostics.GetType().GetMethod("RecordWarning", BindingFlags.NonPublic | BindingFlags.Instance)
                    ?? throw new InvalidOperationException("DiagnosticsService.RecordWarning should remain available for bounded warning coverage.");
                recordWarning.Invoke(diagnostics, new object[] { ownerA, messageB, detailsA });
                diagnostics.SetHookStatus(new string('H', 4096), new string('S', 4096), new string('R', 4096), detailsA);
                diagnostics.SetFeatureStatus(new string('F', 4096), new string('T', 4096), new string('P', 4096), false, 1, messageA, detailsB);

                IReadOnlyList<IDtmErrorInfo> errors = diagnostics.GetErrors();
                Assert(errors.Count == 2 && errors.All(error =>
                    error.Owner.Length <= BoundedDiagnosticScalar.OwnerIdChars &&
                    error.Message.Length <= BoundedDiagnosticScalar.MessageChars &&
                    error.Details.Length <= BoundedDiagnosticScalar.DetailsChars),
                    "Every retained diagnostic error scalar must stay within its centralized field limit.");
                Assert(errors.All(error => error.Owner.Contains("~[sha256:", StringComparison.Ordinal) && error.Message.Contains("~[sha256:", StringComparison.Ordinal) && error.Details.Contains("~[sha256:", StringComparison.Ordinal)), "Every truncated diagnostic scalar should retain a stable hash suffix.");
                Assert(!string.Equals(errors[0].Owner, errors[1].Owner, StringComparison.Ordinal) && !string.Equals(errors[0].Message, errors[1].Message, StringComparison.Ordinal), "Long values with identical retained prefixes but different tails must remain distinct through their stable hashes.");
                IDtmWarningInfo warning = diagnostics.GetWarnings().Single();
                Assert(warning.Owner.Length <= BoundedDiagnosticScalar.OwnerIdChars && warning.Message.Length <= BoundedDiagnosticScalar.MessageChars && warning.Details.Length <= BoundedDiagnosticScalar.DetailsChars, "Retained warning fields must use the same centralized bounds as errors.");
                Assert(diagnostics.RetainedDiagnosticAggregateCount == 3, "Bounded aggregate keys must distinguish error/warning kind and different long owner/message values without retaining their full input.");

                IHookStatusInfo hook = diagnostics.GetHookStatuses().Single();
                Assert(hook.HookId.Length <= BoundedDiagnosticScalar.IdentifierChars && hook.Status.Length <= BoundedDiagnosticScalar.ShortTextChars && hook.Source.Length <= BoundedDiagnosticScalar.ShortTextChars && hook.Details.Length <= BoundedDiagnosticScalar.DetailsChars, "Hook-status keys and values must use centralized scalar bounds.");
                IDtmFeatureStatusInfo feature = diagnostics.GetFeatureStatuses().Single();
                Assert(feature.FeatureId.Length <= BoundedDiagnosticScalar.IdentifierChars && feature.Status.Length <= BoundedDiagnosticScalar.ShortTextChars && feature.LastOperation.Length <= BoundedDiagnosticScalar.ShortTextChars && feature.LastError.Length <= BoundedDiagnosticScalar.MessageChars && feature.Details.Length <= BoundedDiagnosticScalar.DetailsChars, "Feature-status keys and values must use centralized scalar bounds.");
                Assert(diagnostics.TrimmedDiagnosticBytes > 0, "Diagnostics should expose a positive saturating trimmed-byte count after truncating retained scalars.");

                DiscoveredMod longOwnerMod = CreateDiscoveredContentPack(Path.Combine(dir, "LongOwnerStatus"), ownerA, new string('N', 4096));
                IDtmModStatusInfo longOwnerStatus = RuntimeSnapshotFactory.CreateModStatusSnapshot(
                    new[] { longOwnerMod },
                    Array.Empty<DiscoveredMod>(),
                    diagnostics.GetErrors()).Single();
                Assert(longOwnerStatus.Status == "error" && longOwnerStatus.UniqueID.Length <= BoundedDiagnosticScalar.OwnerIdChars, "A bounded display owner must retain fixed SHA-256 identity association with its full manifest owner in diagnostics status rows.");
                var projectedDiagnostics = new DtmDiagnosticsSnapshot(
                    DateTimeOffset.Now,
                    Array.Empty<IDtmLoadedModInfo>(),
                    Array.Empty<IDtmModStatusInfo>(),
                    diagnostics.GetErrors(),
                    diagnostics.GetWarnings(),
                    diagnostics.GetHookStatuses(),
                    diagnostics.GetFeatureStatuses(),
                    string.Empty,
                    string.Empty);
                IDtmModStatusInfo projectedLongOwnerStatus = RuntimeSnapshotFactory.CreateModStatusSnapshot(
                    new[] { longOwnerMod },
                    Array.Empty<DiscoveredMod>(),
                    projectedDiagnostics.Errors).Single();
                Assert(projectedLongOwnerStatus.Status == "error", "Defensive snapshot projection must preserve the full-owner correlation identity of retained diagnostic rows.");
                Assert(longOwnerStatus.Name.Length <= BoundedDiagnosticScalar.MessageChars && longOwnerStatus.Reason.Length <= BoundedDiagnosticScalar.DetailsChars && longOwnerStatus.ManifestPath.Length <= BoundedDiagnosticScalar.DetailsChars && longOwnerStatus.RootPath.Length <= BoundedDiagnosticScalar.DetailsChars, "Diagnostics snapshot model fields must remain bounded end-to-end.");
                var loadedInfo = new DtmLoadedModInfo(new ManifestModel
                {
                    UniqueID = ownerA,
                    Name = new string('L', 4096),
                    Version = new string('V', 4096),
                    Type = new string('T', 4096),
                    EntryType = new string('E', 4096)
                });
                Assert(loadedInfo.UniqueID.Length <= BoundedDiagnosticScalar.OwnerIdChars && loadedInfo.Name.Length <= BoundedDiagnosticScalar.MessageChars && loadedInfo.Version.Length <= BoundedDiagnosticScalar.IdentifierChars && loadedInfo.Type.Length <= BoundedDiagnosticScalar.IdentifierChars && loadedInfo.EntryType.Length <= BoundedDiagnosticScalar.MessageChars, "Loaded-Mod diagnostic snapshot fields must use the same fixed scalar bounds.");

                long firstTrimmed = 0;
                long secondTrimmed = 0;
                string firstBounded = BoundedDiagnosticScalar.Sanitize(detailsA, BoundedDiagnosticScalar.MessageChars, ref firstTrimmed);
                string secondBounded = BoundedDiagnosticScalar.Sanitize(detailsA, BoundedDiagnosticScalar.MessageChars, ref secondTrimmed);
                Assert(firstBounded == secondBounded && firstTrimmed == secondTrimmed && firstTrimmed == (long)(detailsA.Length - BoundedDiagnosticScalar.MessageChars) * sizeof(char), "The centralized sanitizer should produce a deterministic hash suffix and exact UTF-16 trimmed-byte count.");
                long streamedTrimmed = 0;
                string streamedBounded;
                using (var reader = new StringReader(detailsA))
                    streamedBounded = BoundedDiagnosticScalar.Sanitize(reader, BoundedDiagnosticScalar.MessageChars, ref streamedTrimmed);
                Assert(streamedBounded == firstBounded && streamedTrimmed == firstTrimmed, "Streaming pointer-file truncation must match the centralized scalar hash and trimmed-byte accounting without retaining the full input.");

                string latestLogTail = "latest-log-tail";
                string latestReportTail = "latest-report-tail";
                string installVersionTail = "install-version-tail";
                diagnostics.LatestLogPath = new string('L', 4096) + latestLogTail;
                File.WriteAllText(Path.Combine(paths.ReportsPath, "latest-report.txt"), new string('R', 4096) + latestReportTail);
                File.WriteAllText(Path.Combine(paths.DtmApiPath, "install-state.json"), "{\"DTMAPIVersion\":\"" + new string('V', 4096) + installVersionTail + "\"}");
                MethodInfo buildSummary = typeof(DiagnosticsService).GetMethod("BuildSummary", BindingFlags.NonPublic | BindingFlags.Instance)
                    ?? throw new InvalidOperationException("DiagnosticsService.BuildSummary should remain available for bounded summary coverage.");
                string pathAndStateSummary = (string)(buildSummary.Invoke(diagnostics, new object[] { string.Empty }) ?? string.Empty);
                Assert(pathAndStateSummary.Length <= BoundedDiagnosticScalar.ReportSummaryChars && pathAndStateSummary.Contains("~[sha256:", StringComparison.Ordinal), "Diagnostic summary path and install-state scalars must be bounded with stable hash suffixes.");
                Assert(!pathAndStateSummary.Contains(latestLogTail, StringComparison.Ordinal) && !pathAndStateSummary.Contains(latestReportTail, StringComparison.Ordinal) && !pathAndStateSummary.Contains(installVersionTail, StringComparison.Ordinal), "Diagnostic summary must not retain discarded path or install-state tails.");
                diagnostics.LatestLogPath = string.Empty;
                for (int i = 0; i < 300; i++)
                    diagnostics.RecordError("summary-owner", "summary-message", new string('Z', BoundedDiagnosticScalar.DetailsChars));

                string runtimeContext = new string('X', BoundedDiagnosticScalar.RuntimeContextChars + 4096) + "runtime-context-tail";
                string report = diagnostics.ExportLogs(runtimeContext);
                string summary = ReadZipText(report, "dtmapi-summary.txt");
                string boundedContext = ReadZipText(report, "DTMAPI-runtime-context.txt");
                Assert(summary.Length <= BoundedDiagnosticScalar.ReportSummaryChars && summary.Contains("DiagnosticsScalarTrimmedBytes: ", StringComparison.Ordinal) && summary.Contains("DiagnosticsSummaryTrimmedBytes: ", StringComparison.Ordinal) && !summary.Contains("DiagnosticsSummaryTrimmedBytes: 0000000000000000000.", StringComparison.Ordinal) && summary.Contains("~[sha256:", StringComparison.Ordinal), "Diagnostic reports should expose scalar and total-summary trimming while retaining a fixed total character budget and hash suffix.");
                Assert(!summary.Contains("owner-tail-A", StringComparison.Ordinal) && !summary.Contains("message-tail-A", StringComparison.Ordinal) && !summary.Contains("details-tail-A", StringComparison.Ordinal), "Diagnostic reports must not retain discarded scalar tails.");
                Assert(boundedContext.Length <= BoundedDiagnosticScalar.RuntimeContextChars && boundedContext.Contains("~[sha256:", StringComparison.Ordinal) && !boundedContext.Contains("runtime-context-tail", StringComparison.Ordinal), "The exported runtime context must have a fixed total character bound and hash the discarded tail.");

                var ledger = new ModOwnerLedgerService();
                ledger.RecordNeedsRestart(ownerA, messageA, new string('P', 4096), detailsA);
                ledger.RecordCleanup(ownerB, "GameBridgeOwnerResource", 0, new string('Q', 4096), detailsB, success: false);
                ledger.RecordConfigPreview(ownerA, new string('I', 4096), new string('K', 4096), new string('C', 4096), false, detailsB);
                ModOwnerLedgerSnapshot ledgerSnapshot = ledger.GetSnapshot();

                Assert(ledgerSnapshot.Entries.Count == 3 && ledgerSnapshot.Entries.All(entry =>
                    entry.OwnerId.Length <= BoundedDiagnosticScalar.OwnerIdChars &&
                    entry.TransactionId.Length <= BoundedDiagnosticScalar.IdentifierChars &&
                    entry.Kind.Length <= BoundedDiagnosticScalar.IdentifierChars &&
                    entry.Key.Length <= BoundedDiagnosticScalar.ShortTextChars &&
                    entry.Phase.Length <= BoundedDiagnosticScalar.ShortTextChars &&
                    entry.Status.Length <= BoundedDiagnosticScalar.IdentifierChars &&
                    entry.RollbackResult.Length <= BoundedDiagnosticScalar.DetailsChars),
                    "Every retained owner-ledger failure field must stay within the centralized scalar limits.");
                Assert(ledgerSnapshot.ConfigPreviewAggregates.Single().Kind.Length <= BoundedDiagnosticScalar.IdentifierChars && ledgerSnapshot.ConfigPreviewAggregates.Single().Operation.Length <= BoundedDiagnosticScalar.ShortTextChars, "Config-preview aggregate keys must be bounded before dictionary retention.");
                Assert(ledgerSnapshot.TrimmedBytes > 0 && ledgerSnapshot.FormatSummary().Contains("trimmedBytes=" + ledgerSnapshot.TrimmedBytes.ToString(CultureInfo.InvariantCulture), StringComparison.Ordinal), "Owner-ledger snapshots should report their saturating trimmed-byte count.");
                Assert(ledgerSnapshot.Entries.All(entry => entry.OwnerId.Contains("~[sha256:", StringComparison.Ordinal) || entry.RollbackResult.Contains("~[sha256:", StringComparison.Ordinal)), "Owner-ledger truncation should preserve a stable hash without retaining discarded tails.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void ConfigPreviewAuditRecordsApplyAndRestore()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                var menu = new ConfigMenuRegistry();
                IConfigMenuRuntime menuRuntime = menu;
                var runtime = new DtmApiRuntime(new FakeHost(dir), menu);
                IManifest manifest = new ManifestModel
                {
                    Name = "Preview Audit",
                    Author = "DTMAPI",
                    Version = "1.0.0",
                    UniqueID = "DTMAPI.Tests.PreviewAudit"
                };
                bool value = false;
                menu.Register(manifest, () => { }, () => { });
                menu.AddBoolOption(manifest, () => "Preview", () => "", () => value, next => value = next);
                IConfigMenuPage page = menuRuntime.GetPage(manifest.UniqueID) ?? throw new InvalidOperationException("Preview audit page should exist.");
                menuRuntime.BeginEditing(manifest.UniqueID);
                Assert(page.Items[0].TrySetPendingValue("true", out _), "Preview audit bool option should accept pending true.");

                for (int i = 0; i < 200; i++)
                {
                    using (menuRuntime.PreviewPendingValues(page))
                    {
                        Assert(value, "Preview should still apply the pending value while auditing.");
                    }
                    Assert(!value, "Preview scope should still restore the original value.");
                }

                ModOwnerLedgerSnapshot snapshot = runtime.ModOwnerLedgerSnapshot;
                Assert(snapshot.ConfigPreviewObservedCount == 400, "Config preview audit should count apply and restore observations.");
                Assert(snapshot.ConfigPreviewAggregates.Count == 2, "Repeated successful previews should collapse into stable apply/restore aggregate records.");
                Assert(snapshot.Entries.All(e => !e.Kind.Equals("ConfigPreview", StringComparison.OrdinalIgnoreCase)), "Successful config previews should not grow the retained owner-entry list.");
                Assert(snapshot.ConfigPreviewWarningCount == 0 && snapshot.RecentConfigPreviewFailureCount == 0, "Successful preview aggregation should not retain failure samples.");
                Assert(runtime.Diagnostics.GetFeatureStatuses().Any(f => f.FeatureId == "Refactor.ConfigPreviewAudit" && f.Status == "observing"), "Config preview audit should publish an observing feature status.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void EventRemoveIsOwnerBound()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                IEventsHelper ownerA = CreateEventsProxy(runtime, "DTMAPI.Tests.OwnerA");
                IEventsHelper ownerB = CreateEventsProxy(runtime, "DTMAPI.Tests.OwnerB");
                int updateCalls = 0;
                EventHandler<UpdateTickedEventArgs> sharedHandler = (_, _) => updateCalls++;

                ownerA.GameLoop.UpdateTicked += sharedHandler;
                ownerB.GameLoop.UpdateTicked += sharedHandler;
                ownerA.GameLoop.UpdateTicked -= sharedHandler;

                runtime.Start();
                runtime.Update();
                Assert(updateCalls == 1, "Owner A removing a shared delegate must not remove Owner B's event subscription.");

                ownerB.GameLoop.UpdateTicked -= sharedHandler;
                runtime.Update();
                Assert(updateCalls == 1, "Owner B removing its own delegate should remove the remaining subscription.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void BadConfigJsonIsBackedUpAndDefaultedWithTempFileWrites()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                runtime.Start();
                IConfigHelper config = GetConfig(runtime);
                IManifest manifest = new ManifestModel
                {
                    Name = "Bad Config",
                    Author = "DTMAPI",
                    Version = "1.0.0",
                    UniqueID = "DTMAPI.Tests.BadConfig"
                };
                string path = config.GetConfigPath(manifest);
                Directory.CreateDirectory(Path.GetDirectoryName(path) ?? ".");
                File.WriteAllText(path, "{ this is not valid json");

                SampleConfig restored = config.ReadConfig<SampleConfig>(manifest);
                Assert(restored.Enabled && restored.Count == 7, "Bad config JSON should restore default config values.");
                Assert(Directory.GetFiles(Path.GetDirectoryName(path) ?? ".", Path.GetFileName(path) + ".invalid-*.bak").Length == 1, "Bad config JSON should be backed up.");
                Assert(runtime.CreateSnapshot().Errors.Any(e => e.Owner == manifest.UniqueID && e.Message.Contains("配置 JSON 损坏")), "Bad config JSON should be diagnosed.");

                restored.Count = 11;
                config.WriteConfig(manifest, restored);
                Assert(config.ReadConfig<SampleConfig>(manifest).Count == 11, "Config writes should round-trip after recovery.");
                Assert(Directory.GetFiles(Path.GetDirectoryName(path) ?? ".", "*.tmp").Length == 0, "Config writes should not leave temp files behind.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void OffThreadTimerFallbackUpdateDoesNotDispatchOrdinaryModUpdates()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                IEventsHelper events = CreateEventsProxy(runtime, "DTMAPI.Tests.TimerFallback");
                int updates = 0;
                events.GameLoop.UpdateTicked += (_, _) => updates++;
                runtime.Start();

                Exception? threadError = null;
                var thread = new Thread(() =>
                {
                    try
                    {
                        runtime.Update();
                    }
                    catch (Exception ex)
                    {
                        threadError = ex;
                    }
                });
                thread.Start();
                thread.Join();
                if (threadError != null)
                    throw threadError;
                Assert(updates == 0, "Off-thread TimerFallback update must not dispatch ordinary UpdateTicked callbacks.");

                runtime.Update();
                Assert(updates == 1, "Runtime-thread update should still dispatch ordinary UpdateTicked callbacks.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void ConfigMenuEditsSaveCancelAndDetectConflicts()
        {
            var menu = new ConfigMenuRegistry();
            IConfigMenuRuntime menuRuntime = menu;
            IManifest manifest = new ManifestModel
            {
                Name = "Menu Test",
                Author = "DTMAPI",
                Version = "1.0.0",
                UniqueID = "DTMAPI.Tests.Menu"
            };
            bool enabled = false;
            double multiplier = 1.0;
            string label = "before";
            string choice = "Safe";
            string keybind = "F10";
            string alternateKeybind = "F9";
            int saved = 0;
            int reset = 0;

            menu.Register(manifest, () =>
            {
                reset++;
                enabled = false;
                multiplier = 1.0;
                label = "default";
                choice = "Safe";
                keybind = "F10";
            }, () => saved++);
            menu.AddBoolOption(manifest, () => "Enabled", () => "", () => enabled, value => enabled = value);
            menu.AddNumberOption(manifest, () => "Multiplier", () => "", () => multiplier, value => multiplier = value, 1, 4, 0.5);
            menu.AddTextOption(manifest, () => "Label", () => "", () => label, value => label = value);
            menu.AddChoiceOption(manifest, () => "Choice", () => "", () => choice, value => choice = value, new[] { "Safe", "Fast" });
            menu.AddKeybindOption(manifest, () => "Toggle", () => "", () => keybind, value => keybind = value);
            menu.AddKeybindOption(manifest, () => "Alternate", () => "", () => alternateKeybind, value => alternateKeybind = value);

            IConfigMenuPage page = menuRuntime.GetPage(manifest.UniqueID) ?? throw new InvalidOperationException("Page should exist.");
            menuRuntime.BeginEditing(manifest.UniqueID);
            Assert(page.Items[0].TrySetPendingValue("true", out _), "Bool option should accept true.");
            Assert(page.Items[1].TrySetPendingValue("3.25", out _), "Number option should accept numeric input.");
            Assert(page.Items[2].TrySetPendingValue("after", out _), "Text option should accept text input.");
            Assert(page.Items[3].TrySetPendingValue("Fast", out _), "Choice option should accept known choices.");
            Assert(page.HasPendingChanges, "Pending edits should be tracked.");

            menuRuntime.Cancel(manifest.UniqueID);
            Assert(!enabled && multiplier == 1.0 && label == "before" && choice == "Safe", "Cancel should discard pending edits.");

            menuRuntime.BeginEditing(manifest.UniqueID);
            page.Items[0].TrySetPendingValue("true", out _);
            page.Items[1].TrySetPendingValue("3.25", out _);
            page.Items[2].TrySetPendingValue("after", out _);
            page.Items[3].TrySetPendingValue("Fast", out _);
            menuRuntime.Save(manifest.UniqueID);
            Assert(saved == 1, "Save callback should run.");
            Assert(enabled && Math.Abs(multiplier - 3.5) < 0.001 && label == "after" && choice == "Fast", "Save should apply pending values.");

            menuRuntime.Reset(manifest.UniqueID);
            Assert(reset == 1, "Reset callback should run.");
            Assert(page.HasPendingChanges, "Reset should remain pending until save.");
            menuRuntime.Cancel(manifest.UniqueID);
            Assert(enabled && Math.Abs(multiplier - 3.5) < 0.001 && label == "after" && choice == "Fast", "Cancel after reset should restore committed values.");

            menuRuntime.BeginEditing(manifest.UniqueID);
            Assert(page.Items[4].TrySetPendingValue("Plus", out _), "Keybind option should accept Plus aliases.");
            Assert(page.Items[5].TrySetPendingValue("Equals", out _), "Keybind option should accept Equals aliases.");
            string aliasConflict = menu.GetKeybindConflicts(manifest.UniqueID).Single();
            Assert(aliasConflict.StartsWith("按键冲突：Equals", StringComparison.Ordinal), "Plus/Equals aliases should conflict by canonical physical key.");

            Assert(page.Items[4].TrySetPendingValue("LeftControl+F6", out _), "Keybind option should accept explicit left Control chords.");
            Assert(page.Items[5].TrySetPendingValue("RightControl+F6", out _), "Keybind option should accept explicit right Control chords.");
            Assert(menu.GetKeybindConflicts(manifest.UniqueID).Count == 0, "Left and right physical modifiers should not conflict with each other.");

            Assert(page.Items[4].TrySetPendingValue("Ctrl+F6", out _), "Keybind option should accept generic Control chords.");
            Assert(page.Items[5].TrySetPendingValue("LeftControl+F6", out _), "Keybind option should accept side-specific Control chords.");
            string genericConflict = menu.GetKeybindConflicts(manifest.UniqueID).Single();
            Assert(genericConflict.StartsWith("按键冲突：LeftControl+F6", StringComparison.Ordinal), "Generic Control chords should conflict with either physical side.");

            Assert(page.Items[4].TrySetPendingValue("F9", out _), "Keybind option should accept captured keys.");
            Assert(page.Items[5].TrySetPendingValue("F9", out _), "Keybind option should accept repeated captured keys.");
            string conflict = menu.GetKeybindConflicts(manifest.UniqueID).Single();
            Assert(conflict.StartsWith("按键冲突：F9", StringComparison.Ordinal), "Duplicate keybinds should be reported with Chinese-first conflict text.");
            bool conflictBlocked = false;
            try
            {
                menuRuntime.Save(manifest.UniqueID);
            }
            catch (InvalidOperationException)
            {
                conflictBlocked = true;
            }
            Assert(conflictBlocked, "Save should block keybind conflicts.");
        }

        private static void ConfigMenuCallbackFailuresRollbackAndStayInspectable()
        {
            var menu = new ConfigMenuRegistry();
            IConfigMenuRuntime menuRuntime = menu;
            IManifest manifest = new ManifestModel
            {
                Name = "Menu Failure Test",
                Author = "DTMAPI",
                Version = "1.0.0",
                UniqueID = "DTMAPI.Tests.MenuFailure"
            };

            bool first = false;
            bool second = false;
            bool failSecondSetter = true;
            bool failSave = false;
            int saveCalls = 0;
            menu.Register(manifest, () => { }, () =>
            {
                saveCalls++;
                if (failSave)
                    throw new InvalidOperationException("save-boom");
            });
            menu.AddBoolOption(manifest, () => "First", () => "", () => first, value => first = value);
            menu.AddBoolOption(manifest, () => "Second", () => "", () => second, value =>
            {
                if (failSecondSetter && value)
                    throw new InvalidOperationException("setter-boom");
                second = value;
            });

            IConfigMenuPage page = menuRuntime.GetPage(manifest.UniqueID) ?? throw new InvalidOperationException("Page should exist.");
            menuRuntime.BeginEditing(manifest.UniqueID);
            Assert(page.Items[0].TrySetPendingValue("true", out _), "First option should accept true.");
            Assert(page.Items[1].TrySetPendingValue("true", out _), "Second option should accept true.");
            AssertThrows(() => menuRuntime.Save(manifest.UniqueID), "Setter failure should reject save.");
            Assert(!first && !second && saveCalls == 0, "Setter failure should roll back prior applied values and skip save callback.");
            Assert(page.Items[1].ValidationError.Contains("setter-boom"), "Failing setter should remain visible on the config item.");
            Assert(page.HasPendingChanges, "Failed save should keep pending edits inspectable.");

            failSecondSetter = false;
            failSave = true;
            AssertThrows(() => menuRuntime.Save(manifest.UniqueID), "Save callback failure should reject save.");
            Assert(!first && !second && saveCalls == 1, "Save callback failure should roll back applied pending values.");
            Assert(page.HasPendingChanges, "Failed save callback should keep pending edits inspectable.");

            failSave = false;
            menuRuntime.Save(manifest.UniqueID);
            Assert(first && second && saveCalls == 2 && !page.HasPendingChanges, "Successful retry should apply and commit retained pending values.");

            var previewMenu = new ConfigMenuRegistry();
            IConfigMenuRuntime previewRuntime = previewMenu;
            IManifest previewManifest = new ManifestModel
            {
                Name = "Preview Failure Test",
                Author = "DTMAPI",
                Version = "1.0.0",
                UniqueID = "DTMAPI.Tests.PreviewFailure"
            };
            bool previewEnabled = false;
            previewMenu.Register(previewManifest, () => { }, () => { });
            previewMenu.AddBoolOption(previewManifest, () => "Preview", () => "", () => previewEnabled, value =>
            {
                if (value)
                    throw new InvalidOperationException("preview-boom");
                previewEnabled = value;
            });

            IConfigMenuPage previewPage = previewRuntime.GetPage(previewManifest.UniqueID) ?? throw new InvalidOperationException("Preview page should exist.");
            previewRuntime.BeginEditing(previewManifest.UniqueID);
            Assert(previewPage.Items[0].TrySetPendingValue("true", out _), "Preview option should accept pending true.");
            using (previewRuntime.PreviewPendingValues(previewPage) ?? throw new InvalidOperationException("Preview scope should be returned even after callback failure."))
            {
                Assert(!previewEnabled, "Failed preview setter should be rolled back immediately.");
            }
            Assert(!previewEnabled, "Preview dispose should leave the original value intact.");
            Assert(previewPage.Items[0].ValidationError.Contains("preview-boom"), "Preview failure should be visible on the config item.");

            var resetMenu = new ConfigMenuRegistry();
            IConfigMenuRuntime resetRuntime = resetMenu;
            IManifest resetManifest = new ManifestModel
            {
                Name = "Reset Failure Test",
                Author = "DTMAPI",
                Version = "1.0.0",
                UniqueID = "DTMAPI.Tests.ResetFailure"
            };
            bool resetValue = true;
            bool failReset = true;
            resetMenu.Register(resetManifest, () =>
            {
                if (failReset)
                    throw new InvalidOperationException("reset-boom");
                resetValue = false;
            }, () => { });
            resetMenu.AddBoolOption(resetManifest, () => "Reset", () => "", () => resetValue, value => resetValue = value);
            IConfigMenuPage resetPage = resetRuntime.GetPage(resetManifest.UniqueID) ?? throw new InvalidOperationException("Reset page should exist.");
            resetRuntime.BeginEditing(resetManifest.UniqueID);
            AssertThrows(() => resetRuntime.Reset(resetManifest.UniqueID), "Reset callback failure should be reported.");
            Assert(resetValue && resetPage.IsEditing && !resetPage.HasPendingChanges, "Reset callback failure should keep the committed value and editing state.");

            var resetGetterMenu = new ConfigMenuRegistry();
            IConfigMenuRuntime resetGetterRuntime = resetGetterMenu;
            IManifest resetGetterManifest = new ManifestModel
            {
                Name = "Reset Getter Failure Test",
                Author = "DTMAPI",
                Version = "1.0.0",
                UniqueID = "DTMAPI.Tests.ResetGetterFailure"
            };
            bool resetFirst = true;
            bool resetSecond = true;
            bool failResetGetter = false;
            resetGetterMenu.Register(resetGetterManifest, () =>
            {
                resetFirst = false;
                resetSecond = false;
                failResetGetter = true;
            }, () => { });
            resetGetterMenu.AddBoolOption(resetGetterManifest, () => "First", () => "", () => resetFirst, value => resetFirst = value);
            resetGetterMenu.AddBoolOption(resetGetterManifest, () => "Second", () => "", () =>
            {
                if (failResetGetter)
                    throw new InvalidOperationException("reset-getter-boom");
                return resetSecond;
            }, value => resetSecond = value);
            IConfigMenuPage resetGetterPage = resetGetterRuntime.GetPage(resetGetterManifest.UniqueID) ?? throw new InvalidOperationException("Reset getter page should exist.");
            resetGetterRuntime.BeginEditing(resetGetterManifest.UniqueID);
            AssertThrows(() => resetGetterRuntime.Reset(resetGetterManifest.UniqueID), "Reset getter failure should be reported.");
            failResetGetter = false;
            Assert(resetFirst && resetSecond, "Reset getter failure should roll back true config values.");
            Assert(resetGetterPage.IsEditing && !resetGetterPage.HasPendingChanges, "Reset getter failure should not leave partially refreshed pending values.");

            var cancelMenu = new ConfigMenuRegistry();
            IConfigMenuRuntime cancelRuntime = cancelMenu;
            IManifest cancelManifest = new ManifestModel
            {
                Name = "Cancel Failure Test",
                Author = "DTMAPI",
                Version = "1.0.0",
                UniqueID = "DTMAPI.Tests.CancelFailure"
            };
            bool cancelValue = false;
            bool failCancelRestore = false;
            cancelMenu.Register(cancelManifest, () => { }, () => { });
            cancelMenu.AddBoolOption(cancelManifest, () => "Cancel", () => "", () => cancelValue, value =>
            {
                if (failCancelRestore && !value)
                    throw new InvalidOperationException("cancel-boom");
                cancelValue = value;
            });
            IConfigMenuPage cancelPage = cancelRuntime.GetPage(cancelManifest.UniqueID) ?? throw new InvalidOperationException("Cancel page should exist.");
            cancelRuntime.BeginEditing(cancelManifest.UniqueID);
            Assert(cancelPage.Items[0].TrySetPendingValue("true", out _), "Cancel option should accept pending true.");
            cancelValue = true;
            failCancelRestore = true;
            AssertThrows(() => cancelRuntime.Cancel(cancelManifest.UniqueID), "Cancel restore failure should be reported.");
            Assert(cancelValue && cancelPage.IsEditing && cancelPage.HasPendingChanges, "Cancel restore failure should keep the page editing so the failed pending state remains visible.");
            Assert(cancelPage.Items[0].ValidationError.Contains("cancel-boom"), "Cancel restore failure should stay visible on the item.");

            var buttonMenu = new ConfigMenuRegistry();
            IConfigMenuRuntime buttonRuntime = buttonMenu;
            IManifest buttonManifest = new ManifestModel
            {
                Name = "Button Failure Test",
                Author = "DTMAPI",
                Version = "1.0.0",
                UniqueID = "DTMAPI.Tests.ButtonFailure"
            };
            buttonMenu.Register(buttonManifest, () => { }, () => { });
            buttonMenu.AddButton(buttonManifest, () => "Danger", () => "", () => throw new InvalidOperationException("button-boom"));
            IConfigMenuPage buttonPage = buttonRuntime.GetPage(buttonManifest.UniqueID) ?? throw new InvalidOperationException("Button page should exist.");
            AssertThrows(buttonPage.Items.Single(item => item.Kind == "Button").Invoke, "Button callback failure should be wrapped for the UI action guard.");
        }

        private static void ConfigMenuPendingPreviewDrivesConditionalVisibility()
        {
            var menu = new ConfigMenuRegistry();
            IConfigMenuRuntime menuRuntime = menu;
            IManifest manifest = new ManifestModel
            {
                Name = "Conditional Menu Test",
                Author = "DTMAPI",
                Version = "1.0.0",
                UniqueID = "DTMAPI.Tests.ConditionalMenu"
            };
            string colorPreset = "Orange";
            string hex = "FF942E";

            menu.Register(manifest, () =>
            {
                colorPreset = "Orange";
                hex = "FF942E";
            }, () => { });
            menu.AddColorPresetOption(
                manifest,
                () => "Color",
                () => "",
                () => colorPreset,
                value => colorPreset = value,
                new[]
                {
                    new DtmColorPreset("Orange", "Orange", "FF942E"),
                    new DtmColorPreset("Custom", "Custom", hex)
                });
            Func<bool> customSelected = () => colorPreset.Equals("Custom", StringComparison.OrdinalIgnoreCase);
            menu.AddTextOption(manifest, () => "Hex", () => "", () => hex, value => hex = value, customSelected, customSelected);

            IConfigMenuPage page = menuRuntime.GetPage(manifest.UniqueID) ?? throw new InvalidOperationException("Page should exist.");
            menuRuntime.BeginEditing(manifest.UniqueID);
            Assert(page.Items.Count(item => item.Kind == "Text") == 0, "Non-custom color should hide the custom text input.");
            IConfigMenuItem colorItem = page.Items.Single(item => item.Kind == "ColorPreset");
            Assert(colorItem.TrySetPendingValue("Custom", out _), "Custom color preset should be selectable.");
            Assert(colorPreset == "Orange", "Pending edits should not permanently apply before save.");

            using (menuRuntime.PreviewPendingValues(page) ?? throw new InvalidOperationException("Pending preview should be available."))
            {
                Assert(colorPreset == "Custom", "Pending preview should temporarily expose the selected custom preset.");
                IConfigMenuItem textItem = page.Items.Single(item => item.Kind == "Text");
                Assert(textItem.CanEdit, "Custom color text input should be editable inside pending preview.");
            }

            Assert(colorPreset == "Orange", "Pending preview should restore the committed color after rendering.");
        }

        private static void DisabledDiscoveredModLocksConfigPage()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
            string dir = NewTempGameDir();
            string persistentRoot = Environment.GetEnvironmentVariable("DTMAPI_DOLOC_PERSISTENT_ROOT")
                ?? throw new InvalidOperationException("Temporary persistent root was not configured.");
            string modDir = Path.Combine(persistentRoot, "MODS", "Disabled");
            Directory.CreateDirectory(modDir);
            File.WriteAllText(Path.Combine(modDir, "manifest.json"), "{ \"Name\": \"Disabled\", \"Author\": \"DTMAPI\", \"Version\": \"1.0.0\", \"UniqueID\": \"DTMAPI.Tests.Disabled\", \"EntryDll\": \"Disabled.dll\" }");
            WriteOfficialModInfos(persistentRoot, "Local.Disabled", enabled: false);

            var menu = new ConfigMenuRegistry();
            IConfigMenuRuntime menuRuntime = menu;
            IManifest manifest = new ManifestModel
            {
                Name = "Disabled",
                Author = "DTMAPI",
                Version = "1.0.0",
                UniqueID = "DTMAPI.Tests.Disabled"
            };
            bool enabled = false;
            int saved = 0;
            int reset = 0;
            menu.Register(manifest, () => reset++, () => saved++);
            menu.AddBoolOption(manifest, () => "Enabled", () => "", () => enabled, value => enabled = value);

            var runtime = new DtmApiRuntime(
                new FakeHost(dir, includeLegacyDevelopmentModSourceForTests: false),
                menu);
            runtime.Start();

            IConfigMenuPage page = menuRuntime.GetPage(manifest.UniqueID) ?? throw new InvalidOperationException("Disabled page should exist.");
            Assert(page.IsLocked, "Disabled discovered mod should lock its config page.");
            Assert(page.LockReason.IndexOf("Doloc Town 官方 Mod 界面", StringComparison.OrdinalIgnoreCase) >= 0, "Disabled lock should explain the official disabled state with Chinese-first text.");

            menuRuntime.BeginEditing(manifest.UniqueID);
            Assert(page.Items[0].TrySetPendingValue("true", out _), "Locked page may stage text but must not apply it.");
            AssertThrows(() => menuRuntime.Save(manifest.UniqueID), "Locked page save should be rejected.");
            AssertThrows(() => menuRuntime.Reset(manifest.UniqueID), "Locked page reset should be rejected.");
            Assert(!enabled && saved == 0 && reset == 0, "Locked page actions must not mutate config.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void OfficialLocalModPackagesRespectOfficialEnablement()
        {
            string gameDir = NewTempGameDir();
            string persistentRoot = Path.Combine(Path.GetTempPath(), "DTMAPI-tests-persistent", Guid.NewGuid().ToString("N"));
            string packageRoot = Path.Combine(persistentRoot, "MODS", "Yuuka_DTMAPI_Test");
            string contentRoot = Path.Combine(packageRoot, "Content", "DTMAPI");
            Directory.CreateDirectory(contentRoot);
            File.WriteAllText(
                Path.Combine(contentRoot, "manifest.json"),
                "{ \"Name\": \"Official Test\", \"Author\": \"Yuuka\", \"Version\": \"1.0.0\", \"UniqueID\": \"Yuuka.DTMAPI.Test\", \"Type\": \"ContentPack\" }",
                new UTF8Encoding(encoderShouldEmitUTF8Identifier: true));
            File.WriteAllText(
                Path.Combine(contentRoot, "item_tbitem.json"),
                "[{ \"id\": \"dtmapi_test_item\", \"sub_type\": \"material\", \"title\": { \"text\": \"测试物品\", \"english\": \"Test Item\" }, \"ui_sprite_asset\": { \"url\": \"icon_item_dtmapi_test_item\" } }]");

            string? previousRoot = Environment.GetEnvironmentVariable("DTMAPI_DOLOC_PERSISTENT_ROOT");
            try
            {
                Environment.SetEnvironmentVariable("DTMAPI_DOLOC_PERSISTENT_ROOT", persistentRoot);
                WriteOfficialModInfos(persistentRoot, "Local.Yuuka_DTMAPI_Test", false);
                var disabledRuntime = new DtmApiRuntime(new FakeHost(gameDir), new ConfigMenuRegistry());
                disabledRuntime.Start();
                RuntimeSnapshot disabledSnapshot = disabledRuntime.CreateSnapshot();
                DiscoveredMod disabled = disabledSnapshot.DiscoveredMods.Single(m => m.Manifest.UniqueID == "Yuuka.DTMAPI.Test");
                Assert(disabled.Source == "Local", "Official upload package should use Doloc Town's Local source name.");
                Assert(!disabled.OfficialEnabled, "Official disabled state should prevent loading.");
                Assert(!disabledSnapshot.LoadedMods.Any(m => m.Manifest.UniqueID == "Yuuka.DTMAPI.Test"), "Official-disabled package must not load.");
                Assert(disabledRuntime.GetIndexedContentItem("dtmapi_test_item") == null, "Default content item lookup should not return disabled official content.");
                IContentItemInfo? disabledAnyItem = disabledRuntime.GetAnyIndexedContentItem("dtmapi_test_item");
                Assert(disabledAnyItem == null, "All-content item lookup must not parse or expose disabled official gameplay content.");
                Assert(!disabledRuntime.GetAllIndexedContentItems().Any(i => i.ItemId == "dtmapi_test_item"), "All-content list must not retain item-level rows from disabled official content.");
                Assert(!disabledRuntime.GetIndexedContentItems().Any(i => i.ItemId == "dtmapi_test_item"), "Default content list should include enabled content only.");
                IContentQueryHelper disabledContent = GetContent(disabledRuntime);
                Assert(!disabledContent.FindAssets("json").Any(a => a.RelativePath.EndsWith("item_tbitem.json", StringComparison.OrdinalIgnoreCase)), "Default content asset lookup should not expose disabled official package files.");
                Assert(!disabledContent.TryReadTextAsset(Path.Combine("Content", "DTMAPI", "item_tbitem.json"), out _), "Default text asset lookup should not read disabled official package files.");
                IDtmModStatusInfo disabledStatus = disabledRuntime.CreateDiagnosticsSnapshot().Mods.Single(m => m.UniqueID == "Yuuka.DTMAPI.Test");
                Assert(!disabledStatus.Loaded && disabledStatus.Status == "disabled" && disabledStatus.StatusCode == "disabled" && !disabledStatus.OfficialEnabled && disabledStatus.OfficialEnablementManaged && disabledStatus.EnablementReason.Contains("官方"), "Diagnostics snapshot should expose official disabled mod status and enablement reason.");

                WriteOfficialModInfos(persistentRoot, "Local.Yuuka_DTMAPI_Test", true);
                var enabledRuntime = new DtmApiRuntime(new FakeHost(gameDir), new ConfigMenuRegistry());
                enabledRuntime.Start();
                RuntimeSnapshot enabledSnapshot = enabledRuntime.CreateSnapshot();
                Assert(enabledSnapshot.DiscoveredMods.Single(m => m.Manifest.UniqueID == "Yuuka.DTMAPI.Test").OfficialEnabled, "Official enabled state should be honored.");
                Assert(enabledSnapshot.LoadedMods.Any(m => m.Manifest.UniqueID == "Yuuka.DTMAPI.Test"), "Official-enabled content package should load/index.");
                IContentItemInfo? enabledItem = enabledRuntime.GetIndexedContentItem("dtmapi_test_item");
                Assert(enabledItem != null && enabledItem.Enabled && enabledItem.SourceKind == "DTMAPI" && enabledItem.SourceId == "Local.Yuuka_DTMAPI_Test", "Default content item lookup should expose enabled DTMAPI official-local content.");
                IContentQueryHelper enabledContent = GetContent(enabledRuntime);
                Assert(enabledContent.FindAssets("json").Any(a => a.RelativePath.EndsWith("item_tbitem.json", StringComparison.OrdinalIgnoreCase)), "Default content asset lookup should expose enabled official package files.");
                Assert(enabledContent.TryReadTextAsset(Path.Combine("Content", "DTMAPI", "item_tbitem.json"), out string enabledText) && enabledText.Contains("dtmapi_test_item", StringComparison.OrdinalIgnoreCase), "Default text asset lookup should read enabled official package files.");
                IDtmModStatusInfo enabledStatus = enabledRuntime.CreateDiagnosticsSnapshot().Mods.Single(m => m.UniqueID == "Yuuka.DTMAPI.Test");
                Assert(enabledStatus.Loaded && enabledStatus.Status == "loaded" && enabledStatus.StatusCode == "loaded" && enabledStatus.Source == "Local", "Diagnostics snapshot should expose official loaded Mod status with the native Local source name.");

                File.Delete(Path.Combine(persistentRoot, "SAVE", "mod_infos.json"));
                var unknownRuntime = new DtmApiRuntime(new FakeHost(gameDir), new ConfigMenuRegistry());
                unknownRuntime.Start();
                DiscoveredMod unknown = unknownRuntime.CreateSnapshot().DiscoveredMods.Single(m => m.Manifest.UniqueID == "Yuuka.DTMAPI.Test");
                Assert(!unknown.OfficialEnabled, "Missing official enablement data should not default to enabled.");
                Assert(unknown.EnablementReason.IndexOf("官方启用状态文件", StringComparison.OrdinalIgnoreCase) >= 0, "Missing official state should have a clear Chinese-first reason.");
            }
            finally
            {
                Environment.SetEnvironmentVariable("DTMAPI_DOLOC_PERSISTENT_ROOT", previousRoot);
            }
        }

        private static void UnverifiedWorkshopAndGameModsCannotOverrideOfficialLocalState()
        {
            DiscoveredMod? enabledWorkshop = RunDuplicateSourceSelectionCase(
                "EnabledWorkshop",
                officialLocalEnabled: false,
                workshopEnabled: true,
                localDisabled: true,
                workshopId: 3749000001UL,
                out DtmApiRuntime enabledWorkshopRuntime);
            Assert(enabledWorkshop != null && enabledWorkshop.Source == "Local" && !enabledWorkshop.OfficialEnabled,
                "An unverified Workshop directory cannot become the selected source; the sole official Local row remains visible as disabled diagnostics.");
            Assert(!enabledWorkshopRuntime.LoadedMods.Any(mod => mod.Manifest.UniqueID == "Yuuka.DTMAPI.Duplicate.EnabledWorkshop"),
                "A Workshop enabled only in stale file state must not load without current native install-path proof.");

            DiscoveredMod? enabledOfficialAndWorkshop = RunDuplicateSourceSelectionCase(
                "EnabledOfficial",
                officialLocalEnabled: true,
                workshopEnabled: true,
                localDisabled: true,
                workshopId: 3749000002UL,
                out _);
            Assert(enabledOfficialAndWorkshop != null && enabledOfficialAndWorkshop.Source == "Local" && enabledOfficialAndWorkshop.OfficialEnabled,
                "An enabled official Local candidate must win when the duplicate Workshop directory lacks current subscription-path proof.");

            DiscoveredMod? allDisabled = RunDuplicateSourceSelectionCase(
                "AllDisabled",
                officialLocalEnabled: false,
                workshopEnabled: false,
                localDisabled: true,
                workshopId: 3749000003UL,
                out DtmApiRuntime allDisabledRuntime);
            Assert(allDisabled != null && !allDisabled.OfficialEnabled &&
                !allDisabledRuntime.LoadedMods.Any(mod => mod.Manifest.UniqueID == "Yuuka.DTMAPI.Duplicate.AllDisabled"),
                "All-disabled official candidates must remain unloaded even when raw duplicate directories exist.");

            DiscoveredMod? enabledLocal = RunDuplicateSourceSelectionCase(
                "EnabledLocal",
                officialLocalEnabled: false,
                workshopEnabled: false,
                localDisabled: false,
                workshopId: 3749000004UL,
                out DtmApiRuntime enabledLocalRuntime);
            Assert(enabledLocal != null && enabledLocal.Source == "Local" && !enabledLocal.OfficialEnabled &&
                !enabledLocalRuntime.LoadedMods.Any(mod => mod.Manifest.UniqueID == "Yuuka.DTMAPI.Duplicate.EnabledLocal"),
                "A same-ID package under <game>/Mods must not override disabled official Local/Workshop state.");
            AuthorSourceSelectionDecision decision = enabledLocalRuntime.AuthorSourceSelectionDecisions.Single(row =>
                row.UniqueId == "Yuuka.DTMAPI.Duplicate.EnabledLocal");
            Assert(decision.Candidates.Count == 2 && decision.Candidates.All(candidate =>
                !PathsEqualForTest(candidate.RootPath, Path.Combine(enabledLocalRuntime.Paths.LegacyDevelopmentModsPath, "Yuuka_DTMAPI_Duplicate_EnabledLocal"))),
                "Player discovery must retain only the two official physical candidates; <game>/Mods is not a candidate.");
        }

        private static void OfficialSourceArbitrationOneOffMatrix()
        {
            string gameDir = NewTempGameDir();
            string persistentRoot = Path.Combine(Path.GetTempPath(), "DTMAPI-tests-persistent", Guid.NewGuid().ToString("N"));
            var officialRows = new List<OfficialModInfoTestEntry>();
            var subscriptions = new List<NativeWorkshopSubscription>();

            OfficialSourceMatrixFixture localWins = CreateOfficialSourceMatrixFixture(gameDir, persistentRoot, "LocalWins", 3749100001UL);
            File.WriteAllText(Path.Combine(localWins.LocalRoot, "dtmapi.disabled"), "legacy marker must not override official enabled state");
            officialRows.Add(new OfficialModInfoTestEntry(localWins.LocalOfficialId, true, "Local", 10));
            officialRows.Add(new OfficialModInfoTestEntry(localWins.WorkshopOfficialId, false, "Workshop", 20));
            subscriptions.Add(new NativeWorkshopSubscription(localWins.WorkshopId, localWins.WorkshopRoot, false, 20, localWins.WorkshopOfficialId));

            OfficialSourceMatrixFixture workshopWins = CreateOfficialSourceMatrixFixture(gameDir, persistentRoot, "WorkshopWins", 3749100002UL);
            officialRows.Add(new OfficialModInfoTestEntry(workshopWins.LocalOfficialId, false, "Local", 20));
            officialRows.Add(new OfficialModInfoTestEntry(workshopWins.WorkshopOfficialId, true, "Workshop", 10));
            subscriptions.Add(new NativeWorkshopSubscription(workshopWins.WorkshopId, workshopWins.WorkshopRoot, true, 10, workshopWins.WorkshopOfficialId));

            OfficialSourceMatrixFixture allDisabled = CreateOfficialSourceMatrixFixture(gameDir, persistentRoot, "AllDisabled", 3749100003UL);
            officialRows.Add(new OfficialModInfoTestEntry(allDisabled.LocalOfficialId, false, "Local", -1));
            officialRows.Add(new OfficialModInfoTestEntry(allDisabled.WorkshopOfficialId, false, "Workshop", -1));
            subscriptions.Add(new NativeWorkshopSubscription(allDisabled.WorkshopId, allDisabled.WorkshopRoot, false, -1, allDisabled.WorkshopOfficialId));

            OfficialSourceMatrixFixture priorityWins = CreateOfficialSourceMatrixFixture(gameDir, persistentRoot, "PriorityWins", 3749100004UL);
            officialRows.Add(new OfficialModInfoTestEntry(priorityWins.LocalOfficialId, true, "Local", 30));
            officialRows.Add(new OfficialModInfoTestEntry(priorityWins.WorkshopOfficialId, true, "Workshop", 12));
            subscriptions.Add(new NativeWorkshopSubscription(priorityWins.WorkshopId, priorityWins.WorkshopRoot, true, 12, priorityWins.WorkshopOfficialId));

            OfficialSourceMatrixFixture priorityTie = CreateOfficialSourceMatrixFixture(gameDir, persistentRoot, "PriorityTie", 3749100005UL);
            officialRows.Add(new OfficialModInfoTestEntry(priorityTie.LocalOfficialId, true, "Local", 7));
            officialRows.Add(new OfficialModInfoTestEntry(priorityTie.WorkshopOfficialId, true, "Workshop", 7));
            subscriptions.Add(new NativeWorkshopSubscription(priorityTie.WorkshopId, priorityTie.WorkshopRoot, true, 7, priorityTie.WorkshopOfficialId));

            OfficialSourceMatrixFixture priorityMissing = CreateOfficialSourceMatrixFixture(gameDir, persistentRoot, "PriorityMissing", 3749100006UL);
            officialRows.Add(new OfficialModInfoTestEntry(priorityMissing.LocalOfficialId, true, "Local", priority: null));
            officialRows.Add(new OfficialModInfoTestEntry(priorityMissing.WorkshopOfficialId, true, "Workshop", 40));
            subscriptions.Add(new NativeWorkshopSubscription(priorityMissing.WorkshopId, priorityMissing.WorkshopRoot, true, 40, priorityMissing.WorkshopOfficialId));

            OfficialSourceMatrixFixture staleWorkshop = CreateOfficialSourceMatrixFixture(gameDir, persistentRoot, "StaleWorkshop", 3749100007UL);
            officialRows.Add(new OfficialModInfoTestEntry(staleWorkshop.LocalOfficialId, true, "Local", 1));
            officialRows.Add(new OfficialModInfoTestEntry(staleWorkshop.WorkshopOfficialId, true, "Workshop", 99));

            OfficialSourceMatrixFixture gameModsIgnored = CreateOfficialSourceMatrixFixture(gameDir, persistentRoot, "GameModsIgnored", 3749100008UL, includeWorkshop: false, includeGameMods: true);
            officialRows.Add(new OfficialModInfoTestEntry(gameModsIgnored.LocalOfficialId, true, "Local", 1));

            string? previousPersistentRoot = Environment.GetEnvironmentVariable("DTMAPI_DOLOC_PERSISTENT_ROOT");
            try
            {
                Environment.SetEnvironmentVariable("DTMAPI_DOLOC_PERSISTENT_ROOT", persistentRoot);
                WriteOfficialModInfos(persistentRoot, officialRows.ToArray());
                var runtime = new DtmApiRuntime(
                    new FakeHost(gameDir, includeLegacyDevelopmentModSourceForTests: false),
                    new ConfigMenuRegistry());
                runtime.UpdateNativeWorkshopSubscriptions(true, "one-off-official-source-matrix", string.Empty, subscriptions);
                runtime.Start();

                IReadOnlyList<DiscoveredMod> discovered = runtime.CreateSnapshot().DiscoveredMods;
                DiscoveredMod localSelected = discovered.Single(mod => mod.Manifest.UniqueID == localWins.UniqueId);
                Assert(localSelected.Source == "Local" && PathsEqualForTest(localSelected.RootPath, localWins.LocalRoot),
                    "Matrix: Local enabled plus Workshop disabled must select Local.");

                DiscoveredMod workshopSelected = discovered.Single(mod => mod.Manifest.UniqueID == workshopWins.UniqueId);
                Assert(workshopSelected.Source == "Workshop" && PathsEqualForTest(workshopSelected.RootPath, workshopWins.WorkshopRoot),
                    "Matrix: Local disabled plus Workshop enabled must select Workshop.");

                Assert(!discovered.Any(mod => mod.Manifest.UniqueID == allDisabled.UniqueId) &&
                    !runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == allDisabled.UniqueId),
                    "Matrix: two disabled official candidates must select and load neither copy.");

                DiscoveredMod prioritySelected = discovered.Single(mod => mod.Manifest.UniqueID == priorityWins.UniqueId);
                Assert(prioritySelected.Source == "Local" && prioritySelected.OfficialPriority == 30,
                    "Matrix: multiple enabled candidates must use the unique greatest official priority, not Workshop source preference.");

                Assert(!discovered.Any(mod => mod.Manifest.UniqueID == priorityTie.UniqueId) &&
                    runtime.Diagnostics.GetWarnings().Any(warning =>
                        warning.Details.Contains("Duplicate UniqueID " + priorityTie.UniqueId, StringComparison.Ordinal) &&
                        warning.Details.Contains("enable only one copy", StringComparison.OrdinalIgnoreCase)),
                    "Matrix: tied enabled official priorities must block the duplicate and provide one-copy guidance.");

                Assert(!discovered.Any(mod => mod.Manifest.UniqueID == priorityMissing.UniqueId) &&
                    runtime.Diagnostics.GetWarnings().Any(warning =>
                        warning.Details.Contains("Duplicate UniqueID " + priorityMissing.UniqueId, StringComparison.Ordinal) &&
                        warning.Details.Contains("priority/load order is unavailable", StringComparison.OrdinalIgnoreCase)),
                    "Matrix: one missing official priority must block multiple enabled copies even when the other candidate has a numeric priority.");

                DiscoveredMod staleSelected = discovered.Single(mod => mod.Manifest.UniqueID == staleWorkshop.UniqueId);
                Assert(staleSelected.Source == "Local" && PathsEqualForTest(staleSelected.RootPath, staleWorkshop.LocalRoot),
                    "Matrix: a stale numeric Workshop directory outside the current subscription snapshot must not defeat Local.");

                DiscoveredMod gameModsSelected = discovered.Single(mod => mod.Manifest.UniqueID == gameModsIgnored.UniqueId);
                AuthorSourceSelectionDecision gameModsDecision = runtime.AuthorSourceSelectionDecisions.Single(row => row.UniqueId == gameModsIgnored.UniqueId);
                Assert(gameModsSelected.Source == "Local" && PathsEqualForTest(gameModsSelected.RootPath, gameModsIgnored.LocalRoot) &&
                    gameModsDecision.Candidates.Count == 1 &&
                    !gameModsDecision.Candidates.Any(candidate => PathsEqualForTest(candidate.RootPath, gameModsIgnored.GameModsRoot)),
                    "Matrix: a same-ID <game>/Mods tree must not enter player discovery or affect official Local selection.");
            }
            finally
            {
                Environment.SetEnvironmentVariable("DTMAPI_DOLOC_PERSISTENT_ROOT", previousPersistentRoot);
            }
        }

        private static OfficialSourceMatrixFixture CreateOfficialSourceMatrixFixture(
            string gameDir,
            string persistentRoot,
            string caseName,
            ulong workshopId,
            bool includeWorkshop = true,
            bool includeGameMods = false)
        {
            string folderName = "DTMAPI_OfficialSource_" + caseName;
            string uniqueId = "DTMAPI.Tests.OfficialSource." + caseName;
            string localRoot = Path.Combine(persistentRoot, "MODS", folderName);
            string workshopRoot = Path.Combine(gameDir, "steamapps", "workshop", "content", "2285550", workshopId.ToString(CultureInfo.InvariantCulture));
            string gameModsRoot = Path.Combine(gameDir, "Mods", folderName);
            WriteSourceAuthorityContentPack(localRoot, uniqueId, caseName + " Local");
            if (includeWorkshop)
                WriteSourceAuthorityContentPack(workshopRoot, uniqueId, caseName + " Workshop");
            if (includeGameMods)
                WriteSourceAuthorityContentPack(gameModsRoot, uniqueId, caseName + " game Mods");
            return new OfficialSourceMatrixFixture(folderName, uniqueId, workshopId, localRoot, workshopRoot, gameModsRoot);
        }

        private static void FrameDriverHealthPolicyDistinguishesGlobalPauseAndSingleDriverStall()
        {
            DateTimeOffset now = DateTimeOffset.UtcNow;
            DateTimeOffset stale = now - TimeSpan.FromSeconds(3);
            var queued = new FrameDriverHealthSnapshot(
                inputSystemSubscribed: true,
                inputSystemCallbackSeen: true,
                playerLoopCallbackSeen: true,
                nativeCallbackSeen: true,
                unityUpdateCallbackSeen: true,
                inputSystemCallbackCount: 5,
                playerLoopCallbackCount: 10,
                nativeCallbackCount: 20,
                unityUpdateCallbackCount: 30,
                lastInputSystemCallbackAt: stale,
                lastInputSystemSubscribeAttemptAt: stale,
                lastPlayerLoopCallbackAt: stale,
                lastNativeCallbackAt: stale,
                lastUnityUpdateCallbackAt: stale);

            Assert(FrameDriverHealthPolicy.GetProbeKind(queued, now) == FrameDriverHealthProbeKind.ObserveGlobalPause, "A global frame gap should queue one main-thread health observation without assigning fault.");
            Assert(FrameDriverHealthPolicy.Evaluate(FrameDriverHealthProbeKind.ObserveGlobalPause, queued, queued, now) == FrameDriverHealthDecision.GlobalPause, "Unchanged stale counts across every Unity source must be classified as a global pause, not an InputSystem failure.");

            var siblingAdvanced = new FrameDriverHealthSnapshot(
                inputSystemSubscribed: true,
                inputSystemCallbackSeen: true,
                playerLoopCallbackSeen: true,
                nativeCallbackSeen: true,
                unityUpdateCallbackSeen: true,
                inputSystemCallbackCount: 5,
                playerLoopCallbackCount: 11,
                nativeCallbackCount: 20,
                unityUpdateCallbackCount: 31,
                lastInputSystemCallbackAt: stale,
                lastInputSystemSubscribeAttemptAt: stale,
                lastPlayerLoopCallbackAt: now,
                lastNativeCallbackAt: stale,
                lastUnityUpdateCallbackAt: now);
            Assert(FrameDriverHealthPolicy.GetProbeKind(siblingAdvanced, now) == FrameDriverHealthProbeKind.VerifyIsolatedInputStall, "A stale InputSystem callback with a progressing sibling must queue isolated-driver recovery.");
            Assert(FrameDriverHealthPolicy.Evaluate(FrameDriverHealthProbeKind.VerifyIsolatedInputStall, queued, siblingAdvanced, now) == FrameDriverHealthDecision.RecoverInputSystem, "Sibling progress with unchanged stale InputSystem count must select only InputSystem recovery.");
            Assert(FrameDriverHealthPolicy.Evaluate(FrameDriverHealthProbeKind.ObserveGlobalPause, queued, siblingAdvanced, now) == FrameDriverHealthDecision.GlobalPause, "A probe queued during a global pause must not recover InputSystem merely because sibling callbacks resume earlier in the same Unity frame.");

            var inputRecovered = new FrameDriverHealthSnapshot(
                inputSystemSubscribed: true,
                inputSystemCallbackSeen: true,
                playerLoopCallbackSeen: true,
                nativeCallbackSeen: true,
                unityUpdateCallbackSeen: true,
                inputSystemCallbackCount: 6,
                playerLoopCallbackCount: 11,
                nativeCallbackCount: 20,
                unityUpdateCallbackCount: 31,
                lastInputSystemCallbackAt: now,
                lastInputSystemSubscribeAttemptAt: stale,
                lastPlayerLoopCallbackAt: now,
                lastNativeCallbackAt: stale,
                lastUnityUpdateCallbackAt: now);
            Assert(FrameDriverHealthPolicy.Evaluate(FrameDriverHealthProbeKind.VerifyIsolatedInputStall, queued, inputRecovered, now) == FrameDriverHealthDecision.NoAction, "InputSystem progress after queueing must cancel stale recovery before unsubscribe.");

            var missingSubscription = new FrameDriverHealthSnapshot(
                inputSystemSubscribed: false,
                inputSystemCallbackSeen: false,
                playerLoopCallbackSeen: true,
                nativeCallbackSeen: false,
                unityUpdateCallbackSeen: true,
                inputSystemCallbackCount: 0,
                playerLoopCallbackCount: 12,
                nativeCallbackCount: 0,
                unityUpdateCallbackCount: 40,
                lastInputSystemCallbackAt: DateTimeOffset.MinValue,
                lastInputSystemSubscribeAttemptAt: now - TimeSpan.FromSeconds(11),
                lastPlayerLoopCallbackAt: now,
                lastNativeCallbackAt: DateTimeOffset.MinValue,
                lastUnityUpdateCallbackAt: now);
            Assert(FrameDriverHealthPolicy.GetProbeKind(missingSubscription, now) == FrameDriverHealthProbeKind.RetryMissingSubscription, "A missing InputSystem subscription must retry on its bounded cadence even while sibling drivers remain healthy.");
            Assert(FrameDriverHealthPolicy.Evaluate(FrameDriverHealthProbeKind.RetryMissingSubscription, queued, missingSubscription, now) == FrameDriverHealthDecision.NoAction, "A missing subscription is a retry condition, not a false isolated-stall diagnosis.");
        }

        private static void AuthorFileTreeDigestMatchesFrozenCrossToolVectors()
        {
            string root = Path.Combine(Path.GetTempPath(), "DTMAPI-file-tree-v1", Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(root);
            try
            {
                Assert(
                    AuthorFileTreeDigest.Compute(root) == "E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855",
                    "The empty DTMAPI-FileTree-SHA256-v1 vector should remain frozen across Runtime and Author SDK implementations.");

                File.WriteAllText(Path.Combine(root, "a.txt"), "A", new UTF8Encoding(false));
                string nested = Path.Combine(root, "sub");
                Directory.CreateDirectory(nested);
                File.WriteAllBytes(Path.Combine(nested, "β.bin"), new byte[] { 0x00, 0x01, 0x02, 0xFF });
                Assert(
                    AuthorFileTreeDigest.Compute(root) == "8E7C6E58D4982A1C5D749524A8A56A4C2171D7301144EE5640ABAC7AE74CB4CD",
                    "The mixed text/binary DTMAPI-FileTree-SHA256-v1 vector should remain frozen across Runtime and Author SDK implementations.");

                File.WriteAllBytes(Path.Combine(nested, "β.bin"), new byte[] { 0x00, 0x01, 0x02, 0xFE });
                Assert(
                    AuthorFileTreeDigest.Compute(root) != "8E7C6E58D4982A1C5D749524A8A56A4C2171D7301144EE5640ABAC7AE74CB4CD",
                    "Changing file content should change the frozen source-tree digest.");
            }
            finally
            {
                if (Directory.Exists(root))
                    Directory.Delete(root, recursive: true);
            }
        }

        private static void NativeWorkshopAuthorityAndAuthorSourceModesSelectDeterministically()
        {
            string gameDir = NewTempGameDir();
            string persistentRoot = Path.Combine(Path.GetTempPath(), "DTMAPI-tests-persistent", Guid.NewGuid().ToString("N"));
            string authorStateRoot = Path.Combine(Path.GetTempPath(), "DTMAPI-tests-author-state", Guid.NewGuid().ToString("N"));
            const string folderName = "Yuuka_DTMAPI_SourceAuthority";
            const string uniqueId = "Yuuka.DTMAPI.SourceAuthority";
            const ulong workshopId = 3749000020UL;

            string officialRoot = Path.Combine(persistentRoot, "MODS", folderName);
            string workshopRoot = Path.Combine(gameDir, "steamapps", "workshop", "content", "2285550", workshopId.ToString(CultureInfo.InvariantCulture));
            string localRoot = Path.Combine(gameDir, "Mods", folderName);
            WriteSourceAuthorityContentPack(officialRoot, uniqueId, "Official source");
            WriteSourceAuthorityContentPack(workshopRoot, uniqueId, "Workshop source");
            WriteSourceAuthorityContentPack(localRoot, uniqueId, "Local source");

            string? previousPersistentRoot = Environment.GetEnvironmentVariable("DTMAPI_DOLOC_PERSISTENT_ROOT");
            string? previousAuthorRoot = Environment.GetEnvironmentVariable("DTMAPI_AUTHOR_STATE_ROOT");
            try
            {
                Environment.SetEnvironmentVariable("DTMAPI_DOLOC_PERSISTENT_ROOT", persistentRoot);
                Environment.SetEnvironmentVariable("DTMAPI_AUTHOR_STATE_ROOT", authorStateRoot);
                WriteOfficialModInfos(
                    persistentRoot,
                    new OfficialModInfoTestEntry("Local." + folderName, true, "Local", priority: 10),
                    new OfficialModInfoTestEntry("Workshop." + workshopId.ToString(CultureInfo.InvariantCulture), true, "Workshop", priority: 20));

                DtmApiRuntime playerRuntime = StartSourceAuthorityRuntime(gameDir, workshopId, workshopRoot, nativeSnapshotAvailable: true);
                DiscoveredMod playerSelected = playerRuntime.CreateSnapshot().DiscoveredMods.Single(mod => mod.Manifest.UniqueID == uniqueId);
                Assert(playerSelected.Source == "Workshop" && playerSelected.NativeSubscriptionVerified, "Player/Workshop mode should prefer the enabled native-subscribed Workshop source.");
                Assert(File.Exists(AuthorSourceStateStore.GetWorkshopSnapshotPath(gameDir)), "Native Workshop authority should be persisted outside packages and keyed by game root.");

                DtmApiRuntime disabledWorkshopRuntime = StartSourceAuthorityRuntime(gameDir, workshopId, workshopRoot, nativeSnapshotAvailable: true, nativeEnabled: false);
                DiscoveredMod disabledWorkshopSelected = disabledWorkshopRuntime.CreateSnapshot().DiscoveredMods.Single(mod => mod.Manifest.UniqueID == uniqueId);
                Assert(
                    disabledWorkshopSelected.Source == "Local" && disabledWorkshopSelected.OfficialEnabled && PathsEqualForTest(disabledWorkshopSelected.RootPath, officialRoot),
                    "A disabled native-subscribed Workshop duplicate must not shadow the enabled official Local candidate.");
                Assert(disabledWorkshopRuntime.LoadedMods.Any(mod => mod.Manifest.UniqueID == uniqueId), "The enabled official Local candidate should remain active when Workshop is disabled.");

                WriteAuthorSourceSelectionState(gameDir, uniqueId, "LocalDevelopment", localRoot, playerReproductionActive: false);
                DtmApiRuntime localRuntime = StartSourceAuthorityRuntime(gameDir, workshopId, workshopRoot, nativeSnapshotAvailable: true);
                DiscoveredMod localSelected = localRuntime.CreateSnapshot().DiscoveredMods.Single(mod => mod.Manifest.UniqueID == uniqueId);
                Assert(localSelected.Source == "Workshop" && PathsEqualForTest(localSelected.RootPath, workshopRoot), "Legacy Local Development state must not override official enabled/load-order selection.");
                Assert(localSelected.SelectionReason.Contains("mode=LocalDevelopment", StringComparison.Ordinal), "Selected source should retain its machine-inspectable source-mode decision reason.");
                AuthorSourceSelectionDecision localDecision = localRuntime.AuthorSourceSelectionDecisions.Single(decision => decision.UniqueId == uniqueId);
                Assert(localDecision.Selected?.Source == "Workshop" && localDecision.Candidates.Count == 2, "Player source authority should retain only official Local and native-verified Workshop candidates.");
                Assert(localRuntime.Diagnostics.GetWarnings().Any(warning => warning.Details.Contains("recovery-only", StringComparison.OrdinalIgnoreCase)), "Legacy Local Development state should be diagnosed as recovery-only.");

                string missingLocalRoot = Path.Combine(gameDir, "Mods", "MissingSourceAuthorityOverride");
                WriteAuthorSourceSelectionState(gameDir, uniqueId, "LocalDevelopment", missingLocalRoot, playerReproductionActive: false);
                DtmApiRuntime missingOverrideRuntime = StartSourceAuthorityRuntime(gameDir, workshopId, workshopRoot, nativeSnapshotAvailable: true);
                DiscoveredMod missingOverrideSelected = missingOverrideRuntime.CreateSnapshot().DiscoveredMods.Single(mod => mod.Manifest.UniqueID == uniqueId);
                Assert(missingOverrideSelected.Source == "Workshop", "An unavailable legacy Local Development path should leave official source arbitration unchanged.");
                Assert(missingOverrideRuntime.Diagnostics.GetWarnings().Any(warning => warning.Details.Contains("recovery-only", StringComparison.OrdinalIgnoreCase)), "Ignored legacy Local Development state should be explicit in diagnostics.");

                WriteAuthorSourceSelectionState(gameDir, uniqueId, "LocalDevelopment", localRoot, playerReproductionActive: true);
                DtmApiRuntime reproductionRuntime = StartSourceAuthorityRuntime(gameDir, workshopId, workshopRoot, nativeSnapshotAvailable: true);
                DiscoveredMod reproductionSelected = reproductionRuntime.CreateSnapshot().DiscoveredMods.Single(mod => mod.Manifest.UniqueID == uniqueId);
                Assert(reproductionSelected.Source == "Workshop" && reproductionSelected.NativeSubscriptionVerified, "Player Reproduction should suppress all source overrides and restore native Workshop selection.");

                WriteAuthorSourceSelectionState(gameDir, uniqueId, "WorkshopValidation", workshopRoot, playerReproductionActive: false);
                DtmApiRuntime validationRuntime = StartSourceAuthorityRuntime(gameDir, workshopId, workshopRoot, nativeSnapshotAvailable: true);
                Assert(!validationRuntime.CreateSnapshot().DiscoveredMods.Any(mod => mod.Manifest.UniqueID == uniqueId), "Workshop Validation must fail closed without an active startup-authorized author session.");
                Assert(validationRuntime.Diagnostics.GetWarnings().Any(warning => warning.Details.Contains("no active startup-authorized author session", StringComparison.OrdinalIgnoreCase)), "Workshop Validation should diagnose the missing explicit author session.");

                DtmApiRuntime unavailableRuntime = StartSourceAuthorityRuntime(gameDir, workshopId, workshopRoot, nativeSnapshotAvailable: false);
                Assert(!unavailableRuntime.CreateSnapshot().DiscoveredMods.Any(mod => mod.Manifest.UniqueID == uniqueId), "Workshop Validation must fail closed when the native subscription snapshot is unavailable.");
                Assert(unavailableRuntime.Diagnostics.GetWarnings().Any(warning =>
                    warning.Owner == "DTMAPI.ModScanner" &&
                    warning.Details.Contains("Workshop Validation blocked", StringComparison.OrdinalIgnoreCase)),
                    "Workshop Validation fail-closed behavior should remain visible in diagnostics.");

                string otherGameRoot = NewTempGameDir();
                Assert(!string.Equals(
                    AuthorSourceStateStore.GetInstallationStateRoot(gameDir),
                    AuthorSourceStateStore.GetInstallationStateRoot(otherGameRoot),
                    StringComparison.OrdinalIgnoreCase),
                    "Author source state for different game roots must not share an installation journal directory.");

                WriteAuthorSourceSelectionState(gameDir, uniqueId, "LocalDevelopment", localRoot, playerReproductionActive: false, storedGameRoot: otherGameRoot);
                DtmApiRuntime mismatchedStateRuntime = StartSourceAuthorityRuntime(gameDir, workshopId, workshopRoot, nativeSnapshotAvailable: true);
                DiscoveredMod mismatchSelected = mismatchedStateRuntime.CreateSnapshot().DiscoveredMods.Single(mod => mod.Manifest.UniqueID == uniqueId);
                Assert(mismatchSelected.Source == "Workshop", "A source-state file for another game root should fail safely and must not activate its override.");
                Assert(mismatchedStateRuntime.Diagnostics.GetWarnings().Any(warning =>
                    warning.Owner == "DTMAPI.AuthorSource" &&
                    warning.Details.Contains("gameRoot does not match", StringComparison.OrdinalIgnoreCase)),
                    "Rejected source state should be reported as an author-source diagnostic.");
            }
            finally
            {
                Environment.SetEnvironmentVariable("DTMAPI_DOLOC_PERSISTENT_ROOT", previousPersistentRoot);
                Environment.SetEnvironmentVariable("DTMAPI_AUTHOR_STATE_ROOT", previousAuthorRoot);
            }
        }

        private static DtmApiRuntime StartSourceAuthorityRuntime(
            string gameDir,
            ulong workshopId,
            string workshopRoot,
            bool nativeSnapshotAvailable,
            bool nativeEnabled = true,
            int nativePriority = 20)
        {
            var runtime = new DtmApiRuntime(
                new FakeHost(gameDir, includeLegacyDevelopmentModSourceForTests: false),
                new ConfigMenuRegistry());
            runtime.UpdateNativeWorkshopSubscriptions(
                nativeSnapshotAvailable,
                "unit-test-native-owner",
                nativeSnapshotAvailable ? string.Empty : "unit-test-native-owner-unavailable",
                nativeSnapshotAvailable
                    ? new[] { new NativeWorkshopSubscription(workshopId, workshopRoot, nativeEnabled: nativeEnabled, nativePriority: nativePriority, nativeOfficialId: "Workshop." + workshopId.ToString(CultureInfo.InvariantCulture)) }
                    : Array.Empty<NativeWorkshopSubscription>());
            runtime.Start();
            return runtime;
        }

        private static void WriteSourceAuthorityContentPack(string root, string uniqueId, string name)
        {
            Directory.CreateDirectory(root);
            File.WriteAllText(
                Path.Combine(root, "manifest.json"),
                "{ \"Name\": \"" + name + "\", \"Author\": \"DTMAPI\", \"Version\": \"1.0.0\", \"UniqueID\": \"" + uniqueId + "\", \"Type\": \"ContentPack\" }");
        }

        private static void WriteAuthorSourceSelectionState(
            string gameDir,
            string uniqueId,
            string mode,
            string sourcePath,
            bool playerReproductionActive,
            string? storedGameRoot = null,
            string? expectedTreeSha256 = null)
        {
            string statePath = AuthorSourceStateStore.GetSourceStatePath(gameDir);
            Directory.CreateDirectory(Path.GetDirectoryName(statePath) ?? throw new InvalidOperationException("Author source state directory is unavailable."));
            string treeSha256 = expectedTreeSha256 ?? (Directory.Exists(sourcePath) ? AuthorFileTreeDigest.Compute(sourcePath) : string.Empty);
            File.WriteAllText(
                statePath,
                "{ \"schemaVersion\": 1, \"gameRoot\": \"" + JsonEscapeForTest(storedGameRoot ?? gameDir) +
                "\", \"playerReproductionActive\": " + (playerReproductionActive ? "true" : "false") +
                ", \"reproductionSnapshotId\": \"unit-test-snapshot\", \"selections\": [{ \"uniqueId\": \"" + JsonEscapeForTest(uniqueId) +
                "\", \"mode\": \"" + JsonEscapeForTest(mode) + "\", \"sourcePath\": \"" + JsonEscapeForTest(sourcePath) +
                "\", \"expectedTreeSha256\": \"" + JsonEscapeForTest(treeSha256) + "\" }] }");
        }

        private static string JsonEscapeForTest(string value) => (value ?? string.Empty)
            .Replace("\\", "\\\\")
            .Replace("\"", "\\\"");

        private static bool PathsEqualForTest(string left, string right) => string.Equals(
            Path.GetFullPath(left).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar),
            Path.GetFullPath(right).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar),
            StringComparison.OrdinalIgnoreCase);

        private static void BootstrapDefersNativeSourceCaptureUntilNativeReadyLifecycle()
        {
            string repo = FindRepositoryRoot();
            string bootstrap = File.ReadAllText(Path.Combine(repo, "src", "DTMAPI.BepInExBootstrap", "BootstrapPlugin.cs"));
            int awakeStart = bootstrap.IndexOf("public void Awake()", StringComparison.Ordinal);
            int awakeEnd = bootstrap.IndexOf("private TitleReturnObjectGraphSection", awakeStart, StringComparison.Ordinal);
            int startStart = bootstrap.IndexOf("public void Start()", StringComparison.Ordinal);
            int startEnd = bootstrap.IndexOf("public void Update()", startStart, StringComparison.Ordinal);
            Assert(awakeStart >= 0 && awakeEnd > awakeStart && startStart >= 0 && startEnd > startStart, "Bootstrap lifecycle source boundaries should remain inspectable.");

            string awake = bootstrap.Substring(awakeStart, awakeEnd - awakeStart);
            string start = bootstrap.Substring(startStart, startEnd - startStart);
            Assert(!awake.Contains("CaptureNativeWorkshopSubscriptions", StringComparison.Ordinal) &&
                !awake.Contains("runtime.Start();", StringComparison.Ordinal) &&
                !awake.Contains("bridge.Initialize();", StringComparison.Ordinal),
                "Bootstrap Awake must only prepare objects; native ModManager does not exist until the game's Awake initialization completes.");

            int capture = start.IndexOf("CaptureNativeWorkshopSubscriptions(\"Bootstrap.\" + source + \".PreRuntime\")", StringComparison.Ordinal);
            int prepareQaSaveGuard = start.IndexOf("bridge.PrepareQaHostBeforeRuntimeStart();", StringComparison.Ordinal);
            int runtimeStartEntered = start.IndexOf("runtimeStartEntered = true;", StringComparison.Ordinal);
            int runtimeStart = start.IndexOf("runtime.Start();", StringComparison.Ordinal);
            int bridgeInitialize = start.IndexOf("bridge.Initialize();", StringComparison.Ordinal);
            Assert(capture >= 0 && prepareQaSaveGuard > capture && runtimeStartEntered > prepareQaSaveGuard &&
                runtimeStart > runtimeStartEntered && bridgeInitialize > runtimeStart,
                "The native-ready one-shot lifecycle must capture source authority, install the receipt-bound QA save guard before Core Mod discovery, and initialize ordinary GameBridge Harmony only after Runtime Start.");
            int preRuntimeAbort = start.IndexOf("bridge?.AbortQaHostBeforeRuntimeStart(ex.GetType().Name)", StringComparison.Ordinal);
            int postRuntimeRetain = start.IndexOf("bridge?.RetainQaHostAndRequestApplicationQuitAfterRuntimeStartFailure(ex.GetType().Name)", StringComparison.Ordinal);
            Assert(start.Contains("if (!runtimeStartEntered)", StringComparison.Ordinal) &&
                preRuntimeAbort > bridgeInitialize && postRuntimeRetain > preRuntimeAbort,
                "Bootstrap must release the optional pre-Runtime QA owner only before Runtime Start is entered; every later failure must retain isolation and request bounded process exit.");
            Assert(bootstrap.Contains("TryStartRuntimeOnce(\"Unity.Start\")", StringComparison.Ordinal) &&
                bootstrap.Contains("TryStartRuntimeOnce(\"Unity.Update.FirstFrame\")", StringComparison.Ordinal) &&
                bootstrap.Contains("TryStartRuntimeOnce(\"PlayerLoop.FirstFrame\")", StringComparison.Ordinal) &&
                start.Contains("startupAttempted", StringComparison.Ordinal) && start.Contains("if (initialized)", StringComparison.Ordinal),
                "Bootstrap must use the existing first PlayerLoop frame when ordinary Unity callbacks are unavailable and refuse a partial retry without recurring readiness polling.");
            Assert(awake.Contains("TryInstallPlayerLoopFrameDriver();", StringComparison.Ordinal),
                "Awake must install the existing PlayerLoop driver early enough to provide the one-shot native-ready callback.");

            string analyzer = File.ReadAllText(Path.Combine(repo, "tools", "scripts", "analyze-startup-evidence.ps1"));
            int currentMetric = analyzer.IndexOf("Bootstrap\\.StartRuntime totalMs", StringComparison.Ordinal);
            int historicalMetric = analyzer.IndexOf("Bootstrap\\.Awake totalMs", StringComparison.Ordinal);
            Assert(currentMetric >= 0 && historicalMetric > currentMetric,
                "Startup evidence analysis must prefer the StartRuntime metric while preserving historical Awake evidence compatibility.");
        }

        private static void OfficialModUiWorkshopRefreshCommitsOnlyAfterSuccessfulCloseSave()
        {
            string gameDir = NewTempGameDir();
            string persistentRoot = Path.Combine(
                Path.GetTempPath(),
                "DTMAPI-tests-persistent",
                Guid.NewGuid().ToString("N"));
            string authorStateRoot = Path.Combine(
                Path.GetTempPath(),
                "DTMAPI-tests-author-state",
                Guid.NewGuid().ToString("N"));
            string? previousPersistentRoot = Environment.GetEnvironmentVariable(
                "DTMAPI_DOLOC_PERSISTENT_ROOT");
            string? previousAuthorRoot = Environment.GetEnvironmentVariable(
                "DTMAPI_AUTHOR_STATE_ROOT");
            const ulong committedId = 3749000101UL;
            const ulong candidateId = 3749000102UL;
            try
            {
                Environment.SetEnvironmentVariable(
                    "DTMAPI_DOLOC_PERSISTENT_ROOT",
                    persistentRoot);
                Environment.SetEnvironmentVariable(
                    "DTMAPI_AUTHOR_STATE_ROOT",
                    authorStateRoot);

                var runtime = new DtmApiRuntime(
                    new FakeHost(gameDir),
                    new ConfigMenuRegistry());
                var bridge = new DolocTownGameBridge(runtime);
                var committedManager = new FakeNativeModManager(
                    new FakePublishedFileId(committedId),
                    Path.Combine(gameDir, committedId.ToString(CultureInfo.InvariantCulture)),
                    () => new ArrayList());
                var candidateManager = new FakeNativeModManager(
                    new FakePublishedFileId(candidateId),
                    Path.Combine(gameDir, candidateId.ToString(CultureInfo.InvariantCulture)),
                    () => new ArrayList());

                Assert(bridge.CaptureNativeWorkshopSubscriptions(
                        "unit-official-ui-initial",
                        committedManager,
                        requireSteamInitialized: false),
                    "The official-UI transaction fixture must publish an initial committed native snapshot.");
                runtime.Start();
                string snapshotPath = AuthorSourceStateStore.GetWorkshopSnapshotPath(gameDir);
                Assert(File.ReadAllText(snapshotPath).Contains(
                        committedId.ToString(CultureInfo.InvariantCulture),
                        StringComparison.Ordinal),
                    "The initial committed Workshop source authority should be observable before opening the official UI.");

                object previewUi = new object();
                bridge.BeginOfficialModUiTransaction(previewUi);
                bridge.HandleNativeModManagerReloaded(
                    candidateManager,
                    requireSteamInitialized: false);
                Assert(bridge.OfficialModUiTransactionActiveForTests &&
                    !bridge.OfficialModUiCommitPendingForTests &&
                    File.ReadAllText(snapshotPath).Contains(
                        committedId.ToString(CultureInfo.InvariantCulture),
                        StringComparison.Ordinal),
                    "Opening the official UI must stage only a preview and retain the committed source snapshot.");

                bridge.BeginOfficialModUiClose(previewUi);
                bridge.HandleNativeModManagerReloaded(
                    candidateManager,
                    requireSteamInitialized: false);
                bridge.ObserveOfficialModManagerSave(candidateManager, succeeded: false);
                bridge.CompleteOfficialModUiClose(previewUi);
                bridge.Update();
                Assert(!bridge.OfficialModUiTransactionActiveForTests &&
                    !bridge.OfficialModUiCommitPendingForTests &&
                    File.ReadAllText(snapshotPath).Contains(
                        committedId.ToString(CultureInfo.InvariantCulture),
                        StringComparison.Ordinal),
                    "A failed native SaveModManager result must discard the close candidate without refreshing DTMAPI.");

                object mismatchedUi = new object();
                bridge.BeginOfficialModUiTransaction(mismatchedUi);
                bridge.HandleNativeModManagerReloaded(
                    candidateManager,
                    requireSteamInitialized: false);
                bridge.BeginOfficialModUiClose(mismatchedUi);
                bridge.HandleNativeModManagerReloaded(
                    candidateManager,
                    requireSteamInitialized: false);
                bridge.ObserveOfficialModManagerSave(committedManager, succeeded: true);
                bridge.CompleteOfficialModUiClose(mismatchedUi);
                Assert(!bridge.OfficialModUiCommitPendingForTests,
                    "A successful save for a different ModManager instance must not authorize the official UI candidate.");

                object committedUi = new object();
                bridge.BeginOfficialModUiTransaction(committedUi);
                bridge.HandleNativeModManagerReloaded(
                    candidateManager,
                    requireSteamInitialized: false);
                bridge.BeginOfficialModUiClose(committedUi);
                bridge.HandleNativeModManagerReloaded(
                    candidateManager,
                    requireSteamInitialized: false);
                bridge.ObserveOfficialModManagerSave(candidateManager, succeeded: true);
                bridge.CompleteOfficialModUiClose(committedUi);
                Assert(bridge.OfficialModUiCommitPendingForTests &&
                    File.ReadAllText(snapshotPath).Contains(
                        committedId.ToString(CultureInfo.InvariantCulture),
                        StringComparison.Ordinal),
                    "A successful close must defer publication until the next GameBridge frame.");

                bridge.Update();
                string committedText = File.ReadAllText(snapshotPath);
                Assert(!bridge.OfficialModUiCommitPendingForTests &&
                    committedText.Contains(
                        candidateId.ToString(CultureInfo.InvariantCulture),
                        StringComparison.Ordinal) &&
                    !committedText.Contains(
                        committedId.ToString(CultureInfo.InvariantCulture),
                        StringComparison.Ordinal),
                    "The next GameBridge frame must publish exactly the successful close candidate.");
                runtime.NotifyRuntimeShutdown("unit-official-mod-ui-commit");
            }
            finally
            {
                Environment.SetEnvironmentVariable(
                    "DTMAPI_DOLOC_PERSISTENT_ROOT",
                    previousPersistentRoot);
                Environment.SetEnvironmentVariable(
                    "DTMAPI_AUTHOR_STATE_ROOT",
                    previousAuthorRoot);
            }
        }

        private static void NativeWorkshopOptionalInfoFailureRetainsRequiredAuthorityWithoutInventingEnablement()
        {
            string? previousPersistentRoot = Environment.GetEnvironmentVariable("DTMAPI_DOLOC_PERSISTENT_ROOT");
            string? previousAuthorRoot = Environment.GetEnvironmentVariable("DTMAPI_AUTHOR_STATE_ROOT");
            try
            {
                const ulong failingWorkshopId = 3749000025UL;
                string failingGameDir = NewTempGameDir();
                string failingPersistentRoot = Path.Combine(Path.GetTempPath(), "DTMAPI-tests-persistent", Guid.NewGuid().ToString("N"));
                string failingAuthorRoot = Path.Combine(Path.GetTempPath(), "DTMAPI-tests-author-state", Guid.NewGuid().ToString("N"));
                string failingUniqueId = "Yuuka.DTMAPI.NativeInfoFailure";
                string failingWorkshopRoot = Path.Combine(failingGameDir, "steamapps", "workshop", "content", "2285550", failingWorkshopId.ToString(CultureInfo.InvariantCulture));
                WriteSourceAuthorityContentPack(failingWorkshopRoot, failingUniqueId, "Optional native-info failure");
                Environment.SetEnvironmentVariable("DTMAPI_DOLOC_PERSISTENT_ROOT", failingPersistentRoot);
                Environment.SetEnvironmentVariable("DTMAPI_AUTHOR_STATE_ROOT", failingAuthorRoot);
                WriteOfficialModInfos(failingPersistentRoot, new OfficialModInfoTestEntry("Workshop." + failingWorkshopId.ToString(CultureInfo.InvariantCulture), true, "Workshop"));

                var failingRuntime = new DtmApiRuntime(new FakeHost(failingGameDir), new ConfigMenuRegistry());
                var failingBridge = new DolocTownGameBridge(failingRuntime);
                var failingManager = new FakeNativeModManager(
                    new FakePublishedFileId(failingWorkshopId),
                    failingWorkshopRoot,
                    () => throw new NullReferenceException("unit-native-info-not-ready"));
                Assert(failingBridge.CaptureNativeWorkshopSubscriptions("unit-test-native-info-failure", failingManager, requireSteamInitialized: false),
                    "Optional GetAllValidModInfos failure must not discard subscribed ID and exact install-root authority.");
                failingRuntime.Start();
                DiscoveredMod failingSelected = failingRuntime.CreateSnapshot().DiscoveredMods.Single(mod => mod.Manifest.UniqueID == failingUniqueId);
                Assert(failingSelected.NativeSubscriptionVerified && failingSelected.OfficialEnabled,
                    "Verified subscription/root should retain the official enabled state when optional native-info enrichment fails.");
                string failingPersisted = File.ReadAllText(AuthorSourceStateStore.GetWorkshopSnapshotPath(failingGameDir));
                Assert(failingPersisted.Contains("\"available\":true", StringComparison.OrdinalIgnoreCase) &&
                    failingPersisted.Contains("\"nativeInfoAvailable\":false", StringComparison.OrdinalIgnoreCase) &&
                    failingPersisted.Contains(JsonEscapeForTest(failingWorkshopRoot), StringComparison.OrdinalIgnoreCase) &&
                    failingPersisted.Contains("GetAllValidModInfos enrichment failed", StringComparison.Ordinal),
                    "Partial native-info failure evidence must persist an available required snapshot, exact root, nullable enablement and stage-qualified failure.");
                failingRuntime.NotifyRuntimeShutdown("unit-native-info-failure");

                WriteOfficialModInfos(failingPersistentRoot, new OfficialModInfoTestEntry("Workshop." + failingWorkshopId.ToString(CultureInfo.InvariantCulture), false, "Workshop"));
                var disabledRuntime = new DtmApiRuntime(new FakeHost(failingGameDir), new ConfigMenuRegistry());
                var disabledBridge = new DolocTownGameBridge(disabledRuntime);
                Assert(disabledBridge.CaptureNativeWorkshopSubscriptions("unit-test-native-info-failure-disabled", failingManager, requireSteamInitialized: false),
                    "The required snapshot should remain capturable for an officially disabled row.");
                disabledRuntime.Start();
                DiscoveredMod disabledSelected = disabledRuntime.CreateSnapshot().DiscoveredMods.Single(mod => mod.Manifest.UniqueID == failingUniqueId);
                Assert(disabledSelected.NativeSubscriptionVerified && !disabledSelected.OfficialEnabled,
                    "Unknown optional native enablement must never be invented as true over an official disabled state.");
                disabledRuntime.NotifyRuntimeShutdown("unit-native-info-failure-disabled");

                const ulong emptyWorkshopId = 3749000026UL;
                string emptyGameDir = NewTempGameDir();
                string emptyPersistentRoot = Path.Combine(Path.GetTempPath(), "DTMAPI-tests-persistent", Guid.NewGuid().ToString("N"));
                string emptyAuthorRoot = Path.Combine(Path.GetTempPath(), "DTMAPI-tests-author-state", Guid.NewGuid().ToString("N"));
                string emptyUniqueId = "Yuuka.DTMAPI.NativeInfoEmpty";
                string emptyWorkshopRoot = Path.Combine(emptyGameDir, "steamapps", "workshop", "content", "2285550", emptyWorkshopId.ToString(CultureInfo.InvariantCulture));
                WriteSourceAuthorityContentPack(emptyWorkshopRoot, emptyUniqueId, "Successful empty native-info snapshot");
                Environment.SetEnvironmentVariable("DTMAPI_DOLOC_PERSISTENT_ROOT", emptyPersistentRoot);
                Environment.SetEnvironmentVariable("DTMAPI_AUTHOR_STATE_ROOT", emptyAuthorRoot);
                WriteOfficialModInfos(emptyPersistentRoot, new OfficialModInfoTestEntry("Workshop." + emptyWorkshopId.ToString(CultureInfo.InvariantCulture), true, "Workshop"));
                var emptyRuntime = new DtmApiRuntime(new FakeHost(emptyGameDir), new ConfigMenuRegistry());
                var emptyBridge = new DolocTownGameBridge(emptyRuntime);
                var emptyManager = new FakeNativeModManager(new FakePublishedFileId(emptyWorkshopId), emptyWorkshopRoot, () => new ArrayList());
                Assert(emptyBridge.CaptureNativeWorkshopSubscriptions("unit-test-native-info-empty", emptyManager, requireSteamInitialized: false), "A successful empty native-info snapshot should retain required subscription authority.");
                emptyRuntime.Start();
                DiscoveredMod emptySelected = emptyRuntime.CreateSnapshot().DiscoveredMods.Single(mod => mod.Manifest.UniqueID == emptyUniqueId);
                Assert(emptySelected.NativeSubscriptionVerified && !emptySelected.OfficialEnabled,
                    "A successful native-info call with no matching valid row must remain fail-closed instead of using the partial-failure fallback.");
                emptyRuntime.NotifyRuntimeShutdown("unit-native-info-empty");

                const ulong nullRowWorkshopId = 3749000027UL;
                string nullRowGameDir = NewTempGameDir();
                string nullRowPersistentRoot = Path.Combine(Path.GetTempPath(), "DTMAPI-tests-persistent", Guid.NewGuid().ToString("N"));
                string nullRowAuthorRoot = Path.Combine(Path.GetTempPath(), "DTMAPI-tests-author-state", Guid.NewGuid().ToString("N"));
                string nullRowUniqueId = "Yuuka.DTMAPI.NativeInfoNullRow";
                string nullRowWorkshopRoot = Path.Combine(nullRowGameDir, "steamapps", "workshop", "content", "2285550", nullRowWorkshopId.ToString(CultureInfo.InvariantCulture));
                WriteSourceAuthorityContentPack(nullRowWorkshopRoot, nullRowUniqueId, "Null native-info row");
                Environment.SetEnvironmentVariable("DTMAPI_DOLOC_PERSISTENT_ROOT", nullRowPersistentRoot);
                Environment.SetEnvironmentVariable("DTMAPI_AUTHOR_STATE_ROOT", nullRowAuthorRoot);
                WriteOfficialModInfos(nullRowPersistentRoot, new OfficialModInfoTestEntry("Workshop." + nullRowWorkshopId.ToString(CultureInfo.InvariantCulture), false, "Workshop"));
                var nullRowRuntime = new DtmApiRuntime(new FakeHost(nullRowGameDir), new ConfigMenuRegistry());
                var nullRowBridge = new DolocTownGameBridge(nullRowRuntime);
                var nullRowManager = new FakeNativeModManager(
                    new FakePublishedFileId(nullRowWorkshopId),
                    nullRowWorkshopRoot,
                    () => new ArrayList
                    {
                        null,
                        new FakeNativeModInfo("Workshop." + nullRowWorkshopId.ToString(CultureInfo.InvariantCulture), true, 23, nullRowWorkshopId, nullRowWorkshopRoot)
                    });
                Assert(nullRowBridge.CaptureNativeWorkshopSubscriptions("unit-test-native-info-null-row", nullRowManager, requireSteamInitialized: false), "Null optional native-info rows should be skipped without poisoning later valid rows.");
                nullRowRuntime.Start();
                DiscoveredMod nullRowSelected = nullRowRuntime.CreateSnapshot().DiscoveredMods.Single(mod => mod.Manifest.UniqueID == nullRowUniqueId);
                Assert(nullRowSelected.NativeSubscriptionVerified && nullRowSelected.OfficialEnabled,
                    "A later valid native row should supersede stale official disablement after a null row is skipped.");
                string nullRowPersisted = File.ReadAllText(AuthorSourceStateStore.GetWorkshopSnapshotPath(nullRowGameDir));
                Assert(nullRowPersisted.Contains("\"nativeInfoAvailable\":true", StringComparison.OrdinalIgnoreCase) &&
                    nullRowPersisted.Contains("\"nativePriority\":23", StringComparison.OrdinalIgnoreCase),
                    "Null-row handling must still persist the later valid native enablement and priority.");
                nullRowRuntime.NotifyRuntimeShutdown("unit-native-info-null-row");
            }
            finally
            {
                Environment.SetEnvironmentVariable("DTMAPI_DOLOC_PERSISTENT_ROOT", previousPersistentRoot);
                Environment.SetEnvironmentVariable("DTMAPI_AUTHOR_STATE_ROOT", previousAuthorRoot);
            }
        }

        private static void NativeWorkshopBridgeUsesCurrentModManagerStateInsteadOfStaleEnablementFile()
        {
            string gameDir = NewTempGameDir();
            string persistentRoot = Path.Combine(Path.GetTempPath(), "DTMAPI-tests-persistent", Guid.NewGuid().ToString("N"));
