        private static void WriteAuthorSessionDescriptor(
            string gameDir,
            string sessionId,
            string token,
            string pipeName,
            TimeSpan? lifetime = null)
        {
            string path = AuthorSourceStateStore.GetAuthorSessionPath(gameDir);
            Directory.CreateDirectory(Path.GetDirectoryName(path) ?? throw new InvalidOperationException("Author session state directory is unavailable."));
            DateTimeOffset now = DateTimeOffset.UtcNow;
            File.WriteAllText(
                path,
                "{ \"schemaVersion\": 1, \"gameRoot\": \"" + JsonEscapeForTest(gameDir) +
                "\", \"runtimeVersion\": \"" + DtmApiRuntime.ApiVersion +
                "\", \"sessionId\": \"" + sessionId +
                "\", \"token\": \"" + token +
                "\", \"pipeName\": \"" + pipeName +
                "\", \"createdAtUtc\": \"" + now.AddSeconds(-1).ToString("O", CultureInfo.InvariantCulture) +
                "\", \"expiresAtUtc\": \"" + now.Add(lifetime ?? TimeSpan.FromMinutes(5)).ToString("O", CultureInfo.InvariantCulture) + "\" }");
        }

        private static string BuildAuthorSessionRequest(
            string gameDir,
            string sessionId,
            string token,
            string requestId,
            string uniqueId,
            string selectedRoot,
            string expectedTreeSha256,
            string operation,
            string? runtimeVersion = null,
            string? requestGameRoot = null)
        {
            return "{ \"protocol\": \"dtmapi-author-session/1\", \"runtime\": \"" + (runtimeVersion ?? DtmApiRuntime.ApiVersion) +
                "\", \"gameRoot\": \"" + JsonEscapeForTest(requestGameRoot ?? gameDir) +
                "\", \"session\": \"" + sessionId +
                "\", \"token\": \"" + token +
                "\", \"requestId\": \"" + requestId +
                "\", \"uniqueId\": \"" + JsonEscapeForTest(uniqueId) +
                "\", \"selectedRoot\": \"" + JsonEscapeForTest(selectedRoot) +
                "\", \"expectedTreeSha256\": \"" + expectedTreeSha256 +
                "\", \"operation\": \"" + operation + "\" }";
        }

        private static string SendAuthorSessionRequestThroughRuntime(DtmApiRuntime runtime, string pipeName, string request)
        {
            string response = string.Empty;
            Exception? clientFailure = null;
            var clientThread = new Thread(() =>
            {
                try
                {
                    response = SendAuthorSessionRequest(pipeName, request);
                }
                catch (Exception ex)
                {
                    clientFailure = ex;
                }
            }) { IsBackground = true };
            clientThread.Start();

            DateTimeOffset deadline = DateTimeOffset.UtcNow.AddSeconds(5);
            while ((runtime.AuthorSessionSnapshot?.Pending ?? 0) == 0 && clientFailure == null && DateTimeOffset.UtcNow < deadline)
                Thread.Sleep(10);
            Assert((runtime.AuthorSessionSnapshot?.Pending ?? 0) == 1, "The authenticated author request should reach the bounded Runtime queue.");
            runtime.Update();
            Assert(clientThread.Join(TimeSpan.FromSeconds(5)), "The author request should receive a bounded Runtime-thread response.");
            if (clientFailure != null)
                throw new InvalidOperationException("Author-session client failed.", clientFailure);
            return response;
        }

        private static string SendAuthorSessionRequest(string pipeName, string request)
        {
            using var client = new NamedPipeClientStream(".", pipeName, PipeDirection.InOut, PipeOptions.None);
            client.Connect(5000);
            using var writer = new StreamWriter(client, new UTF8Encoding(false), 4096, leaveOpen: true) { AutoFlush = true };
            writer.WriteLine(request);
            using var reader = new StreamReader(client, new UTF8Encoding(false), detectEncodingFromByteOrderMarks: false, 4096, leaveOpen: true);
            return reader.ReadLine() ?? throw new InvalidDataException("Author-session pipe returned no response frame.");
        }

        private static void DuplicateCodeModSourceIdentityChangeRequiresRestart()
        {
            string gameDir = NewTempGameDir();
            string persistentRoot = Path.Combine(Path.GetTempPath(), "DTMAPI-tests-persistent", Guid.NewGuid().ToString("N"));
            const string ownerId = "DTMAPI.Tests.DuplicateIdentitySwitch";
            const string packageFolder = "DTMAPI_DuplicateIdentitySwitch";
            const ulong workshopId = 3749000010UL;
            string officialId = "Local." + packageFolder;
            string workshopOfficialId = "Workshop." + workshopId.ToString(CultureInfo.InvariantCulture);
            string officialRoot = Path.Combine(persistentRoot, "MODS", packageFolder);
            string workshopRoot = Path.Combine(gameDir, "steamapps", "workshop", "content", "2285550", workshopId.ToString(CultureInfo.InvariantCulture));
            WriteDuplicateCodeProbePackage(officialRoot, ownerId, "official-source");
            WriteDuplicateCodeProbePackage(workshopRoot, ownerId, "workshop-source");
            PrepareFileSinkFailure(gameDir);

            string? previousRoot = Environment.GetEnvironmentVariable("DTMAPI_DOLOC_PERSISTENT_ROOT");
            try
            {
                Environment.SetEnvironmentVariable("DTMAPI_DOLOC_PERSISTENT_ROOT", persistentRoot);
                WriteOfficialModInfos(
                    persistentRoot,
                    new OfficialModInfoTestEntry(officialId, true, "Local"),
                    new OfficialModInfoTestEntry(workshopOfficialId, false, "Workshop"));
                AtomicOwnerProbeMod.EntryCount = 0;

                var runtime = new DtmApiRuntime(new ThrowingLogHost(gameDir), new ConfigMenuRegistry());
                runtime.UpdateNativeWorkshopSubscriptions(
                    available: true,
                    source: "unit-test-no-active-workshop-subscription",
                    failure: string.Empty,
                    subscriptions: Array.Empty<NativeWorkshopSubscription>());
                runtime.Start();
                DiscoveredMod initialLoaded = runtime.LoadedMods.Single(mod => mod.Manifest.UniqueID == ownerId);
                Assert(initialLoaded.Source == "Local" && initialLoaded.OfficialId == officialId && PathsEqual(initialLoaded.RootPath, officialRoot), "The duplicate-source fixture should initially load the enabled official Local identity.");
                Assert(AtomicOwnerProbeMod.EntryCount == 1 && CountCoreOwnerRootsForTest(runtime, ownerId) > 0, "The initial duplicate owner should execute Entry once and publish ordinary roots.");
                IContentAssetInfo initialAsset = GetContent(runtime).FindAssets("txt").Single(asset => asset.SourceModId == ownerId && asset.RelativePath.EndsWith("source-identity.txt", StringComparison.OrdinalIgnoreCase));
                Assert(File.ReadAllText(initialAsset.SourcePath) == "official-source" && IsPathUnder(initialAsset.SourcePath, officialRoot), "Initial Content publication should come only from the loaded official Local root.");

                WriteOfficialModInfos(
                    persistentRoot,
                    new OfficialModInfoTestEntry(officialId, false, "Local"),
                    new OfficialModInfoTestEntry(workshopOfficialId, true, "Workshop"));
                runtime.UpdateNativeWorkshopSubscriptions(
                    available: true,
                    source: "unit-test-workshop-subscription-enabled",
                    failure: string.Empty,
                    subscriptions: new[]
                    {
                        new NativeWorkshopSubscription(
                            workshopId,
                            workshopRoot,
                            nativeEnabled: true,
                            nativePriority: -1,
                            nativeOfficialId: workshopOfficialId)
                    });
                runtime.NotifyWorkshopModListChanged();

                DiscoveredMod selectedAfterRefresh = runtime.DiscoveredMods.Single(mod => mod.Manifest.UniqueID == ownerId);
                Assert(selectedAfterRefresh.Source == "Workshop" && selectedAfterRefresh.OfficialId == workshopOfficialId && PathsEqual(selectedAfterRefresh.RootPath, workshopRoot), "Refresh should select the newly enabled Workshop duplicate identity.");
                Assert(!runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == ownerId) && runtime.OwnerRequiresRestart(ownerId), "A loaded code owner whose RootPath/Source/OfficialId identity changes must deactivate and remain restart-required in the same process.");
                Assert(AtomicOwnerProbeMod.EntryCount == 1 && CountCoreOwnerRootsForTest(runtime, ownerId) == 0, "Duplicate source handoff must clean all old-owner roots without executing Entry from the replacement source.");
                Assert(!GetContent(runtime).FindAssets("txt").Any(asset => asset.SourceModId == ownerId), "Same-process source handoff must publish neither stale old-source Content nor replacement-source Content before restart.");
                IDtmModStatusInfo restartStatus = runtime.CreateDiagnosticsSnapshot().Mods.Single(status => status.UniqueID == ownerId);
                Assert(restartStatus.StatusCode == "restart-required", "Duplicate source identity handoff should expose restart-required diagnostics.");

                runtime.NotifyWorkshopModListChanged();
                Assert(!runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == ownerId) && AtomicOwnerProbeMod.EntryCount == 1 && CountCoreOwnerRootsForTest(runtime, ownerId) == 0, "Repeated same-process refresh must not re-enter or republish the replacement duplicate source.");

                var restartedRuntime = new DtmApiRuntime(new ThrowingLogHost(gameDir), new ConfigMenuRegistry());
                restartedRuntime.UpdateNativeWorkshopSubscriptions(
                    available: true,
                    source: "unit-test-workshop-subscription-enabled-after-restart",
                    failure: string.Empty,
                    subscriptions: new[]
                    {
                        new NativeWorkshopSubscription(
                            workshopId,
                            workshopRoot,
                            nativeEnabled: true,
                            nativePriority: -1,
                            nativeOfficialId: workshopOfficialId)
                    });
                restartedRuntime.Start();
                DiscoveredMod restartedLoaded = restartedRuntime.LoadedMods.Single(mod => mod.Manifest.UniqueID == ownerId);
                Assert(restartedLoaded.Source == "Workshop" && restartedLoaded.OfficialId == workshopOfficialId && PathsEqual(restartedLoaded.RootPath, workshopRoot), "A clean runtime should load the selected Workshop replacement identity.");
                Assert(AtomicOwnerProbeMod.EntryCount == 2 && !restartedRuntime.OwnerRequiresRestart(ownerId), "The replacement source should execute Entry only in the clean runtime lifetime.");
                IContentAssetInfo restartedAsset = GetContent(restartedRuntime).FindAssets("txt").Single(asset => asset.SourceModId == ownerId && asset.RelativePath.EndsWith("source-identity.txt", StringComparison.OrdinalIgnoreCase));
                Assert(File.ReadAllText(restartedAsset.SourcePath) == "workshop-source" && IsPathUnder(restartedAsset.SourcePath, workshopRoot), "The clean runtime should publish Content only from the selected Workshop replacement root.");
            }
            finally
            {
                Environment.SetEnvironmentVariable("DTMAPI_DOLOC_PERSISTENT_ROOT", previousRoot);
            }
        }

        private static void NonCodeContentPackCanDisableAndRepublishInProcess()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                const string ownerId = "DTMAPI.Tests.ReloadableContentPack";
                string modDir = Path.Combine(dir, "Mods", "ReloadableContentPack");
                Directory.CreateDirectory(modDir);
                File.WriteAllText(
                    Path.Combine(modDir, "manifest.json"),
                    "{ \"Name\": \"Reloadable Content Pack\", \"Author\": \"DTMAPI\", \"Version\": \"1.0.0\", \"UniqueID\": \"" + ownerId + "\", \"Type\": \"ContentPack\" }");
                File.WriteAllText(Path.Combine(modDir, "reloadable-content.txt"), "content-pack-active");

                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                runtime.Start();
                Assert(runtime.LoadedMods.Count(mod => mod.Manifest.UniqueID == ownerId) == 1 && !runtime.OwnerRequiresRestart(ownerId), "An enabled non-code ContentPack should publish without a restart gate.");
                Assert(CountCoreOwnerRootsForTest(runtime, ownerId) > 0 && GetContent(runtime).FindAssets("txt").Any(asset => asset.SourceModId == ownerId), "The active ContentPack should publish loaded-registry and Content roots.");

                string disabledMarker = Path.Combine(modDir, "dtmapi.disabled");
                File.WriteAllText(disabledMarker, "disable non-code owner");
                runtime.NotifyWorkshopModListChanged();
                Assert(!runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == ownerId) && CountCoreOwnerRootsForTest(runtime, ownerId) == 0, "Disabling a non-code ContentPack should immediately remove all owner roots and Content publication.");
                Assert(!runtime.OwnerRequiresRestart(ownerId), "A non-code owner with zero remaining roots should not require restart.");
                Assert(!GetContent(runtime).FindAssets("txt").Any(asset => asset.SourceModId == ownerId), "Disabled ContentPack assets must not remain in the active Content query root.");

                File.Delete(disabledMarker);
                runtime.NotifyWorkshopModListChanged();
                Assert(runtime.LoadedMods.Count(mod => mod.Manifest.UniqueID == ownerId) == 1 && !runtime.OwnerRequiresRestart(ownerId), "The same process should republish a re-enabled non-code ContentPack.");
                Assert(CountCoreOwnerRootsForTest(runtime, ownerId) > 0 &&
                    GetContent(runtime).FindAssets("txt").Count(asset => asset.SourceModId == ownerId && asset.RelativePath.EndsWith("reloadable-content.txt", StringComparison.OrdinalIgnoreCase)) == 1,
                    "Re-enabled ContentPack publication should restore one authoritative Content asset without duplication.");

                runtime.NotifyWorkshopModListChanged();
                Assert(runtime.LoadedMods.Count(mod => mod.Manifest.UniqueID == ownerId) == 1 && !runtime.OwnerRequiresRestart(ownerId), "Repeated ContentPack refresh should remain active and idempotent.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void WorkshopReloadHotLoadsNewlyEnabledCodeModOnceAndLocksDisabledLoadedMod()
        {
            string gameDir = NewTempGameDir();
            string persistentRoot = Path.Combine(Path.GetTempPath(), "DTMAPI-tests-persistent", Guid.NewGuid().ToString("N"));
            string packageRoot = Path.Combine(persistentRoot, "MODS", "Yuuka_DTMAPI_HotLoad");
            string contentRoot = Path.Combine(packageRoot, "Content", "DTMAPI");
            Directory.CreateDirectory(contentRoot);

            string assemblyPath = typeof(HotLoadProbeMod).Assembly.Location;
            string assemblyName = Path.GetFileName(assemblyPath);
            File.Copy(assemblyPath, Path.Combine(contentRoot, assemblyName), overwrite: true);
            File.WriteAllText(
                Path.Combine(contentRoot, "manifest.json"),
                    "{ \"Name\": \"Hot Load Test\", \"Author\": \"DTMAPI\", \"Version\": \"1.0.0\", \"UniqueID\": \"DTMAPI.Tests.HotLoad\", \"EntryDll\": \"Content/DTMAPI/" + assemblyName + "\", \"EntryType\": \"" + (typeof(HotLoadProbeMod).FullName ?? nameof(HotLoadProbeMod)) + "\", \"Type\": \"CodeMod\", \"CodeModKind\": \"Strict\" }");
            const string contentItemId = "dtmapi_owner_lifetime_hot_item";
            File.WriteAllText(
                Path.Combine(contentRoot, "item_tbitem.json"),
                "[{ \"id\": \"" + contentItemId + "\", \"sub_type\": \"material\", \"title\": { \"text\": \"Owner 生命周期物品\", \"english\": \"Owner Lifetime Item\" } }]");

            string? previousRoot = Environment.GetEnvironmentVariable("DTMAPI_DOLOC_PERSISTENT_ROOT");
            try
            {
                Environment.SetEnvironmentVariable("DTMAPI_DOLOC_PERSISTENT_ROOT", persistentRoot);
                WriteOfficialModInfos(persistentRoot, "Local.Yuuka_DTMAPI_HotLoad", false);

                var menu = new ConfigMenuRegistry();
                IConfigMenuRuntime menuRuntime = menu;
                var runtime = new DtmApiRuntime(new FakeHost(gameDir), menu);
                runtime.Start();
                Assert(!runtime.CreateSnapshot().LoadedMods.Any(m => m.Manifest.UniqueID == "DTMAPI.Tests.HotLoad"), "Disabled official package should not load at startup.");
                Assert(!GetContent(runtime).FindAssets("json").Any(asset => asset.SourceModId.Equals("DTMAPI.Tests.HotLoad", StringComparison.OrdinalIgnoreCase)) && runtime.GetIndexedContentItem(contentItemId) == null, "A disabled code owner must publish neither content assets nor enabled indexed items.");
                Assert(runtime.GetAnyIndexedContentItem(contentItemId) == null, "All-content diagnostics must not parse or retain item-level rows for a disabled code owner.");

                WriteOfficialModInfos(persistentRoot, "Local.Yuuka_DTMAPI_HotLoad", true);
                runtime.NotifyWorkshopModListChanged();
                RuntimeSnapshot loadedSnapshot = runtime.CreateSnapshot();
                Assert(loadedSnapshot.LoadedMods.Count(m => m.Manifest.UniqueID == "DTMAPI.Tests.HotLoad") == 1, "Official reload should hot-load a newly enabled code mod once.");
                Assert(ReadHotLoadEntryCount(gameDir) == 1, "Hot-loaded code mod Entry should run exactly once.");
                Assert(GetContent(runtime).FindAssets("json").Any(asset => asset.SourceModId.Equals("DTMAPI.Tests.HotLoad", StringComparison.OrdinalIgnoreCase)) && runtime.GetIndexedContentItem(contentItemId)?.Enabled == true, "Content assets and indexed items must publish only after atomic owner activation succeeds.");
                IConfigMenuPage loadedPage = menuRuntime.GetPage("DTMAPI.Tests.HotLoad") ?? throw new InvalidOperationException("Hot-loaded mod should register a config page.");
                Assert(!loadedPage.IsLocked, "Hot-loaded enabled page should be editable.");

                runtime.NotifyWorkshopModListChanged();
                Assert(runtime.CreateSnapshot().LoadedMods.Count(m => m.Manifest.UniqueID == "DTMAPI.Tests.HotLoad") == 1, "Repeated official reload must not duplicate loaded mods.");
                Assert(ReadHotLoadEntryCount(gameDir) == 1, "Repeated official reload must not re-run Entry for an already loaded mod.");
                runtime.Diagnostics.RecordError("DTMAPI.Tests.HotLoad", "Mod monitor reported an error. Prior active-owner diagnostic.", "retained-before-disable");
                Assert(runtime.CreateDiagnosticsSnapshot().Mods.Any(status => status.UniqueID == "DTMAPI.Tests.HotLoad" && status.StatusCode == "runtime-diagnostic"), "A loaded owner with a prior runtime error should expose that diagnostic before deactivation.");

                WriteOfficialModInfos(persistentRoot, "Local.Yuuka_DTMAPI_HotLoad", false);
                runtime.NotifyWorkshopModListChanged();
                RuntimeSnapshot disabledAfterLoad = runtime.CreateSnapshot();
                Assert(!disabledAfterLoad.LoadedMods.Any(m => m.Manifest.UniqueID == "DTMAPI.Tests.HotLoad"), "Official disable should immediately remove the owner from loaded state.");
                Assert(menuRuntime.GetPage("DTMAPI.Tests.HotLoad") == null, "Official disable should remove the owner config page and callbacks.");
                Assert(runtime.ModRegistry.GetApi<IUnitProbeApi>("DTMAPI.Tests.HotLoad") == null, "Official disable should remove owner API roots.");
                Assert(!runtime.Input.GetRegisteredButtons().Contains("F12", StringComparer.OrdinalIgnoreCase), "Official disable should dispose owner input registrations.");
                Assert(runtime.Config.CountOwner("DTMAPI.Tests.HotLoad") == 0, "Official disable should remove owner config migrations.");
                Assert(runtime.Events.GetHandlerCleanupSnapshot().Slots.All(slot => !slot.ByOwner.ContainsKey("DTMAPI.Tests.HotLoad")), "Official disable should remove owner event roots.");
                Assert(!GetContent(runtime).FindAssets("json").Any(asset => asset.SourceModId.Equals("DTMAPI.Tests.HotLoad", StringComparison.OrdinalIgnoreCase)) && runtime.GetIndexedContentItem(contentItemId) == null, "Official disable should remove both owner content publication roots.");

                WriteOfficialModInfos(persistentRoot, "Local.Yuuka_DTMAPI_HotLoad", true);
                runtime.NotifyWorkshopModListChanged();
                Assert(!runtime.CreateSnapshot().LoadedMods.Any(m => m.Manifest.UniqueID == "DTMAPI.Tests.HotLoad"), "Same-process re-enable should remain inactive until restart.");
                Assert(ReadHotLoadEntryCount(gameDir) == 1, "Same-process re-enable must not execute Entry again.");
                Assert(runtime.OwnerRequiresRestart("DTMAPI.Tests.HotLoad"), "Deactivated loaded assembly should report restart-required.");
                Assert(!GetContent(runtime).FindAssets("json").Any(asset => asset.SourceModId.Equals("DTMAPI.Tests.HotLoad", StringComparison.OrdinalIgnoreCase)) && runtime.GetIndexedContentItem(contentItemId) == null, "Same-process restart-required re-enable must not republish owner content.");
                Assert(runtime.GetAnyIndexedContentItem(contentItemId) == null, "Restart-required re-enable must retain only package-level diagnostics and must not parse inactive owner item rows.");
                IDtmModStatusInfo restartStatus = runtime.CreateDiagnosticsSnapshot().Mods.Single(status => status.UniqueID == "DTMAPI.Tests.HotLoad");
                Assert(restartStatus.StatusCode == "restart-required", "Authoritative restart-required lifecycle state must take precedence over retained prior owner errors.");
                Assert(restartStatus.Reason.Contains("Prior active-owner diagnostic.", StringComparison.Ordinal), "Restart-required diagnostics should preserve prior error details without hiding the lifecycle state.");

                var restartedRuntime = new DtmApiRuntime(new FakeHost(gameDir), new ConfigMenuRegistry());
                restartedRuntime.Start();
                Assert(restartedRuntime.CreateSnapshot().LoadedMods.Count(m => m.Manifest.UniqueID == "DTMAPI.Tests.HotLoad") == 1, "A new process-lifetime runtime should load the re-enabled mod.");
                Assert(ReadHotLoadEntryCount(gameDir) == 2, "Restarted runtime should execute Entry exactly once for the new process.");
                Assert(GetContent(restartedRuntime).FindAssets("json").Any(asset => asset.SourceModId.Equals("DTMAPI.Tests.HotLoad", StringComparison.OrdinalIgnoreCase)) && restartedRuntime.GetIndexedContentItem(contentItemId)?.Enabled == true, "A clean process may republish content after the owner activates again.");
            }
            finally
            {
                Environment.SetEnvironmentVariable("DTMAPI_DOLOC_PERSISTENT_ROOT", previousRoot);
            }
        }

        private static void AutoFishingProductOwnsExecutableSessionLifetime()
        {
            string source = File.ReadAllText(Path.Combine(
                FindRepositoryRoot(),
                "products",
                "first-party",
                "AutoFishing",
                "src",
                "ModEntry.cs"));
            Assert(source.Contains("SetUpdateSubscription(true)", StringComparison.Ordinal), "AutoFishing must subscribe its updater only after its product-owned session is active.");
            Assert(source.Contains("SetUpdateSubscription(false)", StringComparison.Ordinal), "F6 off and lifecycle boundaries must detach the product updater.");
            Assert(source.Contains("ReleasePrimitiveSession(reason)", StringComparison.Ordinal), "F6 off must release product-owned input, animation, and native session state.");
            Assert(source.Contains("session.SetInputFaultHandler(OnFishingInputFault)", StringComparison.Ordinal) &&
                source.Contains("private bool OnFishingInputFault(string reason)", StringComparison.Ordinal) &&
                source.Contains("SetAutomation(false, reason ?? \"minigame-input-fault\")", StringComparison.Ordinal) &&
                source.Contains("TryClosePendingInputFault()", StringComparison.Ordinal),
                "A ProductNative minigame-input fault must immediately return to ModEntry, use the complete automation-disable path, and retain a lifecycle-level retry.");
            Assert(!source.Contains("GetApi<IFirstPartyFishing", StringComparison.Ordinal), "AutoFishing must not reacquire the deleted GameBridge primitive provider.");
        }

        private static void AutoFishingMiniGameInputStateIsCurrentGameBoundedAndFaultClosed()
        {
            var transaction = new FishingMiniGameInputTransaction();
            var firstGame = new object();
            var secondGame = new object();
            bool observedAlreadyTapped = false;
            int successes = 0;
            int faults = 0;
            string faultStage = string.Empty;
            string faultDetail = string.Empty;
            Exception? observedFault = null;

            FishingMiniGameFrameReader ready = (
                object handle,
                long sequence,
                out FishingMiniGameFrame frame,
                out string failureReason) =>
            {
                frame = new FishingMiniGameFrame(sequence, 1.5d, FishingMiniGameNoteKind.Bonus, int.MaxValue, 1d, 2d, false);
                failureReason = string.Empty;
                return FishingMiniGameFrameReadStatus.Ready;
            };
            Action<string, string, Exception?> recordFault = (stage, detail, error) =>
            {
                faults++;
                faultStage = stage;
                faultDetail = detail;
                observedFault = error;
            };

            bool first = transaction.TryExecute(
                firstGame,
                1,
                ready,
                frame =>
                {
                    observedAlreadyTapped = frame.BonusAlreadyTapped;
                    return FishingSyntheticInputAction.TapBonus;
                },
                () => successes++,
                recordFault,
                out FishingSyntheticInputAction firstAction,
                out _);
            Assert(first && firstAction == FishingSyntheticInputAction.TapBonus &&
                !observedAlreadyTapped && transaction.TrackedBonusNoteCount == 1,
                "The first bonus note must be tapped and recorded without a composite identity hash.");

            bool repeated = transaction.TryExecute(
                firstGame,
                2,
                ready,
                frame =>
                {
                    observedAlreadyTapped = frame.BonusAlreadyTapped;
                    return frame.BonusAlreadyTapped
                        ? FishingSyntheticInputAction.Release
                        : FishingSyntheticInputAction.TapBonus;
                },
                () => successes++,
                recordFault,
                out FishingSyntheticInputAction repeatedAction,
                out _);
            Assert(repeated && repeatedAction == FishingSyntheticInputAction.Release &&
                observedAlreadyTapped && transaction.TrackedBonusNoteCount == 1,
                "A repeated note in the same native minigame must be exposed as already tapped exactly once.");

            bool secondHandle = transaction.TryExecute(
                secondGame,
                3,
                ready,
                frame =>
                {
                    observedAlreadyTapped = frame.BonusAlreadyTapped;
                    return FishingSyntheticInputAction.TapBonus;
                },
                () => successes++,
                recordFault,
                out _,
                out _);
            Assert(secondHandle && !observedAlreadyTapped && transaction.TrackedBonusNoteCount == 1,
                "A different native minigame handle must discard the previous handle even when the note index is identical.");

            FishingMiniGameFrameReader notReady = (
                object handle,
                long sequence,
                out FishingMiniGameFrame frame,
                out string failureReason) =>
            {
                frame = default;
                failureReason = "note-spawner-not-ready";
                return FishingMiniGameFrameReadStatus.NotReady;
            };
            Assert(!transaction.TryExecute(secondGame, 4, notReady, _ => FishingSyntheticInputAction.Hold, () => successes++, recordFault, out _, out _) &&
                faults == 0,
                "A bounded transient frame-not-ready result must wait without poisoning the product session.");

            FishingMiniGameFrameReader frameFault = (
                object handle,
                long sequence,
                out FishingMiniGameFrame frame,
                out string failureReason) =>
            {
                frame = default;
                failureReason = "invoke:frame:TargetInvocationException";
                return FishingMiniGameFrameReadStatus.Faulted;
            };
            Assert(!transaction.TryExecute(secondGame, 5, frameFault, _ => FishingSyntheticInputAction.Hold, () => successes++, recordFault, out _, out _) &&
                faults == 1 && faultStage == "frame" &&
                faultDetail == "invoke:frame:TargetInvocationException" &&
                observedFault == null,
                "A permanent native frame-access failure must enter the same explicit fault transaction.");

            Assert(!transaction.TryExecute(
                    secondGame,
                    6,
                    ready,
                    _ => throw new OverflowException("provider"),
                    () => successes++,
                    recordFault,
                    out _,
                    out _) &&
                faults == 2 && faultStage == "provider" && observedFault is OverflowException,
                "A provider exception must be attributed to the provider stage and published to the immediate fault closer.");

            transaction.Clear();
            Assert(transaction.TrackedBonusNoteCount == 0 && successes == 3,
                "MiniGameStop, Pull and session release can use one transaction clear operation to remove the current handle and note set.");

            string serviceSource = File.ReadAllText(Path.Combine(
                FindRepositoryRoot(),
                "products",
                "first-party",
                "AutoFishing",
                "src",
                "Native",
                "FishingPrimitivesService.cs"));
            Assert(!serviceSource.Contains("BonusTapKey", StringComparison.Ordinal) &&
                !serviceSource.Contains("RuntimeHelpers.GetHashCode", StringComparison.Ordinal) &&
                serviceSource.Contains("RecordMiniGameInputFault", StringComparison.Ordinal) &&
                serviceSource.Contains("session.NotifyInputFault(reason)", StringComparison.Ordinal) &&
                serviceSource.Contains("pendingInputFaultReason", StringComparison.Ordinal),
                "The production transaction must remove the composite identity hash, close immediately, and retain an unclosed fault across session release.");
            string cacheSource = File.ReadAllText(Path.Combine(
                FindRepositoryRoot(),
                "products",
                "first-party",
                "AutoFishing",
                "src",
                "Native",
                "FishingMiniGameNativeCache.cs"));
            Assert(cacheSource.Contains("FishingMiniGameFrameReadStatus.NotReady", StringComparison.Ordinal) &&
                cacheSource.Contains("FishingMiniGameFrameReadStatus.Faulted", StringComparison.Ordinal) &&
                cacheSource.Contains("LastAccessorFailure", StringComparison.Ordinal),
                "The native frame reader must distinguish a transient absent spawner from accessor/build/invocation faults.");
        }

        private static void AutoHarvestUpdaterFollowsOrdinarySaveLifecycle()
        {
            string source = File.ReadAllText(Path.Combine(FindRepositoryRoot(), "author-sdk", "samples", "api-demand", "AutoHarvest", "ModEntry.cs"));
            Assert(!source.Contains("IInstantSaveDebugApi", StringComparison.Ordinal) &&
                !source.Contains("InstantSaveDebugState", StringComparison.Ordinal),
                "The ordinary AutoHarvest sample must not use Diagnostic save state as gameplay lifecycle authority.");
            RunAutoHarvestColdLoadLifetime();
            RunAutoHarvestHotEnableRequiresColdStart();
        }

        private static void RunAutoHarvestColdLoadLifetime()
        {
            const string ownerId = "Yuuka.DTMAPI.AutoHarvest";
            const string officialId = "Local.DTMAPI_AutoHarvest";
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string persistentRoot = Environment.GetEnvironmentVariable("DTMAPI_DOLOC_PERSISTENT_ROOT")
                    ?? throw new InvalidOperationException("AutoHarvest cold-load fixture requires a temporary persistent root.");
                string gameDir = NewTempGameDir();
                WriteAutoHarvestOfficialPackage(persistentRoot);
                WriteOfficialModInfos(persistentRoot, officialId, enabled: true);

                var menu = new ConfigMenuRegistry();
                var runtime = new DtmApiRuntime(new FakeHost(gameDir), menu);
                RegisterAutoHarvestTestApis(runtime);
                WriteAutoHarvestConfig(runtime, enabled: true);
                runtime.Start();

                Assert(runtime.LoadedMods.Count(mod => mod.Manifest.UniqueID == ownerId) == 1,
                    "The AutoHarvest cold-load fixture should load the real product assembly once.");
                Assert(CountEventOwnerHandlers(runtime, ownerId, "GameLoop.OneSecondUpdateTicked") == 0,
                    "Enabled AutoHarvest must remain asleep until an ordinary SaveLoaded lifecycle event is observed.");

                runtime.NotifyLoadGameRequested(2);
                runtime.NotifySaveLoaded(isNewGame: false);
                Assert(CountEventOwnerHandlers(runtime, ownerId, "GameLoop.OneSecondUpdateTicked") == 1,
                    "SaveLoaded plus Enabled must move AutoHarvest's automatic updater 0->1.");
                runtime.NotifySaveLoaded(isNewGame: false);
                Assert(CountEventOwnerHandlers(runtime, ownerId, "GameLoop.OneSecondUpdateTicked") == 1,
                    "Repeated SaveLoaded boundaries must not duplicate AutoHarvest's automatic updater.");

                IConfigMenuRuntime menuRuntime = menu;
                IConfigMenuPage page = menuRuntime.GetPage(ownerId)
                    ?? throw new InvalidOperationException("AutoHarvest config page should be registered.");
                IConfigMenuItem enabledItem = page.Items.First(item => item.Kind == "Bool");
                menuRuntime.BeginEditing(ownerId);
                Assert(enabledItem.TrySetPendingValue("false", out _), "AutoHarvest Enabled should accept false.");
                menuRuntime.Save(ownerId);
                Assert(CountEventOwnerHandlers(runtime, ownerId, "GameLoop.OneSecondUpdateTicked") == 0,
                    "Disabling AutoHarvest in a loaded save must release its automatic updater 1->0.");
                menuRuntime.BeginEditing(ownerId);
                Assert(enabledItem.TrySetPendingValue("true", out _), "AutoHarvest Enabled should accept true after disable.");
                menuRuntime.Save(ownerId);
                Assert(CountEventOwnerHandlers(runtime, ownerId, "GameLoop.OneSecondUpdateTicked") == 1,
                    "Re-enabling AutoHarvest in a loaded save must restore exactly one updater.");

                runtime.NotifyReturnedToTitle();
                Assert(CountEventOwnerHandlers(runtime, ownerId, "GameLoop.OneSecondUpdateTicked") == 0,
                    "ReturnedToTitle must release AutoHarvest's automatic updater 1->0.");
                runtime.NotifyReturnedToTitle();
                Assert(CountEventOwnerHandlers(runtime, ownerId, "GameLoop.OneSecondUpdateTicked") == 0,
                    "Repeated title boundaries must leave AutoHarvest asleep without duplicate unsubscribe state.");
                runtime.NotifyLoadGameRequested(2);
                runtime.NotifySaveLoaded(isNewGame: false);
                Assert(CountEventOwnerHandlers(runtime, ownerId, "GameLoop.OneSecondUpdateTicked") == 1,
                    "A later SaveLoaded must restore AutoHarvest's updater after title cleanup.");

                WriteOfficialModInfos(persistentRoot, officialId, enabled: false);
                runtime.NotifyWorkshopModListChanged();
                Assert(CountEventOwnerHandlers(runtime, ownerId) == 0 &&
                    runtime.Input.CountOwnerResources(ownerId) == 0 &&
                    menuRuntime.GetPage(ownerId) == null &&
                    CountCoreOwnerRootsForTest(runtime, ownerId) == 0,
                    "Official owner cleanup must reduce all AutoHarvest Event, Input, ConfigPage, facade, and loaded roots to zero.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void RunAutoHarvestHotEnableRequiresColdStart()
        {
            const string ownerId = "Yuuka.DTMAPI.AutoHarvest";
            const string officialId = "Local.DTMAPI_AutoHarvest";
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string persistentRoot = Environment.GetEnvironmentVariable("DTMAPI_DOLOC_PERSISTENT_ROOT")
                    ?? throw new InvalidOperationException("AutoHarvest hot-load fixture requires a temporary persistent root.");
                string gameDir = NewTempGameDir();
                WriteAutoHarvestOfficialPackage(persistentRoot);
                WriteOfficialModInfos(persistentRoot, officialId, enabled: false);

                var menu = new ConfigMenuRegistry();
                var runtime = new DtmApiRuntime(new FakeHost(gameDir), menu);
                RegisterAutoHarvestTestApis(runtime);
                WriteAutoHarvestConfig(runtime, enabled: true);
                runtime.Start();
                runtime.NotifyLoadGameRequested(2);
                runtime.NotifySaveLoaded(isNewGame: false);
                Assert(!runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == ownerId),
                    "Disabled AutoHarvest should not be resident before the hot-load transition.");

                WriteOfficialModInfos(persistentRoot, officialId, enabled: true);
                runtime.NotifyWorkshopModListChanged();
                Assert(!runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == ownerId) &&
                    runtime.OwnerRequiresRestart(ownerId) &&
                    CountEventOwnerHandlers(runtime, ownerId) == 0 &&
                    runtime.Input.CountOwnerResources(ownerId) == 0,
                    "A newly enabled omitted-kind AutoHarvest must remain cold-start-only and expose restart-required without loading its assembly or owner roots.");
                runtime.NotifyWorkshopModListChanged();
                Assert(!runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == ownerId) &&
                    runtime.OwnerRequiresRestart(ownerId) &&
                    CountEventOwnerHandlers(runtime, ownerId) == 0,
                    "Repeated Workshop refresh must not bypass the legacy cold-start boundary or invent a SaveLoaded lifecycle.");

                WriteOfficialModInfos(persistentRoot, officialId, enabled: false);
                runtime.NotifyWorkshopModListChanged();
                Assert(CountEventOwnerHandlers(runtime, ownerId) == 0 &&
                    runtime.Input.CountOwnerResources(ownerId) == 0 &&
                    CountCoreOwnerRootsForTest(runtime, ownerId) == 0,
                    "A never-loaded legacy owner must leave zero platform roots when disabled again.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void ReservedRuntimeDependenciesSurviveTitleAndWorkshopRefresh()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                const string ownerId = "DTMAPI.Tests.ReservedDependencies.Active";
                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                RegisterReservedRuntimeProviderProbe(runtime, "DTMAPI.GameBridge.DolocTown", DtmApiRuntime.ApiVersion);
                RegisterReservedRuntimeProviderProbe(runtime, "DTMAPI.DebugConsoleHost", DtmApiRuntime.ApiVersion);
                WriteAtomicProbePackage(
                    dir,
                    ownerId,
                    ", \"Dependencies\": [" +
                    "{ \"UniqueID\": \"DTMAPI.ModConfigMenu\", \"MinimumVersion\": \"0.5.3-alpha\", \"Required\": true }," +
                    "{ \"UniqueID\": \"DTMAPI.GameBridge.DolocTown\", \"MinimumVersion\": \"0.5.3-alpha\", \"Required\": true }," +
                    "{ \"UniqueID\": \"DTMAPI.DebugConsoleHost\", \"MinimumVersion\": \"0.5.3-alpha\", \"Required\": true }]");

                AtomicOwnerProbeMod.EntryCount = 0;
                runtime.Start();
                Assert(runtime.LoadedMods.Count(mod => mod.Manifest.UniqueID == ownerId) == 1 && AtomicOwnerProbeMod.EntryCount == 1, "An ordinary Mod should load once when all required process-lifetime reserved providers are present in the registry.");
                Assert(runtime.ModRegistry.IsLoaded("DTMAPI.ModConfigMenu") && runtime.ModRegistry.IsLoaded("DTMAPI.GameBridge.DolocTown") && runtime.ModRegistry.IsLoaded("DTMAPI.DebugConsoleHost"), "The fixture should expose all three process-lifetime reserved provider manifests through the registry.");
                int activeRoots = CountCoreOwnerRootsForTest(runtime, ownerId);
                Assert(activeRoots > 0, "The reserved-provider consumer should publish ordinary owner roots after Entry.");

                runtime.NotifyReturnedToTitle();
                Assert(runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == ownerId) && CountCoreOwnerRootsForTest(runtime, ownerId) == activeRoots, "ReturnedToTitle must preserve an ordinary Mod and its process-lifetime services when reserved dependencies remain registered.");
                runtime.NotifyWorkshopModListChanged();
                runtime.NotifyWorkshopModListChanged();

                Assert(runtime.LoadedMods.Count(mod => mod.Manifest.UniqueID == ownerId) == 1, "Workshop refresh must not deactivate a consumer merely because process-lifetime reserved providers are absent from mod discovery.");
                Assert(AtomicOwnerProbeMod.EntryCount == 1 && !runtime.OwnerRequiresRestart(ownerId), "Reserved-provider reconciliation must neither repeat Entry nor mark the still-valid consumer restart-required.");
                Assert(CountCoreOwnerRootsForTest(runtime, ownerId) == activeRoots, "Repeated Workshop refresh should preserve the consumer's authoritative owner-root count.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void RequiredReservedRuntimeProviderLossDeactivatesConsumer()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                const string ownerId = "DTMAPI.Tests.ReservedDependencies.Missing";
                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                RegisterReservedRuntimeProviderProbe(runtime, "DTMAPI.GameBridge.DolocTown", DtmApiRuntime.ApiVersion);
                RegisterReservedRuntimeProviderProbe(runtime, "DTMAPI.DebugConsoleHost", DtmApiRuntime.ApiVersion);
                WriteAtomicProbePackage(
                    dir,
                    ownerId,
                    ", \"Dependencies\": [{ \"UniqueID\": \"DTMAPI.DebugConsoleHost\", \"MinimumVersion\": \"0.5.3-alpha\", \"Required\": true }]");

                AtomicOwnerProbeMod.EntryCount = 0;
                runtime.Start();
                Assert(runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == ownerId) && AtomicOwnerProbeMod.EntryCount == 1, "The required-reserved-provider loss fixture should begin active.");
                Assert(runtime.ModRegistry.RemoveOwner("DTMAPI.DebugConsoleHost") > 0 && !runtime.ModRegistry.IsLoaded("DTMAPI.DebugConsoleHost"), "The fixture should remove the required reserved provider from the authoritative registry.");

                runtime.NotifyWorkshopModListChanged();

                Assert(!runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == ownerId) && runtime.OwnerRequiresRestart(ownerId), "A required reserved provider missing from the registry must deactivate its ordinary consumer and require restart.");
                Assert(CountCoreOwnerRootsForTest(runtime, ownerId) == 0, "Required reserved-provider loss should clean every Core owner root from the consumer.");
                Assert(runtime.ModRegistry.IsLoaded("DTMAPI.ModConfigMenu") && runtime.ModRegistry.IsLoaded("DTMAPI.GameBridge.DolocTown"), "Consumer deactivation must preserve unrelated process-lifetime providers.");
                Assert(AtomicOwnerProbeMod.EntryCount == 1, "Provider loss reconciliation must not repeat consumer Entry.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void RequiredReservedRuntimeProviderVersionMismatchDeactivatesConsumer()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                const string ownerId = "DTMAPI.Tests.ReservedDependencies.Version";
                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                ManifestModel gameBridge = RegisterReservedRuntimeProviderProbe(runtime, "DTMAPI.GameBridge.DolocTown", DtmApiRuntime.ApiVersion);
                RegisterReservedRuntimeProviderProbe(runtime, "DTMAPI.DebugConsoleHost", DtmApiRuntime.ApiVersion);
                WriteAtomicProbePackage(
                    dir,
                    ownerId,
                    ", \"Dependencies\": [{ \"UniqueID\": \"DTMAPI.GameBridge.DolocTown\", \"MinimumVersion\": \"0.5.3-alpha\", \"Required\": true }]");

                AtomicOwnerProbeMod.EntryCount = 0;
                runtime.Start();
                Assert(runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == ownerId) && AtomicOwnerProbeMod.EntryCount == 1, "The reserved-provider version fixture should begin active.");
                gameBridge.Version = "0.5.2-alpha";

                runtime.NotifyWorkshopModListChanged();

                Assert(!runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == ownerId) && runtime.OwnerRequiresRestart(ownerId), "A reserved provider registry version below the required minimum must deactivate its ordinary consumer.");
                Assert(CountCoreOwnerRootsForTest(runtime, ownerId) == 0, "Reserved-provider version mismatch should clean every consumer owner root.");
                Assert(runtime.ModRegistry.IsLoaded(gameBridge.UniqueID) && runtime.ModRegistry.Get(gameBridge.UniqueID)?.Version == "0.5.2-alpha", "Reconciliation should preserve the process-lifetime provider itself while deactivating the incompatible consumer.");
                Assert(AtomicOwnerProbeMod.EntryCount == 1, "Reserved-provider version mismatch must not repeat consumer Entry.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void OptionalReservedRuntimeProviderLossWarnsWithoutDeactivation()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                const string ownerId = "DTMAPI.Tests.ReservedDependencies.Optional";
                const string optionalProviderId = "DTMAPI.DebugConsoleHost";
                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                WriteAtomicProbePackage(
                    dir,
                    ownerId,
                    ", \"Dependencies\": [{ \"UniqueID\": \"" + optionalProviderId + "\", \"MinimumVersion\": \"0.5.3-alpha\", \"Required\": false }]");

                AtomicOwnerProbeMod.EntryCount = 0;
                runtime.Start();
                int activeRoots = CountCoreOwnerRootsForTest(runtime, ownerId);
                Assert(runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == ownerId) && !runtime.ModRegistry.IsLoaded(optionalProviderId), "An ordinary Mod should load when its optional reserved provider is absent.");

                runtime.NotifyReturnedToTitle();
                runtime.NotifyWorkshopModListChanged();
                runtime.NotifyWorkshopModListChanged();

                Assert(runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == ownerId) && !runtime.OwnerRequiresRestart(ownerId), "Optional reserved-provider loss must remain warning-only across title and repeated Workshop refresh.");
                Assert(AtomicOwnerProbeMod.EntryCount == 1 && CountCoreOwnerRootsForTest(runtime, ownerId) == activeRoots, "Optional reserved-provider loss must preserve Entry-once and all ordinary owner roots.");
                RuntimeSnapshot snapshot = runtime.CreateSnapshot();
                Assert(snapshot.Warnings.Count(warning => warning.Details.Contains(ownerId, StringComparison.OrdinalIgnoreCase) && warning.Details.Contains(optionalProviderId, StringComparison.OrdinalIgnoreCase)) == 1, "Optional reserved-provider loss should publish one bounded warning for the owner/dependency pair.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void SourceDisableCascadesRequiredDependentInReverseOrder()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                const string provider = "DTMAPI.Tests.Disable.Provider";
                const string required = "DTMAPI.Tests.Disable.Required";
                const string optional = "DTMAPI.Tests.Disable.Optional";
                string providerDir = WriteAtomicProbePackage(dir, provider, string.Empty);
                WriteAtomicProbePackage(dir, required, ", \"Dependencies\": [{ \"UniqueID\": \"" + provider + "\", \"MinimumVersion\": \"1.0.0\", \"Required\": true }]");
                WriteAtomicProbePackage(dir, optional, ", \"Dependencies\": [{ \"UniqueID\": \"" + provider + "\", \"MinimumVersion\": \"1.0.0\", \"Required\": false }]");
                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                var cleanupOrder = new OwnerCleanupOrderProbe("DTMAPI.Tests.Disable.CleanupOrder");
                runtime.RegisterModOwnerCleanupParticipant(cleanupOrder);
                AtomicOwnerProbeMod.EntryCount = 0;
                runtime.Start();
                Assert(runtime.LoadedMods.Count(mod => mod.Manifest.UniqueID == provider || mod.Manifest.UniqueID == required || mod.Manifest.UniqueID == optional) == 3 && AtomicOwnerProbeMod.EntryCount == 3, "The source-disable fixture should begin with provider and both consumers active.");

                File.WriteAllText(Path.Combine(providerDir, "dtmapi.disabled"), "disabled by owner-lifetime dependency test");
                runtime.NotifyWorkshopModListChanged();

                Assert(!runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == provider || mod.Manifest.UniqueID == required), "Disabling an ordinary provider should cascade deactivation to its required dependent.");
                Assert(runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == optional), "Disabling an ordinary provider should keep its optional consumer active.");
                Assert(cleanupOrder.OwnerIds.SequenceEqual(new[] { required, provider }, StringComparer.OrdinalIgnoreCase), "Ordinary provider disable should clean the required dependent before the provider in reverse dependency order.");
                Assert(runtime.OwnerRequiresRestart(provider) && runtime.OwnerRequiresRestart(required) && !runtime.OwnerRequiresRestart(optional), "Disabled provider and required dependent should require restart while the optional consumer remains active.");
                Assert(CountCoreOwnerRootsForTest(runtime, provider) == 0 && CountCoreOwnerRootsForTest(runtime, required) == 0 && CountCoreOwnerRootsForTest(runtime, optional) > 0, "Source-disable cascade should leave zero roots for inactive owners and preserve the optional consumer roots.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void SourceRemovalCascadesRequiredDependentsButKeepsOptionalDependents()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                const string provider = "DTMAPI.Tests.Cascade.Provider";
                const string required = "DTMAPI.Tests.Cascade.Required";
                const string optional = "DTMAPI.Tests.Cascade.Optional";
                string providerDir = WriteAtomicProbePackage(dir, provider, string.Empty);
                WriteAtomicProbePackage(dir, required, ", \"Dependencies\": [{ \"UniqueID\": \"" + provider + "\", \"MinimumVersion\": \"1.0.0\", \"Required\": true }]");
                WriteAtomicProbePackage(dir, optional, ", \"Dependencies\": [{ \"UniqueID\": \"" + provider + "\", \"MinimumVersion\": \"1.0.0\", \"Required\": false }]");
                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                var cleanupOrder = new OwnerCleanupOrderProbe("DTMAPI.Tests.Cascade.CleanupOrder");
                runtime.RegisterModOwnerCleanupParticipant(cleanupOrder);
                runtime.Start();
                Assert(runtime.LoadedMods.Count(mod => mod.Manifest.UniqueID == provider || mod.Manifest.UniqueID == required || mod.Manifest.UniqueID == optional) == 3, "Cascade fixture should initially load provider and both dependents.");

                Directory.Delete(providerDir, recursive: true);
                runtime.NotifyWorkshopModListChanged();

                Assert(!runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == provider || mod.Manifest.UniqueID == required), "Source removal should deactivate the provider and required dependent.");
                Assert(runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == optional), "Optional dependency disappearance should not deactivate its consumer.");
                Assert(cleanupOrder.OwnerIds.SequenceEqual(new[] { required, provider }, StringComparer.OrdinalIgnoreCase), "Source removal should clean the required dependent before its ordinary provider in reverse dependency order.");
                Assert(runtime.OwnerRequiresRestart(provider) && runtime.OwnerRequiresRestart(required), "Removed provider and cascaded required dependent should remain restart-required.");
                Assert(runtime.ModRegistry.CountOwner(provider) == 0 && runtime.ModRegistry.CountOwner(required) == 0, "Cascaded deactivation should leave no registry roots.");
                IContentQueryHelper content = GetContent(runtime);
                Assert(!content.FindAssets("json").Any(asset => asset.SourceModId.Equals(provider, StringComparison.OrdinalIgnoreCase) || asset.SourceModId.Equals(required, StringComparison.OrdinalIgnoreCase)), "Source removal and required-dependency cascade must remove both inactive owners' content publication.");
                Assert(content.FindAssets("json").Any(asset => asset.SourceModId.Equals(optional, StringComparison.OrdinalIgnoreCase)), "An optional dependent that remains active must retain its content publication.");
                Assert(runtime.CreateSnapshot().Warnings.Any(warning => warning.Owner == optional && warning.Message.Contains("可选", StringComparison.OrdinalIgnoreCase)) ||
                    runtime.CreateSnapshot().Warnings.Any(warning => warning.Details.Contains(optional, StringComparison.OrdinalIgnoreCase)), "Optional dependency change should publish a warning.");
                runtime.NotifyWorkshopModListChanged();
                Assert(runtime.ModRegistry.CountOwner(provider) == 0 && runtime.ModRegistry.CountOwner(required) == 0 && runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == optional), "Repeated reconciliation should be idempotent.");
                Assert(!content.FindAssets("json").Any(asset => asset.SourceModId.Equals(provider, StringComparison.OrdinalIgnoreCase) || asset.SourceModId.Equals(required, StringComparison.OrdinalIgnoreCase)), "Repeated reconciliation must not republish restart-required content.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void SourceRefreshDependencyDowngradeCascadesRequiredDependent()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                const string provider = "DTMAPI.Tests.VersionRefresh.Provider";
                const string required = "DTMAPI.Tests.VersionRefresh.Required";
                const string transitive = "DTMAPI.Tests.VersionRefresh.Transitive";
                const string optional = "DTMAPI.Tests.VersionRefresh.Optional";
                string providerDir = WriteAtomicProbePackage(dir, provider, string.Empty);
                WriteAtomicProbePackage(dir, required, ", \"Dependencies\": [{ \"UniqueID\": \"" + provider + "\", \"MinimumVersion\": \"1.0.0\", \"Required\": true }]");
                WriteAtomicProbePackage(dir, transitive, ", \"Dependencies\": [{ \"UniqueID\": \"" + required + "\", \"MinimumVersion\": \"1.0.0\", \"Required\": true }]");
                WriteAtomicProbePackage(dir, optional, ", \"Dependencies\": [{ \"UniqueID\": \"" + provider + "\", \"MinimumVersion\": \"1.0.0\", \"Required\": false }]");
                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                var cleanupOrder = new OwnerCleanupOrderProbe("DTMAPI.Tests.VersionRefresh.CleanupOrder");
                runtime.RegisterModOwnerCleanupParticipant(cleanupOrder);
                AtomicOwnerProbeMod.EntryCount = 0;
                runtime.Start();
                Assert(runtime.LoadedMods.Count(mod => mod.Manifest.UniqueID == provider || mod.Manifest.UniqueID == required || mod.Manifest.UniqueID == transitive || mod.Manifest.UniqueID == optional) == 4, "Version refresh fixture should initially load provider, required chain, and optional dependent.");
                Assert(AtomicOwnerProbeMod.EntryCount == 4, "Version refresh fixture should execute each owner Entry once.");

                string manifestPath = Path.Combine(providerDir, "manifest.json");
                string manifestJson = File.ReadAllText(manifestPath);
                string downgradedJson = manifestJson.Replace("\"Version\": \"1.0.0\"", "\"Version\": \"0.5.0\"");
                Assert(!string.Equals(manifestJson, downgradedJson, StringComparison.Ordinal), "Version refresh fixture should rewrite the discovered provider version.");
                File.WriteAllText(manifestPath, downgradedJson);
                runtime.NotifyWorkshopModListChanged();

                Assert(!runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == provider), "An in-place provider manifest version change must deactivate the resident owner instead of presenting disk metadata as the loaded assembly version.");
                Assert(!runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == required), "A refreshed provider version below the required minimum should cascade deactivation to the required dependent.");
                Assert(!runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == transitive), "A provider version downgrade should cascade through the required dependency chain.");
                Assert(runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == optional), "A refreshed provider version below an optional minimum should keep the optional consumer active.");
                Assert(cleanupOrder.OwnerIds.SequenceEqual(new[] { transitive, required, provider }, StringComparer.OrdinalIgnoreCase), "Version downgrade should clean transitive and direct consumers before the updated provider in reverse dependency order.");
                Assert(runtime.OwnerRequiresRestart(provider) && runtime.OwnerRequiresRestart(required) && runtime.OwnerRequiresRestart(transitive), "The resident provider assembly and cascaded required dependency chain should remain inactive until restart.");
                Assert(AtomicOwnerProbeMod.EntryCount == 4, "Dependency reconciliation must not re-run Entry in the same process.");
                Assert(runtime.ModRegistry.CountOwner(provider) == 0 && runtime.Config.CountOwner(provider) == 0 && runtime.Input.CountOwnerResources(provider) == 0 &&
                    runtime.ModRegistry.CountOwner(required) == 0 && runtime.Config.CountOwner(required) == 0 && runtime.Input.CountOwnerResources(required) == 0 &&
                    runtime.ModRegistry.CountOwner(transitive) == 0 && runtime.Config.CountOwner(transitive) == 0 && runtime.Input.CountOwnerResources(transitive) == 0,
                    "Version-handoff deactivation should remove registry, config, and input roots from the provider and required dependency chain.");
                Assert(runtime.Events.GetHandlerCleanupSnapshot().Slots.All(slot => !slot.ByOwner.ContainsKey(provider) && !slot.ByOwner.ContainsKey(required) && !slot.ByOwner.ContainsKey(transitive)), "Version-handoff deactivation should remove event roots from the provider and required dependency chain.");
                IContentQueryHelper content = GetContent(runtime);
                Assert(!content.FindAssets("json").Any(asset => asset.SourceModId.Equals(provider, StringComparison.OrdinalIgnoreCase) || asset.SourceModId.Equals(required, StringComparison.OrdinalIgnoreCase) || asset.SourceModId.Equals(transitive, StringComparison.OrdinalIgnoreCase)), "Version-handoff deactivation must remove provider and required-chain content publication.");
                Assert(content.FindAssets("json").Any(asset => asset.SourceModId.Equals(optional, StringComparison.OrdinalIgnoreCase)), "The optional consumer that remains active must retain its content publication.");
                Assert(runtime.CreateSnapshot().Warnings.Any(warning => warning.Owner == optional && warning.Message.Contains("可选", StringComparison.OrdinalIgnoreCase)) ||
                    runtime.CreateSnapshot().Warnings.Any(warning => warning.Details.Contains(optional, StringComparison.OrdinalIgnoreCase)), "Optional dependency version changes should retain warning-only semantics.");

                runtime.NotifyWorkshopModListChanged();
                Assert(!runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == provider || mod.Manifest.UniqueID == required || mod.Manifest.UniqueID == transitive) && runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == optional), "Repeated version reconciliation should remain idempotent while the updated assembly awaits restart.");
                Assert(AtomicOwnerProbeMod.EntryCount == 4 && cleanupOrder.OwnerIds.Count == 3, "Repeated version reconciliation must neither re-enter nor re-clean any owner.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void SourceRefreshInPlaceUpgradeCannotAuthorizeResidentProviderVersion()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                const string provider = "DTMAPI.Tests.InPlaceUpgrade.Provider";
                const string existingConsumer = "DTMAPI.Tests.InPlaceUpgrade.ExistingConsumer";
                const string newConsumer = "DTMAPI.Tests.InPlaceUpgrade.NewConsumer";
                string providerDir = WriteAtomicProbePackage(dir, provider, string.Empty);
                WriteAtomicProbePackage(dir, existingConsumer, ", \"Dependencies\": [{ \"UniqueID\": \"" + provider + "\", \"MinimumVersion\": \"1.0.0\", \"Required\": true }]");
                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                var cleanupOrder = new OwnerCleanupOrderProbe("DTMAPI.Tests.InPlaceUpgrade.CleanupOrder");
                runtime.RegisterModOwnerCleanupParticipant(cleanupOrder);
                AtomicOwnerProbeMod.EntryCount = 0;
                runtime.Start();

                Assert(runtime.LoadedMods.Count(mod => mod.Manifest.UniqueID == provider || mod.Manifest.UniqueID == existingConsumer) == 2 && AtomicOwnerProbeMod.EntryCount == 2, "The in-place upgrade fixture should begin with resident provider 1.0 and its existing consumer active.");
                Assert(runtime.ModRegistry.Get(provider)?.Version == "1.0.0", "The loaded registry manifest must expose the resident provider version before refresh.");

                string manifestPath = Path.Combine(providerDir, "manifest.json");
                string versionOneManifest = File.ReadAllText(manifestPath);
                string versionTwoManifest = versionOneManifest.Replace("\"Version\": \"1.0.0\"", "\"Version\": \"2.0.0\"");
                Assert(!string.Equals(versionOneManifest, versionTwoManifest, StringComparison.Ordinal), "The fixture must update the provider manifest in its original directory.");
                File.WriteAllText(manifestPath, versionTwoManifest);
                WriteAtomicProbePackage(dir, newConsumer, ", \"Dependencies\": [{ \"UniqueID\": \"" + provider + "\", \"MinimumVersion\": \"2.0.0\", \"Required\": true }]");

                runtime.NotifyWorkshopModListChanged();

                Assert(!runtime.LoadedMods.Any(mod => mod.Manifest.UniqueID == provider || mod.Manifest.UniqueID == existingConsumer || mod.Manifest.UniqueID == newConsumer), "The refreshed 2.0 disk manifest must neither keep the resident 1.0 provider active nor authorize the new >=2.0 consumer.");
                Assert(AtomicOwnerProbeMod.EntryCount == 2, "In-place upgrade reconciliation must not execute the provider again or enter the new consumer in the old process.");
                Assert(cleanupOrder.OwnerIds.SequenceEqual(new[] { existingConsumer, provider }, StringComparer.OrdinalIgnoreCase), "In-place version handoff must deactivate the existing required consumer before the resident provider.");
                Assert(runtime.OwnerRequiresRestart(provider) && runtime.OwnerRequiresRestart(existingConsumer), "The resident provider assembly and its deactivated consumer must remain restart-required.");
                Assert(!runtime.OwnerRequiresRestart(newConsumer), "A newly discovered consumer that never entered must not manufacture a restart-required owner state.");
                Assert(runtime.ModRegistry.Get(provider) == null && runtime.ModRegistry.CountOwner(provider) == 0 && runtime.ModRegistry.CountOwner(existingConsumer) == 0 && runtime.ModRegistry.CountOwner(newConsumer) == 0, "Version handoff and blocked new-consumer load must leave no registry/API root from the old process graph.");
                Assert(CountCoreOwnerRootsForTest(runtime, provider) == 0 && CountCoreOwnerRootsForTest(runtime, existingConsumer) == 0 && CountCoreOwnerRootsForTest(runtime, newConsumer) == 0, "In-place upgrade reconciliation must leave every affected owner at zero Core roots.");
                Assert(runtime.CreateSnapshot().Errors.Any(error => error.Owner == newConsumer && error.Message.Contains("依赖", StringComparison.OrdinalIgnoreCase)), "The >=2.0 consumer should expose a missing/unavailable dependency diagnostic rather than load against stale resident code.");

                AtomicOwnerProbeMod.EntryCount = 0;
                var restartedRuntime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                restartedRuntime.Start();
                Assert(restartedRuntime.ModRegistry.Get(provider)?.Version == "2.0.0", "A clean runtime may publish the updated provider's 2.0 canonical manifest.");
                Assert(restartedRuntime.LoadedMods.Count(mod => mod.Manifest.UniqueID == provider || mod.Manifest.UniqueID == existingConsumer || mod.Manifest.UniqueID == newConsumer) == 3 && AtomicOwnerProbeMod.EntryCount == 3, "Only the clean runtime may enter provider 2.0 and both compatible consumers.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void RuntimeUiBoundariesIsolateInputWithoutStoppingModUpdates()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
            string dir = NewTempGameDir();
            var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
            IEventsHelper events = CreateEventsProxy(runtime, "DTMAPI.Tests.Events");
            int pressed = 0;
            int released = 0;
            int updates = 0;
            int menuOpened = 0;
            int menuClosed = 0;
            int saveScopedPressed = 0;
            int gameplayScopedPressed = 0;
            events.Input.ButtonPressed += (_, _) => pressed++;
            events.Input.ButtonReleased += (_, _) => released++;
            events.Input.KeybindPressed += (_, e) =>
            {
                if (e.KeybindId == "save-ui-close")
                    saveScopedPressed++;
                else if (e.KeybindId == "gameplay-only")
                    gameplayScopedPressed++;
            };
            events.GameLoop.UpdateTicked += (_, _) => updates++;
            events.UI.MenuOpened += (_, _) => menuOpened++;
            events.UI.MenuClosed += (_, _) => menuClosed++;

            IInputHelper scopedInput = ((InputService)GetInput(runtime)).CreateOwnerBound("DTMAPI.Tests.Events");
            scopedInput.RegisterKeybind("save-ui-close", "Y", DtmInputScope.SaveLoaded);
            scopedInput.RegisterKeybind("gameplay-only", "F6", DtmInputScope.Gameplay);
            scopedInput.RegisterButton("F10");

            runtime.Start();
            runtime.UI.SetUiContext("Gameplay", canDrawOverlay: true, gameplayHotkeysAllowed: true, reason: "unit test");
            runtime.RecordInputFrame(new[] { new InputButtonSample("F10", true, true, false) });
            runtime.RecordInputFrame(new[] { new InputButtonSample("F10", false, false, true) });
            runtime.Update();
            Assert(pressed == 1 && released == 1 && updates == 1, $"Gameplay context should deliver input and update events. pressed={pressed} released={released} updates={updates} open={runtime.UI.IsOpen} context={runtime.UI.InputContext}");

            runtime.UI.OpenOwnerBoundCustomMenu("DTMAPI.Tests.OwnerModal", "DTMAPI.Tests.Events");
            Assert(menuOpened == 1 && runtime.UI.BlocksGameplayHotkeys, "An owner modal should block gameplay input while leaving the shared update clock independent.");
            runtime.Input.ClearFrame();
            runtime.RecordInputFrame(new[] { new InputButtonSample("Y", false, true, true) });
            runtime.Input.ClearFrame();
            runtime.RecordInputFrame(new[] { new InputButtonSample("F6", false, true, true) });
            Assert(saveScopedPressed == 1, "A SaveLoaded-scoped keybind must remain targeted to its owner while that owner's in-save modal is open.");
            Assert(gameplayScopedPressed == 0, "A Gameplay-scoped keybind must remain blocked while an owner modal is open.");
            int pressedAfterSaveScopedUiInput = pressed;
            int releasedAfterSaveScopedUiInput = released;
            runtime.RecordInputFrame(new[] { new InputButtonSample("F10", true, true, false) });
            runtime.RecordInputFrame(new[] { new InputButtonSample("F10", false, false, true) });
            runtime.Update();
            Assert(pressed == pressedAfterSaveScopedUiInput && released == releasedAfterSaveScopedUiInput && updates == 2, "Owner modal must not deliver gameplay input, while UpdateTicked continues with native world time.");
            Assert(!runtime.IsInputDown("F10"), "Blocked input should not leave a stuck down-state.");

            runtime.UI.Close();
            Assert(menuClosed == 1, "Close should dispatch the menu closed event.");
            runtime.UI.SetUiContext("ModUiState", canDrawOverlay: true, gameplayHotkeysAllowed: false, reason: "official mod menu");
            runtime.RecordInputFrame(new[] { new InputButtonSample("F10", true, true, false) });
            runtime.RecordInputFrame(new[] { new InputButtonSample("F10", false, false, true) });
            Assert(pressed == pressedAfterSaveScopedUiInput && released == releasedAfterSaveScopedUiInput, "Official UI contexts should expose a platform-modal audience and deliver no Mod input.");
            Assert(!runtime.IsInputDown("F10"), "Blocked official-menu input should not leave a stuck down-state.");
            runtime.Update();
            Assert(updates == 3, "Platform-modal input isolation must not stop the shared UpdateTicked clock.");

            runtime.UI.SetUiContext("Gameplay", canDrawOverlay: true, gameplayHotkeysAllowed: true, reason: "unit test");
            runtime.RecordInputFrame(new[] { new InputButtonSample("F10", true, true, false) });
            runtime.RecordInputFrame(new[] { new InputButtonSample("F10", false, false, true) });
            runtime.Update();
            Assert(pressed == pressedAfterSaveScopedUiInput + 1 && released == releasedAfterSaveScopedUiInput + 1 && updates == 4, $"Gameplay input should resume after closing the menu while updates remain continuous. pressed={pressed}/{pressedAfterSaveScopedUiInput + 1} released={released}/{releasedAfterSaveScopedUiInput + 1} updates={updates}/4");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void InputAudienceSnapshotRemainsImmutableForTheFrame()
        {
            var input = new InputService(() => true);
            IInputHelper owner = input.CreateOwnerBound("DTMAPI.Tests.Audience.Owner");
            owner.RegisterButton("F10");
            int pressed = 0;
            Func<InputButtonDispatch, EventDeliveryReceipt> press = dispatch =>
            {
                pressed++;
                return new EventDeliveryReceipt(new[] { "DTMAPI.Tests.Audience.Owner" });
            };
            Action<InputReleaseDispatch> release = _ => { };
            Func<InputKeybindDispatch, string, EventDeliveryReceipt> keyPress = (_, _) => EventDeliveryReceipt.Empty;
            Action<InputKeybindReleaseDispatch> keyRelease = _ => { };

            var normal = new InputAudienceSnapshot(InputAudienceMode.Normal, string.Empty, DtmInputScope.Gameplay, 1);
            var platform = new InputAudienceSnapshot(InputAudienceMode.PlatformModal, string.Empty, DtmInputScope.SaveLoaded, 2);
            Assert(input.GetButtonsToSample(normal).SequenceEqual(new[] { "F10" }), "Normal audience should sample its active registered button.");
            input.RecordFrame(
                platform,
                new[] { new InputButtonSample("F10", false, true, true) },
                press,
                release,
                keyPress,
                keyRelease);
            Assert(pressed == 1, "Opening a platform UI after sampling must not mutate the already-frozen normal audience.");

            input.ClearFrame();
            Assert(input.GetButtonsToSample(platform).SequenceEqual(new[] { "F10" }), "A platform-modal frame may keep a rearm button sampled without making it eligible for Mod input.");
            input.RecordFrame(
                normal,
                new[] { new InputButtonSample("F10", false, true, true) },
                press,
                release,
                keyPress,
                keyRelease);
            Assert(pressed == 1, "Closing the platform UI after sampling must take effect only on the next frame.");
        }

        private static void InputOwnerModalTargetsQueriesAndSettlesRelease()
        {
            const string ownerAId = "DTMAPI.Tests.Modal.OwnerA";
            const string ownerBId = "DTMAPI.Tests.Modal.OwnerB";
            var input = new InputService(() => true);
            IInputHelper ownerA = input.CreateOwnerBound(ownerAId);
            IInputHelper ownerB = input.CreateOwnerBound(ownerBId);
            ownerA.RegisterKeybind("close", "Y", DtmInputScope.SaveLoaded);
            ownerB.RegisterKeybind("observe", "Y", DtmInputScope.SaveLoaded);

            int ownerAPressed = 0;
            int ownerAReleased = 0;
            int ownerBPressed = 0;
            int ownerBReleased = 0;
            Func<InputButtonDispatch, EventDeliveryReceipt> press = dispatch =>
            {
                Assert(dispatch.TargetOwnerId == ownerAId, "Owner-modal button delivery must target only the modal owner.");
                ownerAPressed++;
                return new EventDeliveryReceipt(new[] { ownerAId });
            };
            Action<InputReleaseDispatch> release = dispatch =>
            {
                Assert(dispatch.IsSettlement && dispatch.RecipientOwnerIds.SequenceEqual(new[] { ownerAId }), "Release must settle only the owner that received Pressed.");
                ownerAReleased++;
            };
            Func<InputKeybindDispatch, string, EventDeliveryReceipt> keyPress = (dispatch, targetOwnerId) =>
            {
                Assert(dispatch.OwnerId == ownerAId && targetOwnerId == ownerAId, "Owner-modal keybind delivery must be registration- and event-owner targeted.");
                return new EventDeliveryReceipt(new[] { ownerAId });
            };
            Action<InputKeybindReleaseDispatch> keyRelease = dispatch =>
            {
                Assert(dispatch.IsSettlement && dispatch.RecipientOwnerIds.SequenceEqual(new[] { ownerAId }), "Keybind Release must retain the exact Pressed receipt.");
            };

            var ownerModal = new InputAudienceSnapshot(InputAudienceMode.OwnerModal, ownerAId, DtmInputScope.SaveLoaded, 10);
            input.GetButtonsToSample(ownerModal);
            input.RecordFrame(
                ownerModal,
                new[] { new InputButtonSample("Y", true, true, false) },
                press,
                release,
                keyPress,
                keyRelease);
            Assert(ownerAPressed == 1 && ownerA.IsDown("Y") && ownerA.WasPressed("Y"), "Modal owner should receive and query its registered non-gameplay input.");
            Assert(!ownerB.IsDown("Y") && !ownerB.WasPressed("Y"), "A non-owner must see neutral state even when it registered the same button.");
            ownerB.Suppress("Y");
            Assert(ownerA.IsDown("Y"), "A non-owner Suppress call must be inert during an owner modal.");
            ownerA.Suppress("Y");
            Assert(!ownerA.IsDown("Y") && !ownerA.WasPressed("Y"), "The modal owner may suppress only its current-frame visible state.");

            input.ClearFrame();
            var normal = new InputAudienceSnapshot(InputAudienceMode.Normal, string.Empty, DtmInputScope.Gameplay, 11);
            input.GetButtonsToSample(normal);
            input.RecordFrame(
                normal,
                new[] { new InputButtonSample("Y", false, false, true) },
                dispatch =>
                {
                    ownerBPressed++;
                    return new EventDeliveryReceipt(new[] { ownerAId, ownerBId });
                },
                release,
                keyPress,
                keyRelease);
            Assert(ownerAReleased == 1 && ownerBReleased == 0, "Closing the modal before physical release must still settle only the prior Pressed audience.");
            Assert(ownerA.WasReleased("Y") && !ownerB.WasReleased("Y"), "Settlement Release visibility must be exact-owner even after eligibility changes.");
            Assert(ownerBPressed == 0, "A release after modal close must not synthesize a Pressed for the newly eligible owner.");
        }

        private static void InputConfigurationUpdateRetainsPressedBindingForRelease()
        {
            const string ownerId = "DTMAPI.Tests.ConfigLedger";
            var input = new InputService(() => true);
            IInputHelper owner = input.CreateOwnerBound(ownerId);
            IInputRegistration registration = owner.RegisterKeybind("toggle", "F6", DtmInputScope.Gameplay);
            string releasedBinding = string.Empty;
            int presses = 0;
            Func<InputButtonDispatch, EventDeliveryReceipt> buttonPress = _ => EventDeliveryReceipt.Empty;
            Action<InputReleaseDispatch> buttonRelease = _ => { };
            Func<InputKeybindDispatch, string, EventDeliveryReceipt> keyPress = (dispatch, _) =>
            {
                presses++;
                return new EventDeliveryReceipt(new[] { ownerId });
            };
            Action<InputKeybindReleaseDispatch> keyRelease = dispatch => releasedBinding = dispatch.Keybind.Keybinds.ToString();
            var normal = new InputAudienceSnapshot(InputAudienceMode.Normal, string.Empty, DtmInputScope.Gameplay, 20);

            input.GetButtonsToSample(normal);
            input.RecordFrame(
                normal,
                new[] { new InputButtonSample("F6", true, true, false) },
                buttonPress,
                buttonRelease,
                keyPress,
                keyRelease);
            Assert(presses == 1, "Initial configured keybind should deliver Pressed.");
            input.ClearFrame();

            registration.Update("Y", DtmInputScope.Gameplay);
            Assert(input.GetButtonsToSample(normal).OrderBy(value => value).SequenceEqual(new[] { "F6", "Y" }), "A changed binding must keep the old pressed chord sampled until settlement.");
            input.RecordFrame(
                normal,
                new[]
                {
                    new InputButtonSample("F6", false, false, true),
                    new InputButtonSample("Y", false, false, false)
                },
                buttonPress,
                buttonRelease,
                keyPress,
                keyRelease);
            Assert(releasedBinding == "F6", "Configuration mutation must release the exact old binding snapshot, not the replacement binding.");
            input.ClearFrame();

            input.GetButtonsToSample(normal);
            input.RecordFrame(
                normal,
                new[] { new InputButtonSample("Y", true, true, false) },
                buttonPress,
                buttonRelease,
                keyPress,
                keyRelease);
            Assert(presses == 2, "After a neutral sample, the replacement binding should begin a new input cycle normally.");
        }

        private static void InputSuppressionPreservesPhysicalCycleAndOwedRelease()
        {
            const string ownerId = "DTMAPI.Tests.SuppressLedger";
            var input = new InputService(() => true);
            IInputHelper owner = input.CreateOwnerBound(ownerId);
            owner.RegisterButton("F6");
            int presses = 0;
            int releases = 0;
            var normal = new InputAudienceSnapshot(InputAudienceMode.Normal, string.Empty, DtmInputScope.Gameplay, 30);
            Func<InputButtonDispatch, EventDeliveryReceipt> press = _ =>
            {
                presses++;
                return new EventDeliveryReceipt(new[] { ownerId });
            };
            Action<InputReleaseDispatch> release = _ => releases++;
            Func<InputKeybindDispatch, string, EventDeliveryReceipt> keyPress = (_, _) => EventDeliveryReceipt.Empty;
            Action<InputKeybindReleaseDispatch> keyRelease = _ => { };

            input.GetButtonsToSample(normal);
            input.RecordFrame(normal, new[] { new InputButtonSample("F6", true, true, false) }, press, release, keyPress, keyRelease);
            owner.Suppress("F6");
            Assert(!owner.IsDown("F6") && !owner.WasPressed("F6"), "Suppress should hide current owner-visible state after delivery.");
            input.ClearFrame();

            Assert(input.GetButtonsToSample(normal).Contains("F6", StringComparer.OrdinalIgnoreCase), "A physically held and release-owed button must remain sampled after suppression.");
            input.RecordFrame(normal, new[] { new InputButtonSample("F6", true, false, false) }, press, release, keyPress, keyRelease);
            Assert(presses == 1 && owner.IsDown("F6") && !owner.WasPressed("F6"), "Suppression must not erase physical down or manufacture a next-frame Pressed.");
            input.ClearFrame();

            input.GetButtonsToSample(normal);
            input.RecordFrame(normal, new[] { new InputButtonSample("F6", false, false, true) }, press, release, keyPress, keyRelease);
            Assert(releases == 1 && owner.WasReleased("F6"), "Suppress must not cancel the exact settlement Release owed by the prior Pressed.");
        }

        private static void InputAudienceSteadyStateDoesNotAllocate()
        {
            const string ownerId = "DTMAPI.Tests.Audience.Allocation";
            var input = new InputService(() => true);
            input.CreateOwnerBound(ownerId).RegisterKeybind("toggle", "F6", DtmInputScope.SaveLoaded);
            var samples = new[] { new InputButtonSample("F6", false, false, false) };
            Func<InputButtonDispatch, EventDeliveryReceipt> buttonPress = _ => EventDeliveryReceipt.Empty;
            Action<InputReleaseDispatch> buttonRelease = _ => { };
            Func<InputKeybindDispatch, string, EventDeliveryReceipt> keyPress = (_, _) => EventDeliveryReceipt.Empty;
            Action<InputKeybindReleaseDispatch> keyRelease = _ => { };
            var normal = new InputAudienceSnapshot(InputAudienceMode.Normal, string.Empty, DtmInputScope.Gameplay, 40);
            var modal = new InputAudienceSnapshot(InputAudienceMode.OwnerModal, ownerId, DtmInputScope.SaveLoaded, 41);

            for (int index = 0; index < 256; index++)
            {
                input.GetButtonsToSample(normal);
                input.RecordFrame(normal, samples, buttonPress, buttonRelease, keyPress, keyRelease);
                input.ClearFrame();
            }
            GC.Collect();
            GC.WaitForPendingFinalizers();
            GC.Collect();
            long normalBefore = GC.GetAllocatedBytesForCurrentThread();
            for (int index = 0; index < 10000; index++)
            {
                input.GetButtonsToSample(normal);
                input.RecordFrame(normal, samples, buttonPress, buttonRelease, keyPress, keyRelease);
                input.ClearFrame();
            }
            long normalAllocated = GC.GetAllocatedBytesForCurrentThread() - normalBefore;
            Assert(normalAllocated == 0, "10,000 stable normal-audience frames should allocate zero Core bytes; allocated=" + normalAllocated.ToString(CultureInfo.InvariantCulture) + ".");

            for (int index = 0; index < 256; index++)
            {
                input.GetButtonsToSample(modal);
                input.RecordFrame(modal, samples, buttonPress, buttonRelease, keyPress, keyRelease);
                input.ClearFrame();
            }
            GC.Collect();
            GC.WaitForPendingFinalizers();
            GC.Collect();
            long modalBefore = GC.GetAllocatedBytesForCurrentThread();
            for (int index = 0; index < 10000; index++)
            {
                input.GetButtonsToSample(modal);
                input.RecordFrame(modal, samples, buttonPress, buttonRelease, keyPress, keyRelease);
                input.ClearFrame();
            }
            long modalAllocated = GC.GetAllocatedBytesForCurrentThread() - modalBefore;
            Assert(modalAllocated == 0, "10,000 stable owner-modal frames should allocate zero Core bytes; allocated=" + modalAllocated.ToString(CultureInfo.InvariantCulture) + ".");
        }

        private static void Suppress_OneFrame_ClearsAfterUpdate()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                IInputHelper input = GetInput(runtime);
                IEventsHelper events = CreateEventsProxy(runtime, "DTMAPI.Tests.Suppress");
                int pressed = 0;
                int released = 0;
                events.Input.ButtonPressed += (_, _) => pressed++;
                events.Input.ButtonReleased += (_, _) => released++;

                runtime.Start();
                runtime.UI.SetUiContext("Gameplay", canDrawOverlay: true, gameplayHotkeysAllowed: true, reason: "unit test");
                input.RegisterButton("F10");
                input.Suppress(" F10 ");
                runtime.RecordInputFrame(new[] { new InputButtonSample("F10", true, true, false) });
                runtime.RecordInputFrame(new[] { new InputButtonSample("F10", false, false, true) });
                Assert(pressed == 0 && released == 0, "Suppressed input should not dispatch DTMAPI input events during the current frame.");
                Assert(!input.WasPressed("F10"), "Suppressed input should not be reported as pressed.");
                Assert(!input.IsDown("F10"), "Suppressed input should not leave a down-state.");
                Assert(input.GetSuppressedButtons().Contains("F10", StringComparer.OrdinalIgnoreCase), "Suppressed input should be visible during the current frame.");

                runtime.Update();
                Assert(!input.WasPressed("F10"), "Runtime update should clear one-frame pressed input state.");
                Assert(!input.GetSuppressedButtons().Contains("F10", StringComparer.OrdinalIgnoreCase), "Runtime update should clear one-frame suppressed input state.");
                Assert(!input.IsDown("F10"), "Suppressed input should remain released after the frame clears.");

                runtime.RecordInputFrame(new[] { new InputButtonSample("F10", true, true, false) });
                Assert(pressed == 1 && input.WasPressed("F10") && input.IsDown("F10"), "Input should dispatch normally after one-frame suppression clears.");
                input.Suppress("F10");
                Assert(!input.WasPressed("F10") && !input.IsDown("F10"), "Suppressing after a press should clear helper pressed/down state even though the already-dispatched event cannot be undone.");
                runtime.RecordInputFrame(new[] { new InputButtonSample("F10", false, false, true) });
                Assert(released == 1, "One-frame suppression must not cancel the settlement Release owed to an owner that received Pressed.");
                runtime.Update();
                runtime.RecordInputFrame(new[] { new InputButtonSample("F10", true, true, false) });
                runtime.RecordInputFrame(new[] { new InputButtonSample("F10", false, false, true) });
                Assert(pressed == 2 && released == 2, "Input release should dispatch normally after suppression clears in addition to the prior settlement Release.");
                Assert(!input.IsDown("F10"), "Released input should clear the down-state.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void HookCallbackSafeFallbacksReturnFallbacksAndRecordDiagnostics()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                Type callbacks = typeof(DolocTownHookCallbacks);
                callbacks.GetProperty(nameof(DolocTownHookCallbacks.Runtime))!.SetValue(null, runtime);
                callbacks.GetProperty(nameof(DolocTownHookCallbacks.Bridge))!.SetValue(null, null);

                MethodInfo safeResult = callbacks.GetMethod("SafeResult", BindingFlags.NonPublic | BindingFlags.Static)!.MakeGenericMethod(typeof(string));
                MethodInfo safePrefix = callbacks.GetMethod("SafePrefix", BindingFlags.NonPublic | BindingFlags.Static)!;
                MethodInfo safePostfix = callbacks.GetMethod("SafePostfix", BindingFlags.NonPublic | BindingFlags.Static)!;

                string result = (string)safeResult.Invoke(null, new object[] { "Test.SafeResult", "fallback", new Func<string>(() => throw new InvalidOperationException("safe-result-boom")) })!;
                bool prefix = (bool)safePrefix.Invoke(null, new object[] { "Test.SafePrefix", new Func<bool>(() => throw new InvalidOperationException("safe-prefix-boom")), true })!;
                safePostfix.Invoke(null, new object[] { "Test.SafePostfix", new Action(() => throw new InvalidOperationException("safe-postfix-boom")) });
                for (int i = 0; i < 6; i++)
                    safePostfix.Invoke(null, new object[] { "Test.SafePostfix.Repeated", new Action(() => throw new InvalidOperationException("safe-postfix-repeat-boom")) });

                Assert(result == "fallback", "SafeResult should return fallback when a hook callback throws.");
                Assert(prefix, "SafePrefix should use the native-pass fallback when a hook callback throws.");
                Assert(runtime.Diagnostics.GetErrors().Count(e => e.Owner == "DTMAPI.GameBridge.HookCallback") == 4, "Hook callback safe helpers should record one diagnostics error per failed operation.");
                Assert(runtime.Diagnostics.GetErrors().Count(e => e.Message.Contains("Test.SafePostfix.Repeated", StringComparison.Ordinal)) == 1, "Repeated hook callback failures should be throttled in diagnostics.");
            }
            finally
            {
                DolocTownHookCallbacks.Runtime = null;
                DolocTownHookCallbacks.Bridge = null;
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void NativeUiLayoutRepairKeepsExactRepairsAndRetiresGenericHooks()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                var feature = new NativeUiLayoutDiagnosticsFeature(runtime);

                var homeMenu = new DolocTown.UI.HomePageTextMenu();
                DolocAPI.userInput = new DolocAPI.FakeUserInput
                {
                    CurrentState = new DolocTown.HomePageUiState { textMenu = homeMenu }
                };
                feature.Update();
                Assert(homeMenu.slotLayoutGroup.constraintCount == 1 && homeMenu.RebuildCount == 1,
                    "The mandatory active-layout updater must restore the exact HomePage menu without a generic ResetLayoutSize hook.");

                var mainMenu = new DolocTown.UI.MenuUI();
                for (int i = 0; i < 8; i++)
                    mainMenu.slots.Add(new DolocTown.UI.MenuButton { isVisible = i != 3 });
                var activeMainState = new DolocTown.MainMenuUiState { panel = new DolocTown.UI.MainMenuPanel { menu = mainMenu } };
                DolocAPI.userInput = new DolocAPI.FakeUserInput { CurrentState = activeMainState };
                feature.Update();
                Assert(mainMenu.slotLayoutGroup.constraintCount == 7 && mainMenu.RebuildCount == 1,
                    "The mandatory active-layout updater must restore the exact MenuUI visible icon count without a generic ResetLayoutSize hook.");

                string repo = FindRepositoryRoot();
                string featureSource = File.ReadAllText(Path.Combine(repo, "src", "DTMAPI.GameBridge.DolocTown", "Features", "UiDiagnostics", "NativeUiLayoutDiagnosticsFeature.cs"));
                string callbackSource = File.ReadAllText(Path.Combine(repo, "src", "DTMAPI.GameBridge.DolocTown", "Hooking", "DolocTownHookCallbacks.cs"));
                string repairSource = File.ReadAllText(Path.Combine(repo, "src", "DTMAPI.GameBridge.DolocTown", "Features", "UiDiagnostics", "NativeUiLayoutRepairService.cs"));
                string patcherSource = File.ReadAllText(Path.Combine(repo, "src", "DTMAPI.GameBridge.DolocTown", "Hooking", "HarmonyReflectionPatcher.cs"));
                string bootstrapSource = File.ReadAllText(Path.Combine(repo, "src", "DTMAPI.BepInExBootstrap", "BootstrapPlugin.cs"));
                string demandSource = File.ReadAllText(Path.Combine(repo, "src", "DTMAPI.GameBridge.DolocTown", "Demand", "DolocTownGameBridge.Demand.cs"));
                string featureCompact = new string(featureSource.Where(character => !char.IsWhiteSpace(character)).ToArray());
                string bootstrapCompact = new string(bootstrapSource.Where(character => !char.IsWhiteSpace(character)).ToArray());
                string demandCompact = new string(demandSource.Where(character => !char.IsWhiteSpace(character)).ToArray());
                Assert(!featureSource.Contains("DolocGridUI`1", StringComparison.Ordinal) &&
                    !featureSource.Contains("ResetLayoutSize", StringComparison.Ordinal) &&
                    !featureSource.Contains("GridLayoutConstraintCountPrefixPatched", StringComparison.Ordinal) &&
                    !callbackSource.Contains("GridLayoutGroupConstraintCountSetPrefix", StringComparison.Ordinal) &&
                    !repairSource.Contains("NormalizeGridLayoutConstraintCount", StringComparison.Ordinal),
                    "Native UI production source must contain neither generic DolocGridUI attempts nor the unreachable global GridLayoutGroup setter lane.");
                Assert(featureCompact.Contains(
                        "patcher.TryPatchPostfix(\"DolocTown.HomePageUiState,Assembly-CSharp\",\"RenderTextMenu\",typeof(DolocTownHookCallbacks).GetMethod(nameof(DolocTownHookCallbacks.HomePageRenderTextMenuPostfix),BindingFlags.Public|BindingFlags.Static),0)",
                        StringComparison.Ordinal) &&
                    featureCompact.Contains(
                        "patcher.TryPatchPostfix(\"DolocTown.UI.MainMenuPanel,Assembly-CSharp\",\"OnStartShow\",typeof(DolocTownHookCallbacks).GetMethod(nameof(DolocTownHookCallbacks.MainMenuPanelOnStartShowPostfix),BindingFlags.Public|BindingFlags.Static),0)",
                        StringComparison.Ordinal) &&
                    featureCompact.Contains(
                        "patcher.TryPatchPostfix(\"DolocTown.UI.MenuUI,Assembly-CSharp\",\"SetCapacity\",typeof(DolocTownHookCallbacks).GetMethod(nameof(DolocTownHookCallbacks.MenuUiSetCapacityPostfix),BindingFlags.Public|BindingFlags.Static),1)",
                        StringComparison.Ordinal) &&
                    featureCompact.Contains(
                        "patcher.TryPatchPostfix(\"DolocTown.UI.GameDataPanel,Assembly-CSharp\",\"SetCapacity\",typeof(DolocTownHookCallbacks).GetMethod(nameof(DolocTownHookCallbacks.GameDataPanelSetCapacityPostfix),BindingFlags.Public|BindingFlags.Static),1)",
                        StringComparison.Ordinal) &&
                    featureCompact.Contains("publicvoidUpdate(){RepairService.UpdateActiveMenuLayout();}", StringComparison.Ordinal),
                    "Native UI production source must retain all four exact target/method/callback tuples plus the active-layout dispatch.");
                Assert(demandCompact.Contains(
                        "ConfigureDemandRoute(GameBridgeDemandRoutes.NativeUiLayoutDiagnostics,TimeSpan.FromMilliseconds(250),()=>nativeUiLayoutDiagnosticsFeature?.Update()",
                        StringComparison.Ordinal),
                    "The mandatory active-layout repair must remain wired to the 250ms demand cadence.");
                Assert(!callbackSource.Contains("DolocGridUiResetLayoutSizePostfix", StringComparison.Ordinal) &&
                    !callbackSource.Contains("DolocGridUiSetCapacityPostfix", StringComparison.Ordinal) &&
                    !callbackSource.Contains("HomePageTextMenuResetLayoutSize", StringComparison.Ordinal) &&
                    !callbackSource.Contains("MenuUiResetLayoutSize", StringComparison.Ordinal),
                    "Callbacks dedicated to the six retired generic UI hooks must be absent.");
                Assert(!patcherSource.Contains("TryPatchClosedGeneric", StringComparison.Ordinal),
                    "The patcher helper used only by retired generic UI hooks must be absent.");
                Assert(!bootstrapSource.Contains("TryStartCoroutineLoop", StringComparison.Ordinal) &&
                    !bootstrapSource.Contains("RuntimeCoroutine", StringComparison.Ordinal) &&
                    !bootstrapSource.Contains("TickFromUnity(\"Coroutine\")", StringComparison.Ordinal) &&
                    bootstrapCompact.Contains("privatevoidOnPlayerLoopUpdate()", StringComparison.Ordinal) &&
                    bootstrapCompact.Contains("TickFromUnity(\"PlayerLoop\");", StringComparison.Ordinal) &&
                    bootstrapCompact.Contains("privatevoidOnInputSystemAfterUpdate()", StringComparison.Ordinal) &&
                    bootstrapCompact.Contains("TickFromUnity(\"InputSystemAfterUpdate\");", StringComparison.Ordinal) &&
                    bootstrapCompact.Contains("publicvoidUpdate()", StringComparison.Ordinal) &&
                    bootstrapCompact.Contains("TickFromUnity(\"Update\");", StringComparison.Ordinal) &&
                    bootstrapCompact.Contains("privatevoidOnNativeGameFrame()", StringComparison.Ordinal) &&
                    bootstrapCompact.Contains("TickFromUnity(\"NativeGameUpdate\");", StringComparison.Ordinal) &&
                    bootstrapCompact.Contains("runtime.SaveSessionLoaded+=(slot,isNewGame)=>ReinstallPlayerLoopFrameDriver(\"SaveLoaded\")", StringComparison.Ordinal) &&
                    bootstrapCompact.Contains("runtime.ReturnedToTitleBoundary+=()=>ReinstallPlayerLoopFrameDriver(\"ReturnedToTitle\")", StringComparison.Ordinal) &&
                    bootstrapCompact.Contains("runtime.NativeLoadGameReturned+=(slot,result)=>ReinstallPlayerLoopFrameDriver(\"LoadGameReturned:\"", StringComparison.Ordinal) &&
                    bootstrapCompact.Contains("StartFallbackPump();", StringComparison.Ordinal),
                    "Bootstrap must retire the coroutine driver while retaining exact PlayerLoop, InputSystem, Update, native-frame, lifecycle-reinstall and health-pump wiring.");
                Assert(bootstrapSource.Contains("RecordWarning(\"DTMAPI.BepInExBootstrap\", \"Fallback health pump is unavailable.\"", StringComparison.Ordinal) &&
                    !bootstrapSource.Contains("RecordError(\"DTMAPI.BepInExBootstrap\", \"Failed to start fallback tick pump.\"", StringComparison.Ordinal) &&
                    bootstrapCompact.Contains("if(Volatile.Read(refshutdownStarted)!=0||!initialized||runtime==null)return;", StringComparison.Ordinal) &&
                    bootstrapCompact.Contains("if(Volatile.Read(refshutdownStarted)==0&&initialized)RunFallbackHealthCheck();", StringComparison.Ordinal) &&
                    bootstrapCompact.Contains("privatevoidRunFallbackHealthCheck(){if(Volatile.Read(refshutdownStarted)!=0||!initialized)return;", StringComparison.Ordinal) &&
                    bootstrapCompact.Contains("if(Interlocked.Exchange(refshutdownStarted,1)!=0)return;initialized=false;", StringComparison.Ordinal),
                    "The optional health pump must warn rather than turn player status red, and shutdown must close queued health callbacks before driver cleanup.");
            }
            finally
            {
                DolocAPI.userInput = null;
                RestorePersistentRoot(previousRoot);
            }
        }

