                runnerSource.Contains("$noQaAnimalViewerProductClosePattern = 'AnimalHusbandryProgress native panel closed; product-owned derived rows and clones are zero.'", StringComparison.Ordinal) &&
                runnerSource.Contains("$noQaAnimalViewerOverlayClearOk = $noQaAnimalViewerNativeCloseOk", StringComparison.Ordinal) &&
                runnerSource.Contains("$noQaEquipmentSlotsDownstreamInteractionOk = $noQaAnimalViewerUiOk", StringComparison.Ordinal) &&
