                !candidate11Source.Contains("UI\\.DebugConsoleItemTooltip = visible\\.", StringComparison.Ordinal),
                "The Candidate11 ISSUE-011 verifier must consume the same current DebugConsole tooltip/search receipt schema emitted by the smoke runner.");

            int noQaHandshake = runnerSource.IndexOf("NO-QA ORDINARY-PLAYER HANDSHAKE: no internal QA auto-load or ReturnHome navigation is active.", StringComparison.Ordinal);
            int noQaSaveLoadedWait = runnerSource.IndexOf("$saveLoadedOk = (Test-SmokeDeadlineHasBudget -Deadline $noQaRunnerDeadline) -and", StringComparison.Ordinal);
            Assert(runnerSource.Contains("function Get-SmokeRemainingBudgetSeconds", StringComparison.Ordinal) &&
