                runnerSource.Contains("$noQaUiDeadline = $noQaRunnerDeadline", StringComparison.Ordinal) &&
                runnerSource.Contains("Get-SmokeRemainingBudgetSeconds -Deadline $noQaRunnerDeadline -MaximumSeconds $TimeoutSeconds", StringComparison.Ordinal) &&
                runnerSource.Contains("Get-SmokeRemainingBudgetSeconds -Deadline $noQaRunnerDeadline -MaximumSeconds 60", StringComparison.Ordinal) &&
                runnerSource.Contains("Get-SmokeRemainingBudgetSeconds -Deadline $noQaRunnerDeadline", StringComparison.Ordinal) &&
