                runnerSource.Contains("-Pattern 'SaveLoaded hook dispatched.' -Deadline $noQaRunnerDeadline", StringComparison.Ordinal) &&
                runnerSource.Contains("$autoExitAfterSeconds = if ($AssertNoQaUiEvidence)", StringComparison.Ordinal) &&
                runnerSource.Contains("$processWaitSeconds = if ($AssertNoQaUiEvidence)", StringComparison.Ordinal) &&
                runnerSource.Contains("$noQaProcessWaitSeconds = $processWaitSeconds", StringComparison.Ordinal) &&
                runnerSource.Contains("NoQaBehaviorCompletedBeforeDeadline", StringComparison.Ordinal) &&
                !runnerSource.Contains("$noQaUiDeadline = (Get-Date).AddSeconds($TimeoutSeconds)", StringComparison.Ordinal) &&
                noQaHandshake >= 0 && noQaSaveLoadedWait > noQaHandshake,
