            Assert(runnerSource.Contains("Mod-owner cleanup participants owner=Yuuka\\.DTMAPI\\.ActionSpeed, reason=ReturnedToTitle", StringComparison.Ordinal) &&
                runnerSource.Contains("remaining=0, failures=0, results=.*DTMAPI\\.GameBridge\\.DolocTown\\.OwnerResources:[0-9]+/0:ok", StringComparison.Ordinal) &&
                !runnerSource.Contains("ActionSpeed restore logic OK reason=ReturnedToTitle", StringComparison.Ordinal),
