                runnerSource.Contains("Hook status: Compatibility\\.Host = resident\\..*service=EquipmentSlots' -TimeoutSeconds $TimeoutSeconds -Regex", StringComparison.Ordinal) &&
                runnerSource.Contains("DTMAPI\\.MoreEquipmentSlotsMod recovered=1 message=.*(native backpack|native item mail)' -TimeoutSeconds $TimeoutSeconds -Regex", StringComparison.Ordinal) &&
                runnerSource.Contains("MoreEquipmentSlots product-owned Hook set installed|MoreEquipmentSlots ProductNative ready", StringComparison.Ordinal) &&
