                "The MoreEquipmentSlots route must protect the save/config transaction, fail the incomplete cold acceptance closed, bind a future official package to tracked authority, and verify exact four-target/callback/root cleanup through the real Loader.");
        }

        private static void ZoomAcceptanceRoutingRequiresProductNativeTitleAndExactOwnerCleanup()
        {
            string shell = GetWindowsPowerShell51Path();
            using JsonDocument g5Route = RunBatch4Routing(
                shell,
                "-StageQaHost",
                "-AutoExerciseZoomProductNative",
                "-SaveSlot", "3",
                "-ValidateQaG5RoutingOnly");
            string[] cases = g5Route.RootElement.GetProperty("Cases")
                .EnumerateArray()
                .Select(item => item.GetString() ?? string.Empty)
                .ToArray();
            Assert(
                g5Route.RootElement.GetProperty("SaveSlotExplicit").GetBoolean() &&
                g5Route.RootElement.GetProperty("SaveSlot").GetInt32() == 3 &&
                cases.SequenceEqual(new[] { "ZoomProductNative" }, StringComparer.Ordinal),
                "Zoom ProductNative behavior must use one explicit third-save G5 route.");

            using JsonDocument ownerRoute = RunBatch4Routing(
                shell,
                "-StageQaHost",
                "-AutoExerciseZoomProductNative",
                "-AutoExerciseTitleButtonLifecycle",
                "-AssertAdvancedProductOwnerDeactivation",
                "-AdvancedProductOwnerDeactivationOwnerIds", "DTMAPI.ZoomMod",
                "-SaveSlot", "3",
                "-ValidateQaG4RoutingOnly");
            Assert(
                ownerRoute.RootElement.GetProperty("AdvancedProductOwnerDeactivationEnabled").GetBoolean() &&
                ownerRoute.RootElement.GetProperty("ContinuousHomePageTerminalEnabled").GetBoolean() &&
                ownerRoute.RootElement.GetProperty("ContinuousHomePageRequiresSaveLoaded").GetBoolean(),
                "Zoom exact-owner deactivation must run after the real ReturnedToTitle terminal.");

            string missingBehavior = RunBatch4RoutingFailure(
                shell,
                "-StageQaHost",
                "-AutoExerciseTitleButtonLifecycle",
                "-AssertAdvancedProductOwnerDeactivation",
                "-AdvancedProductOwnerDeactivationOwnerIds", "DTMAPI.ZoomMod",
                "-SaveSlot", "3",
                "-ValidateQaG4RoutingOnly");
            Assert(
                missingBehavior.Contains("requires the matching in-save behavior request", StringComparison.Ordinal),
                "Zoom owner cleanup must reject a route without ProductNative behavior evidence.");

            string repo = FindRepositoryRoot();
            string runnerSource = File.ReadAllText(Path.Combine(repo, "tools", "scripts", "run-game-smoke.ps1"));
            string behaviorFixture = File.ReadAllText(Path.Combine(
                repo,
                "src",
                "DTMAPI.GameBridge.DolocTown.QA",
                "Scenarios",
                "Fixtures",
                "ZoomProductNativeFixtureCase.cs"));
            string ownerFixture = File.ReadAllText(Path.Combine(
                repo,
                "src",
                "DTMAPI.GameBridge.DolocTown.QA",
                "Scenarios",
                "Fixtures",
                "AdvancedProductOwnerDeactivationFixture.cs"));
            Assert(
                !runnerSource.Contains("AutoExerciseZoomOwnerLifetime", StringComparison.Ordinal) &&
                !runnerSource.Contains("Smoke.ZoomOwnerLifetime", StringComparison.Ordinal) &&
                runnerSource.Contains("AutoExerciseZoomProductNative", StringComparison.Ordinal) &&
                behaviorFixture.Contains("titlePendingScale=4", StringComparison.Ordinal) &&
                behaviorFixture.Contains("DolocAPI.SetEnvCamera", StringComparison.Ordinal) &&
                behaviorFixture.Contains("\"DolocTown.CameraController\"", StringComparison.Ordinal) &&
                !behaviorFixture.Contains("\"CameraController\",", StringComparison.Ordinal) &&
                behaviorFixture.Contains("expectedOwnerPatchCount: 2", StringComparison.Ordinal) &&
                ownerFixture.Contains("ReturnedToTitle", StringComparison.Ordinal) &&
                ownerFixture.Contains("zoomBefore.ExactOwnerPatchCount != 3", StringComparison.Ordinal) &&
                ownerFixture.Contains("required two-target, three-patch", StringComparison.Ordinal) &&
                ownerFixture.Contains("Zoom=title4to1+native1+derived1+actual1+callback1->instance0+actual0+", StringComparison.Ordinal) &&
                ownerFixture.Contains("callback0+roots0", StringComparison.Ordinal),
                "Zoom acceptance must prove ProductNative 4x at the title boundary, real native reset reapply, 4x-to-1x title restore, and exact Loader cleanup without the retired Strict seam.");
        }

        private static JsonDocument RunBatch4RoutingCommand(string shell, string scriptArguments)
        {
            string runner = Path.Combine(FindRepositoryRoot(), "tools", "scripts", "run-game-smoke.ps1");
            string commandText = "& '" + runner.Replace("'", "''", StringComparison.Ordinal) + "' " + scriptArguments;
            WindowsPowerShellResult result = RunWindowsPowerShell(shell, new[]
            {
                "-NoLogo", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-Command", commandText
            });
            if (result.ExitCode != 0)
                throw new InvalidOperationException("Batch 4 Windows PowerShell command routing probe failed: " + result.Error + result.Output);
            return JsonDocument.Parse(result.Output);
        }

        private static JsonDocument RunBatch4Routing(string shell, params string[] arguments)
        {
            WindowsPowerShellResult result = RunBatch4Runner(shell, arguments);
            if (result.ExitCode != 0)
                throw new InvalidOperationException("Batch 4 Windows PowerShell routing probe failed: " + result.Error + result.Output);
            return JsonDocument.Parse(result.Output);
        }

        private static string RunBatch4RoutingFailure(string shell, params string[] arguments)
        {
            WindowsPowerShellResult result = RunBatch4Runner(shell, arguments);
            Assert(result.ExitCode != 0, "The Batch 4 Windows PowerShell routing probe unexpectedly succeeded: " + string.Join(" ", arguments));
            return result.Error + Environment.NewLine + result.Output;
        }

        private static WindowsPowerShellResult RunBatch4Runner(string shell, params string[] arguments)
        {
            string runner = Path.Combine(FindRepositoryRoot(), "tools", "scripts", "run-game-smoke.ps1");
            var command = new List<string>
            {
                "-NoLogo", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-File", runner
            };
            command.AddRange(arguments);
            return RunWindowsPowerShell(shell, command);
        }

        private static WindowsPowerShellResult RunWindowsPowerShell(string shell, IEnumerable<string> arguments)
        {
            var startInfo = new ProcessStartInfo
            {
                FileName = shell,
                UseShellExecute = false,
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                CreateNoWindow = true
            };
            foreach (string argument in arguments)
                startInfo.ArgumentList.Add(argument);

            using Process process = Process.Start(startInfo) ?? throw new InvalidOperationException("Could not start Windows PowerShell 5.1 for the Batch 4 routing matrix.");
            string output = process.StandardOutput.ReadToEnd();
            string error = process.StandardError.ReadToEnd();
            process.WaitForExit();
            return new WindowsPowerShellResult(process.ExitCode, output, error);
        }

        private static string GetWindowsPowerShell51Path()
        {
            string windows = Environment.GetFolderPath(Environment.SpecialFolder.Windows);
            string shell = Path.Combine(windows, "System32", "WindowsPowerShell", "v1.0", "powershell.exe");
            Assert(File.Exists(shell), "Windows PowerShell 5.1 is required for the Batch 4 runner routing matrix: " + shell);
            return shell;
        }

        private readonly struct WindowsPowerShellResult
        {
            internal WindowsPowerShellResult(int exitCode, string output, string error)
            {
                ExitCode = exitCode;
                Output = output;
                Error = error;
            }

            internal int ExitCode { get; }
            internal string Output { get; }
            internal string Error { get; }
        }

        private static void OilOfficialJsonOwnershipIsolatedAndProbabilityMatchesTrackedSemantics()
        {
            string repo = FindRepositoryRoot();
            string oilRoot = Path.Combine(repo, "products", "first-party", "Oil");
            string extensionPath = Path.Combine(oilRoot, "Content", "mod_tbmoditemspawnextension.json");
            string manifestPath = Path.Combine(oilRoot, "manifest.json");
            string officialInfoPath = Path.Combine(oilRoot, "official-info.json");
            string oilManifestVersion;

            using (JsonDocument manifestDocument = JsonDocument.Parse(File.ReadAllText(manifestPath)))
            {
                JsonElement manifest = manifestDocument.RootElement;
                oilManifestVersion = manifest.GetProperty("Version").GetString() ?? string.Empty;
                Assert(manifest.GetProperty("Type").GetString() == "ContentPack", "Oil must be an official JSON-only ContentPack.");
                Assert(!manifest.TryGetProperty("EntryDll", out _), "Oil ContentPack must not retain an EntryDll.");
                Assert(!manifest.TryGetProperty("MinimumDTMApiVersion", out _), "Oil official JSON must not claim a DTMAPI code contract.");
                Assert(!manifest.TryGetProperty("Dependencies", out _), "Oil official JSON must not retain code-layer dependencies.");
            }
            using (JsonDocument officialInfoDocument = JsonDocument.Parse(File.ReadAllText(officialInfoPath)))
            {
                string oilInfoVersion = officialInfoDocument.RootElement.GetProperty("version").GetString() ?? string.Empty;
                Assert(oilManifestVersion == "0.3.1-dtmapi" && oilInfoVersion == oilManifestVersion, "Oil's native info version must equal its current 0.3.1-dtmapi source manifest version; 1.0.0 remains only the blocked future target.");
            }

            Assert(!File.Exists(Path.Combine(oilRoot, "OilMod.csproj")) && !File.Exists(Path.Combine(oilRoot, "ModEntry.cs")), "Oil must not retain an empty CodeMod project or entry point.");
            Assert(!Directory.EnumerateFiles(oilRoot, "*.dll", SearchOption.AllDirectories).Any(), "Oil content-only source must not contain a DLL anywhere in its tree.");
            Assert(!Directory.EnumerateFiles(oilRoot, "*.cs", SearchOption.AllDirectories).Any() &&
                !Directory.EnumerateFiles(oilRoot, "*.csproj", SearchOption.AllDirectories).Any(),
                "Oil content-only source must not retain C# implementation or project files anywhere in its tree.");
            Assert(!File.ReadAllText(Path.Combine(repo, "DTMAPI.sln")).Contains("OilMod.csproj", StringComparison.Ordinal), "The solution must not retain the removed Oil DLL project.");
            Assert(!File.ReadAllText(Path.Combine(repo, "tools", "scripts", "build.ps1")).Contains("OilMod.csproj", StringComparison.Ordinal), "The canonical build must not expect an Oil DLL.");

            string installerSource = File.ReadAllText(Path.Combine(repo, "tools", "scripts", "install-to-game.ps1"));
            string releaseCommonSource = File.ReadAllText(Path.Combine(repo, "tools", "scripts", "release-common.ps1"));
            Assert(installerSource.Contains("must not contain DLL files anywhere under its source root", StringComparison.Ordinal) &&
                installerSource.Contains("nested Content manifests are forbidden", StringComparison.Ordinal) &&
                installerSource.Contains("staged unexpected DLL files", StringComparison.Ordinal) &&
                installerSource.Contains("must stage exactly one canonical Content/DTMAPI/manifest.json", StringComparison.Ordinal) &&
                releaseCommonSource.Contains("Assert-DtmApiManifestInfoVersionParity", StringComparison.Ordinal),
                "The content-only installer must fail closed on source/staged DLLs, nested or duplicate manifests, and explicit manifest/info version drift.");
            int contentCopyIndex = installerSource.IndexOf("Copy-DirectoryContents -Source (Split-Path -Parent $contentSource) -Destination $stagingPath -Include @('Content')", StringComparison.Ordinal);
            int canonicalManifestWriteIndex = installerSource.IndexOf("Write-JsonObject -Path $stagedManifestPath -Value $manifest", StringComparison.Ordinal);
            Assert(contentCopyIndex >= 0 && canonicalManifestWriteIndex > contentCopyIndex, "The installer must write the validated canonical manifest after copying source Content.");

            string catalogCheckerSource = File.ReadAllText(Path.Combine(repo, "tools", "scripts", "check-product-catalog.ps1"));
            Assert(catalogCheckerSource.Contains("Oil content-only recursive DLL count", StringComparison.Ordinal) &&
                catalogCheckerSource.Contains("Oil content-only CSharp/project file count", StringComparison.Ordinal) &&
                catalogCheckerSource.Contains("Oil nested Content manifest count", StringComparison.Ordinal) &&
                catalogCheckerSource.Contains("Oil publish-text current version projection", StringComparison.Ordinal) &&
                catalogCheckerSource.Contains("Oil native info current version projection", StringComparison.Ordinal),
                "Catalog validation must preserve Oil's recursively code-free, single-manifest source boundary and current version projection.");

            string gameSmokeSource = File.ReadAllText(Path.Combine(repo, "tools", "scripts", "run-game-smoke.ps1"));
            Assert(gameSmokeSource.Contains("One or more required profile/extra enabled IDs are missing from mod_infos.json; profile was not applied.", StringComparison.Ordinal) &&
                gameSmokeSource.Contains("@($officialModProfileSummary.DisabledIds) -contains 'Local.DTMAPI_Oil'", StringComparison.Ordinal) &&
                gameSmokeSource.Contains("official-mod-profile-gate.json", StringComparison.Ordinal) &&
                gameSmokeSource.Contains("-not $officialModProfileGateOk", StringComparison.Ordinal) &&
                gameSmokeSource.Contains("-IsolateAllOfficialMods requires an explicit non-Current OfficialModProfile.", StringComparison.Ordinal) &&
                gameSmokeSource.Contains("if ($property.Name -like 'Local.*' -or $property.Name -like 'Workshop.*')", StringComparison.Ordinal) &&
                gameSmokeSource.Contains("-IsolateAll ([bool]$IsolateAllOfficialMods)", StringComparison.Ordinal) &&
                gameSmokeSource.Contains("Official Mod smoke profile apply failed and its backup could not be restored", StringComparison.Ordinal) &&
                gameSmokeSource.Contains("Restore-SmokeOfficialModProfile -Summary $officialModProfileSummary -EvidencePath $evidence -Phase 'run-finally'", StringComparison.Ordinal),
                "Game smoke must fail closed when the requested official Mod profile is missing, incomplete, not fully isolated, Oil-on during Oil-off, or not restored.");

            using JsonDocument extensionDocument = JsonDocument.Parse(File.ReadAllText(extensionPath));
            JsonElement extensionRoot = extensionDocument.RootElement;
            Assert(extensionRoot.ValueKind == JsonValueKind.Array && extensionRoot.GetArrayLength() == 1, "Oil must publish exactly one official item-spawn extension row.");
            JsonElement extension = extensionRoot[0];
            Assert(extension.GetProperty("id").GetString() == "coal_mine_drop", "Oil must extend only the native coal_mine_drop LUT.");
            Assert(extension.EnumerateObject().Select(property => property.Name).OrderBy(name => name, StringComparer.Ordinal).SequenceEqual(new[] { "extra_items", "id" }, StringComparer.Ordinal), "Oil extension must not redeclare native coal/amber fields.");
            JsonElement extraItems = extension.GetProperty("extra_items");
            Assert(extraItems.ValueKind == JsonValueKind.Array && extraItems.GetArrayLength() == 1, "Oil must append exactly one item to coal_mine_drop.");
            JsonElement oil = extraItems[0];
            Assert(oil.GetProperty("item_name").GetString() == "crude_oil" &&
                oil.GetProperty("spawn_weight").GetInt32() == 25 &&
                oil.GetProperty("min_count").GetInt32() == 0 &&
                oil.GetProperty("max_count").GetInt32() == 0,
                "Oil extension must be crude_oil weight=25, min=0, max=0 (native unlimited).");
            Assert(oil.EnumerateObject().Select(property => property.Name).OrderBy(name => name, StringComparer.Ordinal).SequenceEqual(new[] { "item_name", "max_count", "min_count", "spawn_weight" }, StringComparer.Ordinal), "Oil extension must contain only the selected native spawn fields.");

            string fixturePath = Path.Combine(repo, "tests", "DTMAPI.UnitTests", "Fixtures", "oil-coal-drop-semantics.v1.json");
            string fixtureText = File.ReadAllText(fixturePath);
            foreach (string forbiddenPrivateToken in new[] { "spawn_datas", "level_datas", "drop_spawn_entry", "coal_mine_drop", "amber_ore", "ISpawnLut", "Tables.cs" })
                Assert(!fixtureText.Contains(forbiddenPrivateToken, StringComparison.Ordinal), "The tracked Oil semantic fixture must remain normalized and must not copy official schema, identifiers, or reverse-source names.");

            using JsonDocument fixtureDocument = JsonDocument.Parse(fixtureText);
            JsonElement fixtureRoot = fixtureDocument.RootElement;
            Assert(fixtureRoot.GetProperty("format").GetString() == "dtmapi.synthetic-ordered-draw-semantics/v1", "The Oil probability fixture format must remain explicit and versioned.");
            JsonElement orderedDraw = fixtureRoot.GetProperty("orderedDraw");
            JsonElement[] baseEntries = orderedDraw.GetProperty("baseEntries").EnumerateArray().ToArray();
            JsonElement appendedEntry = orderedDraw.GetProperty("appendedEntry");
            Assert(baseEntries.Length == 2 &&
                baseEntries[0].GetProperty("role").GetString() == "uncapped-base" &&
                baseEntries[0].GetProperty("operationCap").ValueKind == JsonValueKind.Null &&
                baseEntries[1].GetProperty("role").GetString() == "single-cap-base" &&
                baseEntries[1].GetProperty("operationCap").GetInt32() == 1 &&
                appendedEntry.GetProperty("role").GetString() == "target-extension" &&
                appendedEntry.GetProperty("operationCap").ValueKind == JsonValueKind.Null,
                "The synthetic Oil fixture must describe one uncapped base interval, one single-cap base interval, then one uncapped target extension.");

            int uncappedBaseWeight = baseEntries[0].GetProperty("weight").GetInt32();
            int cappedBaseWeight = baseEntries[1].GetProperty("weight").GetInt32();
            int targetWeight = appendedEntry.GetProperty("weight").GetInt32();
            Assert(uncappedBaseWeight > 0 && cappedBaseWeight > 0 && targetWeight == oil.GetProperty("spawn_weight").GetInt32(),
                "The synthetic fixture must retain positive base weights and project the tracked Oil extension weight into the target role.");

            JsonElement drawRange = orderedDraw.GetProperty("drawRange");
            int minimumDraws = drawRange.GetProperty("minimum").GetInt32();
            int maximumDraws = drawRange.GetProperty("maximum").GetInt32();
            int monotonicCheckMaximum = drawRange.GetProperty("monotonicCheckMaximum").GetInt32();
            JsonElement semantics = orderedDraw.GetProperty("semantics");
            Assert(minimumDraws == 3 && maximumDraws == 4 && monotonicCheckMaximum == 8 &&
                semantics.GetProperty("replacementAppendsAfterBaseEntries").GetBoolean() &&
                semantics.GetProperty("selectedCappedIntervalFallsThrough").GetBoolean(),
                "The synthetic Oil fixture must retain the reviewed 3-4 draw range, ordered append, and capped-interval fall-through semantics.");

            double totalWeight = uncappedBaseWeight + cappedBaseWeight + targetWeight;
            double ProbabilityAtLeastOneTarget(int draws)
            {
                double noTargetCapAvailable = 1d;
                double noTargetCapConsumed = 0d;
                for (int draw = 0; draw < draws; draw++)
                {
                    double nextNoTargetCapAvailable = noTargetCapAvailable * (uncappedBaseWeight / totalWeight);
                    double nextNoTargetCapConsumed = noTargetCapAvailable * (cappedBaseWeight / totalWeight) + noTargetCapConsumed * (uncappedBaseWeight / totalWeight);
                    noTargetCapAvailable = nextNoTargetCapAvailable;
                    noTargetCapConsumed = nextNoTargetCapConsumed;
                }
                return 1d - noTargetCapAvailable - noTargetCapConsumed;
            }

            JsonElement expectedProbability = fixtureRoot.GetProperty("expectedTargetProbability");
            double threeDraws = ProbabilityAtLeastOneTarget(minimumDraws);
            double fourDraws = ProbabilityAtLeastOneTarget(maximumDraws);
            Assert(Math.Abs(threeDraws - expectedProbability.GetProperty("minimumDraws").GetDouble()) < 0.000000000001d, "The normalized ordered-draw semantics should yield the exact three-draw Oil probability, including capped-interval fall-through.");
            Assert(Math.Abs(fourDraws - expectedProbability.GetProperty("maximumDraws").GetDouble()) < 0.000000000001d, "The normalized ordered-draw semantics should yield the exact four-draw Oil probability, including capped-interval fall-through.");
            Assert(Math.Abs(((threeDraws + fourDraws) / 2d) - expectedProbability.GetProperty("uniformRangeAverage").GetDouble()) < 0.000000000001d, "The unbuffed draw-range average must use the normalized ordered algorithm rather than an independent Bernoulli approximation.");
            double previousProbability = fourDraws;
            foreach (double probability in Enumerable.Range(maximumDraws + 1, monotonicCheckMaximum - maximumDraws).Select(ProbabilityAtLeastOneTarget))
            {
                Assert(probability > previousProbability && probability < 1d, "Collection-buffed 5-8 draw paths must retain strictly increasing normalized Oil opportunity.");
                previousProbability = probability;
            }

            Assembly bridgeAssembly = typeof(DolocTownGameBridge).Assembly;
            Assert(bridgeAssembly.GetType("DTMAPI.GameBridge.DolocTown.OilCoalDropFeature") == null &&
                bridgeAssembly.GetType("DTMAPI.GameBridge.DolocTown.OilCoalDropService") == null,
                "Oil-specific GameBridge feature/service types must be removed.");

            string bridgeRoot = Path.Combine(repo, "src", "DTMAPI.GameBridge.DolocTown");
            string nonFixtureBridgeSource = string.Join("\n", Directory.EnumerateFiles(bridgeRoot, "*.cs", SearchOption.AllDirectories)
                .Where(path => !path.Contains(Path.DirectorySeparatorChar + "Smoke" + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase) &&
                    !path.Contains(Path.DirectorySeparatorChar + "QaHost" + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase) &&
                    !path.Contains(Path.DirectorySeparatorChar + "bin" + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase) &&
                    !path.Contains(Path.DirectorySeparatorChar + "obj" + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase))
                .Select(File.ReadAllText));
            foreach (string forbidden in new[] { "OilCoalDrop", "crude_oil", "OilMod.MiningDrop", "Resources.OilCoalDrop", "rollOilDropFromCoal" })
                Assert(!nonFixtureBridgeSource.Contains(forbidden, StringComparison.OrdinalIgnoreCase), "Ordinary production GameBridge code outside the explicit Smoke/QA fixture seams must not retain Oil product token " + forbidden + ".");

            string toolHookSource = File.ReadAllText(Path.Combine(bridgeRoot, "Compatibility", "ActionCompletion", "ToolColliderHitHookBridge.cs"));
            string callbacksSource = File.ReadAllText(Path.Combine(bridgeRoot, "Hooking", "DolocTownHookCallbacks.cs"));
            Assert(toolHookSource.Contains("TryPatchPostfix", StringComparison.Ordinal) && !toolHookSource.Contains("TryPatchPrefix", StringComparison.Ordinal) && !toolHookSource.Contains("PrefixPatched", StringComparison.Ordinal), "Frozen ActionCompletion compatibility must remain Postfix-only on ToolCollider.");
            Assert(callbacksSource.Contains("ToolCollider.HandleTools.ActionCompletion", StringComparison.Ordinal) && !callbacksSource.Contains("ToolColliderHandleToolsPrefix", StringComparison.Ordinal) && !callbacksSource.Contains("OilCoalDrop", StringComparison.Ordinal), "Frozen ActionCompletion callback dispatch must remain isolated from retired Oil ownership.");

            foreach (string relativeManifest in new[]
            {
                Path.Combine("author-sdk", "samples", "api-demand", "AutoHarvest", "manifest.json"),
                Path.Combine("tests", "mod-fixtures", "qa", "CropHarvesting", "manifest.json")
            })
            {
                using JsonDocument dependencyDocument = JsonDocument.Parse(File.ReadAllText(Path.Combine(repo, relativeManifest)));
                JsonElement[] providers = dependencyDocument.RootElement.GetProperty("Dependencies").EnumerateArray()
                    .Where(dependency => dependency.GetProperty("UniqueID").GetString() == "DTMAPI.GameBridge.DolocTown")
                    .ToArray();
                Assert(providers.Length == 1 && providers[0].GetProperty("Required").GetBoolean() && providers[0].GetProperty("MinimumVersion").GetString() == "0.5.1-alpha", relativeManifest + " must declare exactly one required GameBridge provider dependency.");
            }
        }

        private static void FishingAutomationApiIsFeatureOwnedNotExperimentalBridgeOwned()
        {
            Assembly bridgeAssembly = typeof(DolocTownGameBridge).Assembly;
            Type experimentalBridgeType = bridgeAssembly.GetType("DTMAPI.GameBridge.DolocTown.DolocTownExperimentalBridgeApi")
                ?? throw new InvalidOperationException("DolocTownExperimentalBridgeApi type should exist.");
            Type serviceType = bridgeAssembly.GetType("DTMAPI.GameBridge.DolocTown.LegacyFishingAutomationService")
                ?? throw new InvalidOperationException("LegacyFishingAutomationService type should exist.");
            Type compatibilityType = bridgeAssembly.GetType("DTMAPI.GameBridge.DolocTown.FishingAutomationCompatibilityAdapter")
                ?? throw new InvalidOperationException("FishingAutomationCompatibilityAdapter type should exist.");
            Type featureType = bridgeAssembly.GetType("DTMAPI.GameBridge.DolocTown.FishingAutomationCompatibilityFeature")
                ?? throw new InvalidOperationException("FishingAutomationCompatibilityFeature type should exist.");

            Assert(!typeof(IFishingAutomationApi).IsAssignableFrom(experimentalBridgeType), "DolocTownExperimentalBridgeApi should no longer implement IFishingAutomationApi.");
            Assert(!typeof(IFishingAutomationApi).IsAssignableFrom(serviceType), "The native runtime service should no longer be the public fishing API owner.");
            Assert(typeof(IFishingAutomationApi).IsAssignableFrom(compatibilityType), "FishingAutomationCompatibilityAdapter should be the only feature-owned IFishingAutomationApi facade.");

            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                StageCompatibilityHostFixture(dir);
                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                object feature = Activator.CreateInstance(featureType, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic, null, new object[] { runtime }, null)
                    ?? throw new InvalidOperationException("FishingAutomationCompatibilityFeature should be constructable for unit tests.");
                string id = (string)(featureType.GetProperty("Id", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(feature) ?? string.Empty);
                object? service = featureType.GetProperty("Service", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(feature);
                Assert(id == "FishingAutomationCompatibility", "The frozen facade must publish an explicitly compatibility-only feature id.");
                Assert(service == null, "The compatibility feature should not create the executor before an IFishingAutomationApi consumer appears.");

                var bridgeManifest = new ManifestModel
                {
                    Name = "DTMAPI Doloc Town GameBridge",
                    Author = "DTMAPI",
                    Version = DtmApiRuntime.ApiVersion,
                    UniqueID = "DTMAPI.GameBridge.DolocTown",
                    Type = "RuntimeApi"
                };
                featureType.GetMethod("RegisterApis", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.Invoke(feature, new object[] { bridgeManifest });
                IFishingAutomationApi api = GetModRegistry(runtime).GetApi<IFishingAutomationApi>("DTMAPI.GameBridge.DolocTown")
                    ?? throw new InvalidOperationException("FishingAutomationCompatibilityFeature should register the facade API.");
                Assert(featureType.GetProperty("Service", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(feature) == null, "RegisterApis should keep FishingAutomation service inactive.");
                Assert(api.GetStatus("DTMAPI.Tests.AutoFishing").Status == "inactive/no-consumer", "Facade status should report inactive/no-consumer before Configure.");

                var owner = new ManifestModel
                {
                    Name = "AutoFishing Consumer",
                    Author = "DTMAPI",
                    Version = "1.0.0",
                    UniqueID = "DTMAPI.Tests.AutoFishing"
                };
                api.Configure(owner, new FishingAutomationOptions());
                service = featureType.GetProperty("Service", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(feature);
                Assert(service == null, "Configure should only store compatibility policy and must not activate the LegacyFishingAutomationService runtime or hooks.");
                Assert(api.GetStatus(owner.UniqueID).Status == "configured", "Configure should report a configured consumer before it is enabled.");
                api.SetEnabled(owner, true, "unit-test");
                service = featureType.GetProperty("Service", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(feature);
                Assert(service != null, "First SetEnabled(true) should activate the internal native runtime service behind the compatibility adapter.");
                object? callbackRuntime = featureType.GetProperty("CallbackRuntime", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(feature);
                Assert(callbackRuntime == null, "Pre-Initialize compatibility activation may retain owner state, but callback publication must remain fail-closed until the exact Harmony inventory is ready.");
                Assert(api.GetStatus(owner.UniqueID).Status == "active", "SetEnabled(true) should report active.");

                var competingOwner = new ManifestModel
                {
                    Name = "Competing Frozen Fishing Consumer",
                    Author = "DTMAPI",
                    Version = "1.0.0",
                    UniqueID = "DTMAPI.Tests.AutoFishing.Competing"
                };
                api.Configure(competingOwner, new FishingAutomationOptions());
                api.SetEnabled(competingOwner, true, "unit-test-busy");
                FishingAutomationState competingState = api.GetState(competingOwner.UniqueID);
                Assert(!competingState.Enabled && competingState.Phase == "Busy" && competingState.LastReason.Contains(owner.UniqueID, StringComparison.Ordinal),
                    "The frozen compatibility executor must reject a second enabled owner deterministically.");
                Assert(runtime.DemandCoordinator.GetOwnerDemandCount(owner.UniqueID) == 2 &&
                    runtime.DemandCoordinator.GetOwnerDemandCount(competingOwner.UniqueID) == 0,
                    "Only the owner whose enable request was accepted may retain the compatibility hook/updater demand roots.");
                api.SetEnabled(owner, false, "unit-test-disable");
                Assert(api.GetStatus(owner.UniqueID).Status == "disabled/consumer-present", "SetEnabled(false) should report a disabled consumer while retaining policy.");
                Assert(CompatibilityHostBroker.For(runtime).TryGetService("FishingAutomation", out object? residentBackend) && residentBackend != null &&
                    CompatibilityHostBroker.ReadProperty(residentBackend, "ConfiguredOwnerCount", -1) == 0 &&
                    CompatibilityHostBroker.ReadProperty(residentBackend, "OwnerStateCount", -1) == 0,
                    "Disabling the last enabled compatibility owner must clear owner policy/state from the process-resident Host backend before dropping the proxy.");
                Assert(featureType.GetProperty("Service", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(feature) == null &&
                    runtime.DemandCoordinator.GetOwnerDemandCount(owner.UniqueID) == 0 &&
                    runtime.DemandCoordinator.GetOwnerDemandCount(competingOwner.UniqueID) == 0,
                    "Disabling the accepted owner after a busy rejection must leave no stale compatibility demand or executor.");

                var retryOwner = new ManifestModel
                {
                    Name = "Compatibility Cleanup Retry",
                    Author = "DTMAPI",
                    Version = "1.0.0",
                    UniqueID = "DTMAPI.Tests.AutoFishing.CleanupRetry"
                };
                api.Configure(retryOwner, new FishingAutomationOptions());
                api.SetEnabled(retryOwner, true, "unit-test-cleanup-retry");
                Assert(residentBackend != null &&
                    CompatibilityHostBroker.ReadProperty(residentBackend, "ConfiguredOwnerCount", -1) == 1 &&
                    CompatibilityHostBroker.ReadProperty(residentBackend, "OwnerStateCount", -1) == 1,
                    "Reactivating the resident Host for a new owner must rebuild only that owner and must not expose earlier owner state.");
                var failingHarmony = new FakeHarmonyUnpatcher { ThrowOnUnpatch = true };
                var failingPatcher = new HarmonyReflectionPatcher(runtime, "dtmapi.gamebridge.doloctown.fishing.compatibility");
                SetPrivateField(failingPatcher, "harmony", failingHarmony);
                SetPrivateField(failingPatcher, "harmonyType", typeof(FakeHarmonyUnpatcher));
                SetPrivateField(feature, "patcher", failingPatcher);
                bool cleanupFailed = false;
                try
                {
                    api.SetEnabled(retryOwner, false, "unit-test-unpatch-failure");
                }
                catch (InvalidOperationException ex)
                {
                    cleanupFailed = ex.Message.Contains("cleanup failed", StringComparison.OrdinalIgnoreCase);
                }
                Assert(cleanupFailed &&
                    featureType.GetProperty("Service", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(feature) != null &&
                    runtime.DemandCoordinator.GetOwnerDemandCount(retryOwner.UniqueID) == 0,
                    "An exact-owner Harmony unpatch failure must propagate and retain a retryable compatibility cleanup tombstone without retaining logical demand.");
                failingHarmony.ThrowOnUnpatch = false;
                api.SetEnabled(retryOwner, false, "unit-test-unpatch-retry");
                Assert(featureType.GetProperty("Service", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(feature) == null &&
                    runtime.DemandCoordinator.GetOwnerDemandCount(retryOwner.UniqueID) == 0 && failingHarmony.UnpatchCalls == 2 &&
                    residentBackend != null && CompatibilityHostBroker.ReadProperty(residentBackend, "ConfiguredOwnerCount", -1) == 0 &&
                    CompatibilityHostBroker.ReadProperty(residentBackend, "OwnerStateCount", -1) == 0,
                    "The next compatibility cleanup pass must retry the same exact Harmony owner and release the tombstone only after success.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void FrozenCompatibilityApisPublishSeparateStabilityDispositionAndWarnings()
        {
            Type[] frozenTypes =
            {
                typeof(IActionCompletionApi),
                typeof(ActionCompletionOptions),
                typeof(IFishingAutomationApi),
                typeof(FishingBiteWaitMode),
                typeof(FishingResultMode),
                typeof(FishingAnimationMode),
                typeof(FishingAutomationOptions),
                typeof(FishingAutomationState),
                typeof(IActionSpeedApi),
                typeof(ActionSpeedOptions),
                typeof(IItemTooltipApi),
                typeof(FishRoeTooltipOptions),
                typeof(FishRoeDisplayInfo),
                typeof(IAnimalViewerApi),
                typeof(AnimalHusbandryProgressOptions),
                typeof(IMachineProductionApi),
                typeof(MachineDefinition),
                typeof(MachineRecipeInput),
                typeof(MachineOutputRule),
                typeof(MachineRegisterResult),
                typeof(MachineProductionState),
                typeof(IEquipmentSlotsApi),
                typeof(EquipmentSlotsOptions),
                typeof(EquipmentSlotsRegisterResult),
                typeof(EquipmentSlotsState),
                typeof(EquipmentSlotInfo),
                typeof(EquipmentSlotEquipResult),
                typeof(EquipmentSlotsRecoveryResult),
                typeof(ISaveSlotsApi),
                typeof(SaveSlotsOptions),
                typeof(SaveSlotsRegisterResult),
                typeof(SaveSlotsState),
                typeof(ICameraViewApi),
                typeof(ICameraViewLease),
                typeof(CameraViewRequest),
                typeof(CameraViewResult),
                typeof(CameraViewState),
                typeof(ICameraZoomApi),
                typeof(CameraZoomOptions),
                typeof(CameraZoomRegisterResult),
                typeof(CameraZoomResult),
                typeof(CameraZoomState),
                typeof(IChestLocatorEnhancerApi),
                typeof(ChestLocatorEnhancerOptions),
                typeof(ChestLocatorEnhancerRegisterResult),
                typeof(ChestLocatorEnhancerState)
            };

            foreach (Type type in frozenTypes)
            {
                DtmApiStatusAttribute stability = type.GetCustomAttribute<DtmApiStatusAttribute>()
                    ?? throw new InvalidOperationException(type.Name + " must publish stability metadata independently of disposition.");
                Assert(stability.Status == DtmApiStatus.Experimental,
                    type.Name + " must remain Experimental while its compatibility disposition is frozen.");

                DtmApiDispositionAttribute disposition = type.GetCustomAttribute<DtmApiDispositionAttribute>()
                    ?? throw new InvalidOperationException(type.Name + " must publish a frozen disposition.");
                Assert(disposition.Disposition == DtmApiDisposition.Frozen && disposition.Since == "0.5.5",
                    type.Name + " must publish the 0.5.5 Frozen disposition without changing its stability level.");

                ObsoleteAttribute obsolete = type.GetCustomAttribute<ObsoleteAttribute>()
                    ?? throw new InvalidOperationException(type.Name + " must carry a source warning while its ABI is retained.");
                Assert(!obsolete.IsError && (obsolete.Message ?? string.Empty).Contains("frozen", StringComparison.OrdinalIgnoreCase),
                    type.Name + " must use Obsolete(..., false) with an explicit frozen warning.");
            }

            Assert(typeof(IItemDisplayNameApi).GetCustomAttribute<DtmApiDispositionAttribute>() == null,
                "An API without disposition metadata must retain the documented Open default instead of receiving an unrelated frozen classification.");
        }

        private static void CustomEntityApisAreExperimentalFrozenAndCoreOwned()
        {
            Type[] apiTypes =
            {
                typeof(ICustomAnimalApi),
                typeof(ICustomMonsterApi),
                typeof(ICustomAttackApi),
                typeof(ICustomDroneApi)
            };
            foreach (Type apiType in apiTypes)
            {
                DtmApiStatusAttribute stability = apiType.GetCustomAttribute<DtmApiStatusAttribute>()
                    ?? throw new InvalidOperationException(apiType.Name + " must publish explicit stability metadata.");
                DtmApiDispositionAttribute disposition = apiType.GetCustomAttribute<DtmApiDispositionAttribute>()
                    ?? throw new InvalidOperationException(apiType.Name + " must publish explicit disposition metadata.");
                ObsoleteAttribute warning = apiType.GetCustomAttribute<ObsoleteAttribute>()
                    ?? throw new InvalidOperationException(apiType.Name + " must warn new source consumers while retaining its ABI.");
                Assert(stability.Status == DtmApiStatus.Experimental,
                    apiType.Name + " must be Experimental because its native runtime verbs remain blocked.");
                Assert(disposition.Disposition == DtmApiDisposition.Frozen && disposition.Since == "0.5.5",
                    apiType.Name + " must be Frozen for adoption while retaining its existing binary identity.");
                Assert(!warning.IsError && (warning.Message ?? string.Empty).Contains("frozen", StringComparison.OrdinalIgnoreCase),
                    apiType.Name + " must use a non-error frozen source warning.");
            }

            string? previousRoot = UseTempPersistentRoot();
            try
            {
                var runtime = new DtmApiRuntime(new FakeHost(NewTempGameDir()), new ConfigMenuRegistry());
                runtime.Start();
                _ = new DolocTownGameBridge(runtime);
                Assert(runtime.ModRegistry.GetApi<ICustomAnimalApi>("DTMAPI") != null &&
                    runtime.ModRegistry.GetApi<ICustomMonsterApi>("DTMAPI") != null &&
                    runtime.ModRegistry.GetApi<ICustomAttackApi>("DTMAPI") != null &&
                    runtime.ModRegistry.GetApi<ICustomDroneApi>("DTMAPI") != null,
                    "The frozen registry ABI must remain available from its DTMAPI Core provider.");
                Assert(runtime.ModRegistry.GetApi<ICustomAnimalApi>("DTMAPI.GameBridge.DolocTown") == null &&
                    runtime.ModRegistry.GetApi<ICustomMonsterApi>("DTMAPI.GameBridge.DolocTown") == null &&
                    runtime.ModRegistry.GetApi<ICustomAttackApi>("DTMAPI.GameBridge.DolocTown") == null &&
                    runtime.ModRegistry.GetApi<ICustomDroneApi>("DTMAPI.GameBridge.DolocTown") == null,
                    "GameBridge must not advertise a second CustomEntity provider identity for the same Core registry instance.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void LegacyFishingCompatibilityIsObsoleteFrozenAndHasNoProductConsumers()
        {
            ObsoleteAttribute apiObsolete = typeof(IFishingAutomationApi).GetCustomAttribute<ObsoleteAttribute>()
                ?? throw new InvalidOperationException("IFishingAutomationApi should carry an Obsolete warning.");
            Assert(!apiObsolete.IsError && (apiObsolete.Message ?? string.Empty).Contains("deprecated and frozen", StringComparison.OrdinalIgnoreCase), "The legacy fishing API warning should be non-breaking and explicitly frozen.");
            DtmApiStatusAttribute status = typeof(IFishingAutomationApi).GetCustomAttribute<DtmApiStatusAttribute>()
                ?? throw new InvalidOperationException("IFishingAutomationApi should retain its Experimental status metadata.");
            Assert(status.Status == DtmApiStatus.Experimental && (status.Notes ?? string.Empty).Contains("Deprecated/Frozen", StringComparison.Ordinal), "The legacy fishing API must remain Experimental while documentation marks it Deprecated/Frozen.");
            foreach (Type type in new[] { typeof(FishingBiteWaitMode), typeof(FishingResultMode), typeof(FishingAnimationMode), typeof(FishingAutomationOptions), typeof(FishingAutomationState) })
                Assert(type.GetCustomAttribute<ObsoleteAttribute>()?.IsError == false, type.Name + " should carry the same non-error compatibility warning.");

            string? previousRoot = UseTempPersistentRoot();
            try
            {
                var host = new FakeHost(NewTempGameDir());
                var runtime = new DtmApiRuntime(host, new ConfigMenuRegistry());
                runtime.Start();
                _ = new DolocTownGameBridge(runtime);
                IFishingAutomationApi api = runtime.ModRegistry.GetApi<IFishingAutomationApi>("DTMAPI.GameBridge.DolocTown")!;
                var owner = new ManifestModel { Name = "FrozenLegacy", Author = "DTMAPI", Version = "1.0.0", UniqueID = "DTMAPI.Tests.FrozenLegacy", Type = "CodeMod" };
                api.Configure(owner, new FishingAutomationOptions());
                api.Configure(owner, new FishingAutomationOptions());
                api.SetEnabled(owner, false, "warning-once");
                string warning = host.Warnings.Single(message => message.Contains("deprecated IFishingAutomationApi", StringComparison.Ordinal));
                Assert(host.Warnings.Count(message => message.Contains("deprecated IFishingAutomationApi", StringComparison.Ordinal)) == 1, "The compatibility facade should warn once per owner instead of logging every call.");
                Assert(warning.Contains("frozen to new consumers", StringComparison.Ordinal) &&
                    warning.Contains("existing binary compatibility is retained until a separately approved breaking change", StringComparison.Ordinal) &&
                    warning.Contains("does not replace or reopen this public API", StringComparison.Ordinal),
                    "The runtime warning must preserve the frozen no-new-consumer and separately-approved-breaking-change boundary.");
                Assert(!warning.Contains("0.5.5", StringComparison.Ordinal) && !warning.Contains("0.6.0", StringComparison.Ordinal),
                    "The frozen compatibility warning must not promise a fixed removal or migration release.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }

            string repo = FindRepositoryRoot();
            var violations = new List<string>();
            foreach (string directoryName in new[] { "src", "products", "first-party-mods", Path.Combine("author-sdk", "samples", "api-demand") })
            {
                string directory = Path.Combine(repo, directoryName);
                if (!Directory.Exists(directory))
                    continue;
                foreach (string file in Directory.EnumerateFiles(directory, "*.cs", SearchOption.AllDirectories))
                {
                    string normalized = file.Replace('\\', '/');
                    if (normalized.Contains("/bin/", StringComparison.OrdinalIgnoreCase) || normalized.Contains("/obj/", StringComparison.OrdinalIgnoreCase) ||
                        normalized.EndsWith("/src/DTMAPI.Abstractions/ExperimentalGameBridge.cs", StringComparison.OrdinalIgnoreCase) ||
                        normalized.Contains("/src/DTMAPI.InstallDoctor/", StringComparison.OrdinalIgnoreCase) ||
                        normalized.Contains("/Compatibility/FishingAutomation/", StringComparison.OrdinalIgnoreCase) ||
                        normalized.EndsWith("/products/first-party/AutoFishing/qa/batch6/Batch6AutoFishingCompatibilityDriver.cs", StringComparison.OrdinalIgnoreCase) ||
                        normalized.EndsWith("/DTMAPI.GameBridge.DolocTown.QA/Scenarios/Fixtures/LegacyFishingAutomationCompatibilityFixtureCase.cs", StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }
                    if (File.ReadAllText(file).Contains("IFishingAutomationApi", StringComparison.Ordinal))
                        violations.Add(Path.GetRelativePath(repo, file));
                }
            }
            Assert(violations.Count == 0, "No product may consume frozen IFishingAutomationApi; unexpected consumers=" + string.Join(",", violations) + ".");
        }

        private static void AutoFishingArchitectureBoundariesRemainIsolated()
        {
            string repo = FindRepositoryRoot();
            string productDirectory = Path.Combine(repo, "products", "first-party", "AutoFishing", "src");
            string productSource = string.Join("\n", Directory.EnumerateFiles(productDirectory, "*.cs", SearchOption.AllDirectories)
                .Select(File.ReadAllText));

            foreach (string required in new[]
            {
                "using HarmonyLib;",
                "System.Reflection",
                "AgentStateFishingReady",
                "FishingGameScrollBar",
                "AgentStateBase",
                "dtmapi.mod.yuuka.dtmapi.autofishing",
                "ExpectedPatchCount = 22",
                "SetUpdateSubscription(false)"
            })
            {
                Assert(productSource.Contains(required, StringComparison.Ordinal), "The admitted Advanced AutoFishing product must own native/lifecycle token " + required + ".");
            }
            foreach (string forbidden in new[]
            {
                "IFishingAutomationApi",
                "IFirstPartyFishing",
                "DTMAPI.GameBridge.DolocTown",
                "GetApi<IFirstPartyFishing",
                "GameBridgeDemandRoutes"
            })
            {
                Assert(!productSource.Contains(forbidden, StringComparison.Ordinal), "The self-contained AutoFishing product must not consume deleted/compatibility token " + forbidden + ".");
            }
            Assert(CountTextOccurrences(productSource, "RegisterKeybind(") == 1, "AutoFishing should retain exactly one owner-bound Gameplay toggle registration.");
            Assert(CountTextOccurrences(productSource, "GameLoop.UpdateTicked += OnUpdateTicked") == 1 &&
                CountTextOccurrences(productSource, "GameLoop.UpdateTicked -= OnUpdateTicked") == 1 &&
                productSource.Contains("SetAutomation(false, \"update session unavailable\")", StringComparison.Ordinal) &&
                productSource.Contains("SetAutomation(false, \"SaveLoaded session unavailable\")", StringComparison.Ordinal),
                "AutoFishing's updater must remain session-scoped and fail closed on session reacquisition failure.");
            string modEntrySource = File.ReadAllText(Path.Combine(productDirectory, "ModEntry.cs"));
            int disposeStart = modEntrySource.IndexOf("public void Dispose()", StringComparison.Ordinal);
            int disposeEnd = modEntrySource.IndexOf("private static void TryCleanup", disposeStart, StringComparison.Ordinal);
            Assert(modEntrySource.Contains("public sealed class ModEntry : DtmMod, IDisposable", StringComparison.Ordinal) &&
                disposeStart >= 0 && disposeEnd > disposeStart,
                "The Advanced product must expose one standard optional owner-deactivation callback without expanding DTMAPI.Abstractions.");
            string disposeSource = modEntrySource.Substring(disposeStart, disposeEnd - disposeStart);
            Assert(disposeSource.Contains("enabled = false;", StringComparison.Ordinal) &&
                disposeSource.Contains("updateSubscribed = false;", StringComparison.Ordinal) &&
                disposeSource.Contains("ResetPrimitiveLifecycleBoundary(\"OwnerDeactivation\")", StringComparison.Ordinal) &&
                disposeSource.Contains("toggleRegistration?.Dispose();", StringComparison.Ordinal) &&
                disposeSource.Contains("nativeRuntime.DeactivateOwner(\"OwnerDeactivation\")", StringComparison.Ordinal) &&
                !disposeSource.Contains("SetUpdateSubscription", StringComparison.Ordinal) &&
                !disposeSource.Contains("DetachProductHandlers", StringComparison.Ordinal),
                "Manager deactivation must restore product-private state directly while Core owns removal of guarded event proxies.");
            int refreshNativeState = modEntrySource.IndexOf("primitives.RefreshNativeState();", StringComparison.Ordinal);
            int updateSnapshot = modEntrySource.IndexOf("FishingPrimitiveSnapshot snapshot = session!.GetSnapshot();", StringComparison.Ordinal);
            Assert(refreshNativeState >= 0 && updateSnapshot > refreshNativeState,
                "AutoFishing must refresh the native frame before the F6 updater consumes its session snapshot.");
            Assert(modEntrySource.Contains("ResetPrimitiveLifecycleBoundary(\"SaveLoaded\")", StringComparison.Ordinal) &&
                modEntrySource.Contains("ResetPrimitiveLifecycleBoundary(\"ReturnedToTitle\")", StringComparison.Ordinal) &&
                modEntrySource.Contains("primitives.ResetForLifecycleBoundary", StringComparison.Ordinal) &&
                modEntrySource.Contains("primitives.InvalidateEnvironment(\"automation-enable:", StringComparison.Ordinal) &&
                modEntrySource.Contains("primitives.InvalidateEnvironment(\"automation-disable:", StringComparison.Ordinal),
                "AutoFishing SaveLoaded, title return, and F6 re-entry boundaries must invalidate scene-sensitive native caches.");
            string productHookSource = File.ReadAllText(Path.Combine(productDirectory, "Native", "FishingProductHookInstaller.cs"));
            Assert(productHookSource.Contains("CompatibilityHarmonyOwner = \"dtmapi.gamebridge.doloctown.fishingcompatibility\"", StringComparison.Ordinal) &&
                productHookSource.Contains("ThrowIfCompatibilityOwnerIsPresent(resolved)", StringComparison.Ordinal) &&
                productHookSource.Contains("Harmony.GetPatchInfo(patch.Target)", StringComparison.Ordinal),
                "The product owner must fail closed before patching when the frozen compatibility owner is already present.");
            string nativeRuntimeSource = File.ReadAllText(Path.Combine(productDirectory, "Native", "AutoFishingNativeRuntime.cs"));
            int nativeDeactivate = nativeRuntimeSource.IndexOf("internal void DeactivateOwner(string reason)", StringComparison.Ordinal);
            int callbackDetach = nativeRuntimeSource.IndexOf("FishingProductCallbacks.Detach(this);", nativeDeactivate, StringComparison.Ordinal);
            int primitiveRollback = nativeRuntimeSource.IndexOf("RollbackPrimitiveActivation(primitiveHookRuntime", nativeDeactivate, StringComparison.Ordinal);
            int exactUnpatch = nativeRuntimeSource.IndexOf("hookInstaller.UnpatchOwnedHooks();", nativeDeactivate, StringComparison.Ordinal);
            Assert(nativeDeactivate >= 0 && callbackDetach > nativeDeactivate && primitiveRollback > callbackDetach && exactUnpatch > primitiveRollback,
                "Owner deactivation must sever the static callback root before native rollback and still attempt exact-owner Harmony cleanup afterward.");

            string abstractionsDirectory = Path.Combine(repo, "src", "DTMAPI.Abstractions");
            Assert(!File.Exists(Path.Combine(abstractionsDirectory, "FirstPartyFishingPrimitives.cs")), "The single-consumer first-party fishing seam must be deleted.");
            string abstractionsAssemblyInfo = File.ReadAllText(Path.Combine(abstractionsDirectory, "AssemblyInfo.cs"));
            Assert(!abstractionsAssemblyInfo.Contains("InternalsVisibleTo(\"AutoFishingMod\")", StringComparison.Ordinal), "AutoFishing must not retain an Abstractions friend opening.");

            string bridgeDirectory = Path.Combine(repo, "src", "DTMAPI.GameBridge.DolocTown");
            string bridgeSource = string.Join("\n", Directory.EnumerateFiles(bridgeDirectory, "*.cs", SearchOption.AllDirectories)
                .Select(File.ReadAllText));
            foreach (string forbidden in new[]
            {
                "IFirstPartyFishing",
                "FishingPrimitivesService",
                "FishingPrimitiveHookRuntime",
                "SetPrimitiveDemand",
                "AttachPrimitives",
                "FishingBaseExitOwned",
                "fishing-base-exit"
            })
            {
                Assert(!bridgeSource.Contains(forbidden, StringComparison.Ordinal), "Mandatory GameBridge must not retain moved ProductNative seam " + forbidden + ".");
            }

            string compatibilityDirectory = Path.Combine(bridgeDirectory, "Compatibility", "FishingAutomation");
            string compatibilitySource = string.Join("\n", Directory.EnumerateFiles(compatibilityDirectory, "*.cs", SearchOption.AllDirectories)
                .Select(File.ReadAllText));
            string demandSource = File.ReadAllText(Path.Combine(bridgeDirectory, "Demand", "GameBridgeDemandRoutes.cs"));
            Assert(compatibilitySource.Contains("class FishingAutomationCompatibilityFeature", StringComparison.Ordinal) &&
                compatibilitySource.Contains("IFishingCompatibilityHookRuntime", StringComparison.Ordinal) &&
                demandSource.Contains("FishingAutomation.Compatibility", StringComparison.Ordinal) &&
                compatibilitySource.Contains("FishingCompatibilityBaseExitPostfix", StringComparison.Ordinal),
                "The frozen IFishingAutomationApi executor must use compatibility-named construction, callback, demand, and BaseExit roots.");
            string compatibilityHookSource = File.ReadAllText(Path.Combine(compatibilityDirectory, "FishingCompatibilityHookBridge.cs"));
            string compatibilityFeatureSource = File.ReadAllText(Path.Combine(compatibilityDirectory, "FishingAutomationCompatibilityFeature.cs"));
            int compatibilityFailClosed = compatibilityHookSource.IndexOf("private void FailClosed", StringComparison.Ordinal);
            int compatibilityOwnerRollback = compatibilityHookSource.IndexOf("patcher.TryUnpatchAllOwnedPatches()", compatibilityFailClosed, StringComparison.Ordinal);
            int compatibilityStatusReset = compatibilityHookSource.IndexOf("ResetPatchStatuses();", compatibilityOwnerRollback, StringComparison.Ordinal);
            Assert(compatibilityHookSource.Contains("HarmonyOwner = \"dtmapi.gamebridge.doloctown.fishingcompatibility\"", StringComparison.Ordinal) &&
                compatibilityHookSource.Contains("ManagedProductUniqueId = \"Yuuka.DTMAPI.AutoFishing\"", StringComparison.Ordinal) &&
                compatibilityHookSource.Contains("ManagedModClassifier.GetExpectedHarmonyOwner(ManagedProductUniqueId)", StringComparison.Ordinal) &&
                compatibilityHookSource.Contains("TryFindManagedModOwnerOnInventory(patcher", StringComparison.Ordinal) &&
                compatibilityHookSource.Contains("patch.Targets(target)", StringComparison.Ordinal) &&
                compatibilityHookSource.Contains("patch.Owner.Equals(ManagedProductHarmonyOwner, StringComparison.Ordinal)", StringComparison.Ordinal) &&
                !compatibilityHookSource.Contains("StartsWith(ManagedModHarmonyOwnerPrefix", StringComparison.Ordinal) &&
                compatibilityFailClosed >= 0 && compatibilityOwnerRollback > compatibilityFailClosed && compatibilityStatusReset > compatibilityOwnerRollback &&
                compatibilityFeatureSource.Contains("CallbackRuntime => HooksReady &&", StringComparison.Ordinal) &&
                compatibilityFeatureSource.Contains("UninstallHooks(patcher, reason)", StringComparison.Ordinal) &&
                compatibilityFeatureSource.Contains("SetCompatibilityDemand(owner.UniqueID, active: false, \"compatibility activation rejected", StringComparison.Ordinal) &&
                compatibilityFeatureSource.Contains("if (patcher == null)", StringComparison.Ordinal) &&
                compatibilityFeatureSource.Contains("service.SetFishingHooksInstalled(false);", StringComparison.Ordinal) &&
                compatibilityFeatureSource.Contains("if (hookBridge?.HooksReady != true)", StringComparison.Ordinal) &&
                compatibilityFeatureSource.Contains("service = null;", StringComparison.Ordinal) &&
                compatibilityFeatureSource.Contains("return null;", StringComparison.Ordinal),
                "Frozen fishing compatibility must defer callback publication before patcher binding, then use a private owner, roll back an incomplete 22-patch inventory atomically, disable the whole service/demand after rejection, reject the exact AutoFishing product owner, and preserve cross-domain shared-target owners.");
            string legacyService = File.ReadAllText(Path.Combine(compatibilityDirectory, "LegacyFishingAutomationService.cs"));
            foreach (string forbidden in new[] { "AttachPrimitives", "FishingPrimitivesService", "primitiveDiagnosticState", "primitives?." })
                Assert(!legacyService.Contains(forbidden, StringComparison.Ordinal), "The frozen compatibility executor must not attach the new product through " + forbidden + ".");

            string callbacks = File.ReadAllText(Path.Combine(bridgeDirectory, "Hooking", "DolocTownHookCallbacks.cs"));
            int sharedBaseExitStart = callbacks.IndexOf("public static void AgentStateBaseExitPostfix()", StringComparison.Ordinal);
            int compatibilityBaseExitStart = callbacks.IndexOf("public static void FishingCompatibilityBaseExitPostfix()", StringComparison.Ordinal);
            Assert(sharedBaseExitStart >= 0 && compatibilityBaseExitStart > sharedBaseExitStart, "Shared and compatibility BaseExit callbacks should remain independently named.");
            string sharedBaseExit = callbacks.Substring(sharedBaseExitStart, compatibilityBaseExitStart - sharedBaseExitStart);
            Assert(!sharedBaseExit.Contains("Fishing", StringComparison.Ordinal), "The shared AgentStateBase exit callback must retain only ActionSpeed ownership.");

            string coreDirectory = Path.Combine(repo, "src", "DTMAPI.Core");
            string[] coreFiles = Directory.EnumerateFiles(coreDirectory, "*.cs", SearchOption.AllDirectories).ToArray();
            string advancedAdmissionAuthorityPath = Path.Combine(coreDirectory, "Manifesting", "ManagedModClassification.cs");
            string coreWithoutAdmissionAuthority = string.Join("\n", coreFiles
                .Where(path => !path.Equals(advancedAdmissionAuthorityPath, StringComparison.OrdinalIgnoreCase))
                .Select(File.ReadAllText));
            Assert(!coreWithoutAdmissionAuthority.Contains("AutoFishing", StringComparison.Ordinal) &&
                !coreWithoutAdmissionAuthority.Contains("FishingPrimitive", StringComparison.Ordinal),
                "Core may name AutoFishing only in its exact Advanced policy/identity authority and must own no fishing implementation.");
            string advancedAdmissionAuthority = File.ReadAllText(advancedAdmissionAuthorityPath);
            string coreProjectSource = File.ReadAllText(Path.Combine(coreDirectory, "DTMAPI.Core.csproj"));
            string advancedPolicyRegistry = File.ReadAllText(Path.Combine(repo, "author-sdk", "advanced-reference-policies", "registry.json"));
            Assert(advancedAdmissionAuthority.Contains("AdvancedReferencePolicyRegistry.json", StringComparison.Ordinal) &&
                advancedAdmissionAuthority.Contains("PolicyResourcePrefix", StringComparison.Ordinal) &&
                coreProjectSource.Contains("advanced-reference-policies\\registry.json", StringComparison.Ordinal) &&
                coreProjectSource.Contains("advanced-reference-policies\\*.json", StringComparison.Ordinal) &&
                advancedPolicyRegistry.Contains("doloctown-24456188-autofishing-v1", StringComparison.Ordinal) &&
                advancedPolicyRegistry.Contains("Yuuka.DTMAPI.AutoFishing", StringComparison.Ordinal),
                "Core admission authority must embed the registry-driven exact AutoFishing policy/UniqueID binding.");

            string unitProject = File.ReadAllText(Path.Combine(repo, "tests", "DTMAPI.UnitTests", "DTMAPI.UnitTests.csproj"));
            Assert(!unitProject.Contains("first-party-mods\\AutoFishingMod\\AutoFishingMod.csproj", StringComparison.OrdinalIgnoreCase),
                "Unit tests must not restore the raw legacy AutoFishing project as a production build authority.");
        }

        private static void ZoomProductArchitectureBoundariesRemainOrdinary()
        {
            string repo = FindRepositoryRoot();
            string productDirectory = Path.Combine(repo, "products", "first-party", "Zoom");
            Assert(Directory.Exists(productDirectory), "Zoom must live under the admitted Advanced product source root.");
            foreach (string retiredRoot in new[]
            {
                Path.Combine(repo, "first-party-mods", "ZoomMod"),
                Path.Combine(repo, "testmods", "ZoomMod")
            })
            {
                Assert(!File.Exists(Path.Combine(retiredRoot, "ZoomMod.csproj")) &&
                    !File.Exists(Path.Combine(retiredRoot, "ModEntry.cs")) &&
                    !File.Exists(Path.Combine(retiredRoot, "manifest.json")),
                    "Deleted Strict/test Zoom source must not remain as a competing production authority; ignored build artifacts alone are not source authority.");
            }

            string project = File.ReadAllText(Path.Combine(productDirectory, "DTMAPI.Zoom.csproj"));
            Assert(project.Contains("<AssemblyName>DTMAPI.Zoom</AssemblyName>", StringComparison.Ordinal) &&
                project.Contains("DTMAPI_AUTHOR_SDK_ROOT", StringComparison.Ordinal) &&
                project.Contains("DTMAPI.Author.props", StringComparison.Ordinal) &&
                !project.Contains("<ProjectReference", StringComparison.Ordinal),
                "Zoom must use the Advanced Author SDK instead of a hand-authored project-reference lane.");
            string productSource = string.Join("\n", Directory.EnumerateFiles(productDirectory, "*.cs", SearchOption.AllDirectories)
                .Where(path => !path.Contains(Path.DirectorySeparatorChar + "bin" + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase) &&
                    !path.Contains(Path.DirectorySeparatorChar + "obj" + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase))
                .Select(File.ReadAllText));
            Assert(productSource.Contains("new Harmony(", StringComparison.Ordinal) &&
                productSource.Contains("dtmapi.mod.dtmapi.zoommod", StringComparison.Ordinal) &&
                productSource.Contains("SetEnvCamera(Vector2,Vector2,bool,bool,bool)", StringComparison.Ordinal) &&
                productSource.Contains("parameters[0].ParameterType.FullName ==", StringComparison.Ordinal) &&
                !productSource.Contains("ICameraViewApi", StringComparison.Ordinal) &&
                !productSource.Contains("ICameraZoomApi", StringComparison.Ordinal),
                "Advanced Zoom must own its exact ProductNative Hook and must not consume its frozen compatibility API.");
            Assert(productSource.Contains("public sealed class ModEntry : DtmMod, IDisposable", StringComparison.Ordinal) &&
                productSource.Contains("runtime.DeactivateOwner(", StringComparison.Ordinal) &&
                productSource.Contains("helper.Events.Save.SaveLoaded -=", StringComparison.Ordinal) &&
                productSource.Contains("OnSaveLoaded;", StringComparison.Ordinal) &&
                productSource.Contains("helper.Events.GameLoop.ReturnedToTitle -=", StringComparison.Ordinal) &&
                productSource.Contains("OnReturnedToTitle;", StringComparison.Ordinal) &&
                productSource.Contains("helper.Events.Input.KeybindPressed +=", StringComparison.Ordinal) &&
                productSource.Contains("OnKeybindPressed;", StringComparison.Ordinal) &&
                !productSource.Contains("helper.Events.GameLoop.UpdateTicked += OnUpdateTicked", StringComparison.Ordinal),
                "Advanced Zoom must preserve Loader/config owner cleanup and event-driven input without a permanent updater.");
            Assert(CountTextOccurrences(productSource, "RegisterKeybind(") == 2 &&
                !productSource.Contains("RegisterApi<", StringComparison.Ordinal),
                "Zoom must retain exactly two owner-bound input registrations and expose no public provider.");
            Assert(productSource.Contains("public bool Enabled { get; set; } = true", StringComparison.Ordinal) &&
                productSource.Contains("public double MaxViewScale { get; set; } = 4d", StringComparison.Ordinal) &&
                productSource.Contains("public double Step { get; set; } = 0.25d", StringComparison.Ordinal) &&
                productSource.Contains("\"Equals, KeypadPlus\"", StringComparison.Ordinal) &&
                productSource.Contains("\"Minus, KeypadMinus\"", StringComparison.Ordinal),
                "Advanced Zoom must preserve its enabled/range/step and canonical +/- config defaults.");

            string manifest = File.ReadAllText(Path.Combine(productDirectory, "manifest.json"));
            string officialInfo = File.ReadAllText(Path.Combine(productDirectory, "official-info.json"));
            string author = File.ReadAllText(Path.Combine(productDirectory, "dtmapi.author.json"));
            Assert(manifest.Contains("\"Version\": \"1.0.0\"", StringComparison.Ordinal) &&
                manifest.Contains("\"UniqueID\": \"DTMAPI.ZoomMod\"", StringComparison.Ordinal) &&
                manifest.Contains("\"EntryDll\": \"DTMAPI.Zoom.dll\"", StringComparison.Ordinal) &&
                manifest.Contains("\"MinimumDTMApiVersion\": \"0.5.5\"", StringComparison.Ordinal) &&
                manifest.Contains("\"CodeModKind\": \"Advanced\"", StringComparison.Ordinal) &&
                author.Contains("\"referencePolicyId\": \"doloctown-23762374-zoom-v1\"", StringComparison.Ordinal) &&
                author.Contains("\"0Harmony\"", StringComparison.Ordinal) &&
                author.Contains("\"Assembly-CSharp\"", StringComparison.Ordinal),
                "Zoom identity and native references must be generated through its exact admitted Advanced policy.");
            Assert(officialInfo.Contains("\"version\": \"1.0.0\"", StringComparison.Ordinal),
                "Current Zoom source metadata must project the admitted 1.0.0 product version.");
            string[] i18nFiles = Directory.GetFiles(Path.Combine(productDirectory, "i18n"), "*.json", SearchOption.TopDirectoryOnly)
                .Select(path => Path.GetFileName(path) ?? string.Empty)
                .OrderBy(name => name, StringComparer.OrdinalIgnoreCase)
                .ToArray();
            Assert(i18nFiles.SequenceEqual(new[] { "english.json", "schinese.json" }, StringComparer.OrdinalIgnoreCase), "Zoom should preserve its English and Simplified Chinese translation assets.");
            foreach (string i18nFile in i18nFiles)
            {
                string translation = File.ReadAllText(Path.Combine(productDirectory, "i18n", i18nFile));
                foreach (string key in new[] { "mod.loaded", "config.enabled.name", "config.maxScale.name", "config.step.name", "config.increaseKey.name", "config.decreaseKey.name", "config.status" })
                    Assert(translation.Contains("\"" + key + "\"", StringComparison.Ordinal), "Zoom translation " + i18nFile + " should preserve key " + key + ".");
            }

            string solution = File.ReadAllText(Path.Combine(repo, "DTMAPI.sln"));
            string build = File.ReadAllText(Path.Combine(repo, "tools", "scripts", "build.ps1"));
            string release = File.ReadAllText(Path.Combine(repo, "tools", "scripts", "release-common.ps1"));
            string publish = File.ReadAllText(Path.Combine(repo, "tools", "release", "dtmapi-mod-publish-zh.json"));
            string catalog = File.ReadAllText(Path.Combine(repo, "tools", "release", "dtmapi-product-catalog.json"));
            Assert(!solution.Contains("first-party-mods\\ZoomMod", StringComparison.Ordinal) &&
                !build.Contains("first-party-mods\\ZoomMod", StringComparison.Ordinal),
                "Solution/build authorities must not retain the deleted Strict Zoom tree; Advanced products are Catalog/SDK-built rather than hand-added to the solution.");
            Assert(catalog.Contains("\"sourceRoot\": \"products/first-party/Zoom\"", StringComparison.Ordinal) &&
                catalog.Contains("\"project\": \"DTMAPI.Zoom\"", StringComparison.Ordinal) &&
                catalog.Contains("\"productionBuildAuthority\": \"DTMAPI Author SDK build/pack/deploy\"", StringComparison.Ordinal),
                "Catalog/Author SDK metadata must remain the Advanced Zoom build authority.");
            Assert(release.Contains("OfficialFolder = 'DTMAPI_Zoom'", StringComparison.Ordinal) &&
                release.Contains("SourceRoot = 'products\\first-party\\Zoom'", StringComparison.Ordinal) &&
                release.Contains("SourceDll = 'DTMAPI.Zoom.dll'", StringComparison.Ordinal) &&
                release.Contains("PackageDll = 'DTMAPI.Zoom.dll'", StringComparison.Ordinal) &&
                release.Contains("UniqueID = 'DTMAPI.ZoomMod'", StringComparison.Ordinal),
                "Zoom release wiring must preserve identity while using the Advanced product source.");
            Assert(publish.Contains("\"uniqueId\": \"DTMAPI.ZoomMod\"", StringComparison.Ordinal) &&
                publish.Contains("\"officialInfoPath\": \"products/first-party/Zoom/official-info.json\"", StringComparison.Ordinal) &&
                !publish.Contains("\"officialInfoPath\": \"first-party-mods/ZoomMod/official-info.json\"", StringComparison.Ordinal),
                "Canonical publish metadata must resolve Zoom only from its Advanced product path.");
        }

        private static bool EvaluateGameBridgeFinalHealthGate(bool snapshotRequested, bool generalHealthy, bool zoomRequested, bool zoomCleanupHealthy)
        {
            return !snapshotRequested || generalHealthy || (zoomRequested && zoomCleanupHealthy);
        }

        private static int CountTextOccurrences(string text, string value)
        {
            int count = 0;
            int index = 0;
            while ((index = text.IndexOf(value, index, StringComparison.Ordinal)) >= 0)
            {
                count++;
                index += value.Length;
            }
            return count;
        }

        private static void ConfigPreviewAuditBoundsRecentFailures()
        {
            var ledger = new ModOwnerLedgerService();
            for (int i = 0; i < 200; i++)
                ledger.RecordConfigPreview("DTMAPI.Tests.PreviewFailure", "scope", "ChangedItems", "restore", false, "failure=" + i.ToString(CultureInfo.InvariantCulture));

            ModOwnerLedgerSnapshot snapshot = ledger.GetSnapshot();
            Assert(snapshot.ConfigPreviewObservedCount == 200 && snapshot.ConfigPreviewWarningCount == 200, "Config preview aggregate counters should preserve the full failure history.");
            Assert(snapshot.ConfigPreviewAggregates.Count == 1, "Repeated failures for one preview scope should use one stable aggregate record.");
            Assert(snapshot.RecentConfigPreviewFailureCount == 64 && snapshot.Entries.Count == 64, "Config preview diagnostics should retain only the bounded 64 most recent failure samples.");
            Assert(snapshot.ConfigPreviewAggregates.All(aggregate => aggregate.LastDetails.Length == 0), "Config preview aggregate rows must retain counts only and keep LastDetails permanently empty.");
            Assert(snapshot.Entries.All(entry => entry.Kind == "ConfigPreview" && entry.Status == "Warning" && entry.RollbackResult.StartsWith("failure=", StringComparison.Ordinal)), "Arbitrary preview failure details should exist only in the bounded recent failure window.");
            Assert(snapshot.Entries.First().RollbackResult == "failure=136" && snapshot.Entries.Last().RollbackResult == "failure=199", "The bounded preview failure window should retain exactly the latest 64 scalar details.");

            var uniqueLedger = new ModOwnerLedgerService();
            for (int i = 0; i < 400; i++)
            {
                uniqueLedger.RecordConfigPreview(
                    "DTMAPI.Tests.PreviewUnique." + i.ToString(CultureInfo.InvariantCulture),
                    "scope-" + i.ToString(CultureInfo.InvariantCulture),
                    "Kind-" + i.ToString(CultureInfo.InvariantCulture),
                    "Operation-" + i.ToString(CultureInfo.InvariantCulture),
                    true,
                    "scalar");
            }

            ModOwnerLedgerSnapshot uniqueSnapshot = uniqueLedger.GetSnapshot();
            ModOwnerConfigPreviewAggregate overflow = uniqueSnapshot.ConfigPreviewAggregates.Single(aggregate =>
                aggregate.Kind == "other" && aggregate.Operation == "other");
            Assert(uniqueSnapshot.ConfigPreviewAggregates.Count == 256, "Unique config preview operation/kind pairs must retain at most 256 aggregate records including overflow.");
            Assert(overflow.ObservationCount == 145, "Config preview aggregate overflow should count every observation beyond the 255 retained specific keys.");
            Assert(uniqueSnapshot.ConfigPreviewAggregates.All(aggregate => aggregate.LastDetails.Length == 0), "Successful and overflow preview aggregates must never retain arbitrary LastDetails.");
            Assert(uniqueSnapshot.Entries.Count == 0 && uniqueSnapshot.RecentConfigPreviewFailureCount == 0, "Successful preview details should not enter the recent failure window.");
        }

        private static void FishingAnimationMultiplierUsesFullTrajectoryPreservingScale()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                StageCompatibilityHostFixture(dir);
                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                var service = new LegacyFishingAutomationService(runtime);
                var owner = new ManifestModel { Name = "Animation", Author = "DTMAPI", Version = "1.0.0", UniqueID = "DTMAPI.Tests.FishingAnimation", Type = "CodeMod" };
                service.Configure(owner, new FishingAutomationOptions
                {
                    AnimationMode = FishingAnimationMode.FastCastPull,
                    AnimationMultiplier = 4,
                    CastChargeRatio = 0
                });
                service.SetEnabled(owner, true, "animation-unit");
                object backend = CompatibilityHostBroker.For(runtime).GetService("FishingAutomation");
                Type backendType = backend.GetType();

                float duration = 8f;
                service.AdjustFishingPullDurationResult(ref duration, "unit-pull");
                Assert(Math.Abs(duration - 2f) < 0.0001f, "Pull duration should divide by the full multiplier even when first-party casting uses zero charge.");

                var hook = new FakeFishingHook { Velocity = new FakeVector2(2f, 3f) };
                MethodInfo scaleVector = backendType.GetMethod("TryScaleVector2Member", BindingFlags.Static | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("Fishing velocity scaler should exist.");
                var samples = new List<string>();
                int velocityChanged = (int)(scaleVector.Invoke(null, new object[] { hook, "Velocity", 4d, "hook.Velocity", samples }) ?? 0);
                Assert(velocityChanged == 1 && Math.Abs(hook.Velocity.x - 8f) < 0.0001f && Math.Abs(hook.Velocity.y - 12f) < 0.0001f, "Hook velocity should multiply by the full configured multiplier.");

                var rigidbody = new FakeFishingRigidbody { gravityScale = 2f };
                MethodInfo scaleGravity = backendType.GetMethod("TryScaleHookGravity", BindingFlags.Instance | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("Fishing gravity scaler should exist.");
                int gravityChanged = (int)(scaleGravity.Invoke(backend, new object[] { rigidbody, 4d, samples }) ?? 0);
                Assert(gravityChanged == 1 && Math.Abs(rigidbody.gravityScale - 32f) < 0.0001f, "Hook gravity should multiply by m² so the scaled flight keeps its native trajectory.");
                service.RestoreExperimentalAnimatorSpeeds("animation-unit-restore");
                Assert(Math.Abs(rigidbody.gravityScale - 2f) < 0.0001f, "Animation lease cleanup should restore the original hook gravity.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void LegacyFishingAutomationServiceFailureThrottleRecordsOneDiagnosticPerOperation()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                StageCompatibilityHostFixture(dir);
                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                object service = CompatibilityHostBroker.For(runtime).GetService("FishingAutomation");
                Type serviceType = service.GetType();
                MethodInfo recordFailure = serviceType.GetMethod("RecordFishingAutomationFailure", BindingFlags.Instance | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("LegacyFishingAutomationService failure throttle helper should exist.");

                for (int i = 0; i < 6; i++)
                {
                    recordFailure.Invoke(service, new object?[]
                    {
                        "FishingAutomation.MiniGame.Update",
                        new InvalidOperationException("mini-game-boom"),
                        true,
                        "Smoke.AutoFishingMiniGameComplete",
                        "FishingGameScrollBar.UpdateGame Postfix"
                    });
                }

                Assert(runtime.Diagnostics.GetErrors().Count(e => e.Owner == "DTMAPI.GameBridge.FishingAutomation") == 1, "Repeated FishingAutomation service failures for the same operation should record only the first diagnostics error.");
                IHookStatusInfo hookStatus = runtime.Diagnostics.GetHookStatuses().Single(s => s.HookId == "Smoke.AutoFishingMiniGameComplete");
                Assert(hookStatus.Details.Contains("failureCount=3", StringComparison.Ordinal), "Repeated high-frequency FishingAutomation failures should publish hook status only through the short-warning limit.");
                Assert(!hookStatus.Details.Contains("failureCount=6", StringComparison.Ordinal), "Suppressed high-frequency FishingAutomation failures should not rewrite hook status on every repeat.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void LegacyFishingAutomationServiceFailureRecoveryStartsNewDiagnosticsEpisodeAfterStableSuccess()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                StageCompatibilityHostFixture(dir);
                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                object service = CompatibilityHostBroker.For(runtime).GetService("FishingAutomation");
                Type serviceType = service.GetType();
                MethodInfo recordFailure = serviceType.GetMethod("RecordFishingAutomationFailure", BindingFlags.Instance | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("LegacyFishingAutomationService failure throttle helper should exist.");
                MethodInfo recordSuccess = serviceType.GetMethod("RecordFishingAutomationSuccess", BindingFlags.Instance | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("LegacyFishingAutomationService success recovery helper should exist.");
                IDictionary failureEpisodes = (IDictionary)(serviceType.GetField("fishingAutomationFailures", BindingFlags.Instance | BindingFlags.NonPublic)?.GetValue(service)
                    ?? throw new InvalidOperationException("LegacyFishingAutomationService should keep service failure throttle state."));

                for (int i = 0; i < 6; i++)
                    recordFailure.Invoke(service, new object?[] { "FishingAutomation.MiniGame.Update", new InvalidOperationException("mini-game-boom"), true, "Smoke.AutoFishingMiniGameComplete", "FishingGameScrollBar.UpdateGame Postfix" });

                Assert(runtime.Diagnostics.GetErrors().Count(e => e.Owner == "DTMAPI.GameBridge.FishingAutomation") == 1, "Initial repeated FishingAutomation failures should record one diagnostics error.");
                recordSuccess.Invoke(service, new object?[] { "FishingAutomation.MiniGame.Update" });
                recordSuccess.Invoke(service, new object?[] { "FishingAutomation.MiniGame.Update" });
                Assert(failureEpisodes.Count == 1, "Two stable FishingAutomation successes should not clear a failure episode yet.");
                recordSuccess.Invoke(service, new object?[] { "FishingAutomation.MiniGame.Update" });
                Assert(failureEpisodes.Count == 0, "Three stable FishingAutomation successes should clear the failure episode.");

                recordFailure.Invoke(service, new object?[] { "FishingAutomation.MiniGame.Update", new InvalidOperationException("mini-game-boom-again"), true, "Smoke.AutoFishingMiniGameComplete", "FishingGameScrollBar.UpdateGame Postfix" });
                Assert(runtime.Diagnostics.GetErrors().Count(e => e.Owner == "DTMAPI.GameBridge.FishingAutomation") == 2, "A post-recovery FishingAutomation failure should start a new diagnostics episode.");
                IHookStatusInfo hookStatus = runtime.Diagnostics.GetHookStatuses().Single(s => s.HookId == "Smoke.AutoFishingMiniGameComplete");
                Assert(hookStatus.Details.Contains("failureCount=1", StringComparison.Ordinal), "Post-recovery FishingAutomation failure should publish as a fresh first failure.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void FishingAutomationSuccessDiagnosticsThrottleRepeatedHookStatus()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                StageCompatibilityHostFixture(dir);
                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                object service = CompatibilityHostBroker.For(runtime).GetService("FishingAutomation");
                Type serviceType = service.GetType();
                MethodInfo publishHookStatus = serviceType.GetMethod("PublishFishingAutomationHookStatus", BindingFlags.Instance | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("LegacyFishingAutomationService success diagnostic publisher should exist.");
                IDictionary diagnosticStates = (IDictionary)(serviceType.GetField("fishingAutomationDiagnostics", BindingFlags.Instance | BindingFlags.NonPublic)?.GetValue(service)
                    ?? throw new InvalidOperationException("LegacyFishingAutomationService should keep success diagnostic throttle state."));

                for (int i = 0; i < 20; i++)
                {
                    publishHookStatus.Invoke(service, new object[]
                    {
                        "Smoke.AutoFishingReadyChargeSpeed",
                        "verified",
                        "AgentStateFishingReady.OnPlay",
                        "iteration=" + i.ToString(CultureInfo.InvariantCulture),
                        "ReadyChargeSpeed.Verified"
                    });
                }

                IHookStatusInfo hookStatus = runtime.Diagnostics.GetHookStatuses().Single(s => s.HookId == "Smoke.AutoFishingReadyChargeSpeed");
                Assert(hookStatus.Details.Contains("iteration=0", StringComparison.Ordinal), "Repeated AutoFishing success diagnostics should publish the first state-change sample only.");
                Assert(!hookStatus.Details.Contains("iteration=19", StringComparison.Ordinal), "Suppressed AutoFishing success diagnostics should not rewrite hook status on every repeat.");
                Assert(diagnosticStates.Count == 1, "AutoFishing success diagnostics should track one throttle entry for one hook/source key.");
                object diagnosticState = diagnosticStates.Values.Cast<object>().Single();
                int observed = (int)(diagnosticState.GetType().GetProperty("ObservedCount")?.GetValue(diagnosticState) ?? -1);
                int published = (int)(diagnosticState.GetType().GetProperty("PublishedCount")?.GetValue(diagnosticState) ?? -1);
                Assert(observed == 20, "AutoFishing success diagnostic throttle should count every observed repeated success.");
                Assert(published == 1, "AutoFishing success diagnostic throttle should publish only the initial state-change sample.");

                publishHookStatus.Invoke(service, new object[]
                {
                    "Smoke.AutoFishingReadyChargeSpeed",
                    "pending",
                    "AgentStateFishingReady.OnPlay",
                    "iteration=status-change",
                    "ReadyChargeSpeed.Verified"
                });

                IHookStatusInfo changed = runtime.Diagnostics.GetHookStatuses().Single(s => s.HookId == "Smoke.AutoFishingReadyChargeSpeed");
                Assert(changed.Status == "pending" && changed.Details.Contains("iteration=status-change", StringComparison.Ordinal), "AutoFishing success diagnostic throttle should still publish status changes immediately.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void FishingAutomationRuntimeStateResetClearsTransientState()
        {
            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                StageCompatibilityHostFixture(dir);
                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                object service = CompatibilityHostBroker.For(runtime).GetService("FishingAutomation");
                Type serviceType = service.GetType();

                object miniGameHandle = new object();
                var animator = new FakeAnimator { speed = 3.0 };
                IDictionary miniGameStartedAt = (IDictionary)(serviceType.GetField("fishingMiniGameStartedAt", BindingFlags.Instance | BindingFlags.NonPublic)?.GetValue(service)
                    ?? throw new InvalidOperationException("LegacyFishingAutomationService should keep mini-game handle state."));
                object loggedPhases = serviceType.GetField("loggedFishingPhases", BindingFlags.Instance | BindingFlags.NonPublic)?.GetValue(service)
                    ?? throw new InvalidOperationException("LegacyFishingAutomationService should keep phase log cooldown state.");
                IDictionary failureEpisodes = (IDictionary)(serviceType.GetField("fishingAutomationFailures", BindingFlags.Instance | BindingFlags.NonPublic)?.GetValue(service)
                    ?? throw new InvalidOperationException("LegacyFishingAutomationService should keep service failure throttle state."));
                IDictionary diagnosticStates = (IDictionary)(serviceType.GetField("fishingAutomationDiagnostics", BindingFlags.Instance | BindingFlags.NonPublic)?.GetValue(service)
                    ?? throw new InvalidOperationException("LegacyFishingAutomationService should keep success diagnostic throttle state."));
                IDictionary animatorSpeeds = (IDictionary)(serviceType.GetField("originalAnimatorSpeeds", BindingFlags.Instance | BindingFlags.NonPublic)?.GetValue(service)
                    ?? throw new InvalidOperationException("LegacyFishingAutomationService should keep original animator speed state."));

                miniGameStartedAt[miniGameHandle] = DateTimeOffset.UtcNow;
                loggedPhases.GetType().GetMethod("Add", new[] { typeof(string) })?.Invoke(loggedPhases, new object[] { "Pull" });
                MethodInfo recordFailure = serviceType.GetMethod("RecordFishingAutomationFailure", BindingFlags.Instance | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("LegacyFishingAutomationService failure throttle helper should exist.");
                recordFailure.Invoke(service, new object?[] { "FishingAutomation.MiniGame.Update", new InvalidOperationException("mini-game-boom"), true, null, null });
                MethodInfo publishHookStatus = serviceType.GetMethod("PublishFishingAutomationHookStatus", BindingFlags.Instance | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("LegacyFishingAutomationService success diagnostic publisher should exist.");
                publishHookStatus.Invoke(service, new object[] { "Smoke.AutoFishingReadyChargeSpeed", "verified", "AgentStateFishingReady.OnPlay", "iteration=reset", "ReadyChargeSpeed.Verified" });
                animatorSpeeds[animator] = 1.25;

                MethodInfo reset = serviceType.GetMethod("ResetFishingRuntimeState", BindingFlags.Instance | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("LegacyFishingAutomationService reset helper should exist.");
                reset.Invoke(service, new object[] { "unit-test-reset" });

                Assert(miniGameStartedAt.Count == 0, "FishingAutomation reset should clear mini-game handle state.");
                int loggedPhaseCount = (int)(loggedPhases.GetType().GetProperty("Count")?.GetValue(loggedPhases) ?? -1);
                Assert(loggedPhaseCount == 0, "FishingAutomation reset should clear phase log cooldown state.");
                Assert(failureEpisodes.Count == 0, "FishingAutomation reset should clear service failure throttle state.");
                Assert(diagnosticStates.Count == 0, "FishingAutomation reset should clear success diagnostic throttle state.");
                Assert(animatorSpeeds.Count == 0 && Math.Abs(animator.speed - 1.25) < 0.0001, "FishingAutomation reset should restore and clear animator speed snapshots.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

