                    Type = "RuntimeApi"
                };
                ((LegacyFishingAutomationService)service).Configure(owner, new FishingAutomationOptions
                {
                    AnimationMode = FishingAnimationMode.FastCastPull,
                    AnimationMultiplier = 2
                });
                ((LegacyFishingAutomationService)service).SetEnabled(owner, true, "unit-test");
                MethodInfo notify = serviceType.GetMethod("NotifyFishingPhase", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("LegacyFishingAutomationService should keep phase notification helper.");
                PropertyInfo applicationCount = serviceType.GetProperty("FishingAutomationApplicationCount", BindingFlags.Instance | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("LegacyFishingAutomationService should expose an internal application counter.");

                var readySource = new FakeFishingAnimationSource { animator = new FakeAnimator { speed = 1 } };
                notify.Invoke(service, new object?[] { "Ready", readySource });
                Assert((int)(applicationCount.GetValue(service) ?? -1) == 0 && Math.Abs(readySource.animator.speed - 1) < 0.0001, "FishingAutomation FastAnimations should not run on the no-charge Ready phase.");

                var castSource = new FakeFishingAnimationSource { animator = new FakeAnimator { speed = 1.25 } };
                notify.Invoke(service, new object?[] { "Cast", castSource });
                Assert((int)(applicationCount.GetValue(service) ?? -1) == 1 && Math.Abs(castSource.animator.speed - 2.5) < 0.0001, "FishingAutomation FastAnimations should run on Cast phase.");

                var waitSource = new FakeFishingAnimationSource { animator = new FakeAnimator { speed = 1 } };
                notify.Invoke(service, new object?[] { "Wait", waitSource });
                Assert((int)(applicationCount.GetValue(service) ?? -1) == 1 && Math.Abs(waitSource.animator.speed - 1) < 0.0001, "FishingAutomation FastAnimations must not run on Wait phase.");

                var pullSource = new FakeFishingAnimationSource { animator = new FakeAnimator { speed = 1.5 } };
                notify.Invoke(service, new object?[] { "Pull", pullSource });
                Assert((int)(applicationCount.GetValue(service) ?? -1) == 2 && Math.Abs(pullSource.animator.speed - 3) < 0.0001, "FishingAutomation FastAnimations should run on Pull phase.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void FishingAutomationReadyChargeSpeedTicksNativeCastTimer()
        {
            Assembly bridgeAssembly = typeof(DolocTownGameBridge).Assembly;
            Type serviceType = bridgeAssembly.GetType("DTMAPI.GameBridge.DolocTown.LegacyFishingAutomationService")
                ?? throw new InvalidOperationException("LegacyFishingAutomationService type should exist.");

            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                StageCompatibilityHostFixture(dir);
                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                object service = Activator.CreateInstance(serviceType, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic, null, new object[] { runtime }, null)
                    ?? throw new InvalidOperationException("LegacyFishingAutomationService should be constructable for unit tests.");
                var owner = new ManifestModel
                {
                    Name = "AutoFishing Tests",
                    Author = "DTMAPI",
                    Version = "1.0.0",
                    UniqueID = "DTMAPI.Tests.AutoFishing",
                    Type = "RuntimeApi"
                };
                ((LegacyFishingAutomationService)service).Configure(owner, new FishingAutomationOptions
                {
                    AnimationMode = FishingAnimationMode.FastCastPull,
                    AnimationMultiplier = 3
                });
                ((LegacyFishingAutomationService)service).SetEnabled(owner, true, "unit-test");
                MethodInfo applyReadyCharge = serviceType.GetMethod("ApplyFishingReadyChargeSpeed", BindingFlags.Instance | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("LegacyFishingAutomationService should expose Ready charge speed helper.");

                var noChargeState = new FakeFishingReadyState();
                applyReadyCharge.Invoke(service, new object?[] { noChargeState });
                Assert(noChargeState._castTimer.TickCount == 0, "FishingAutomation no-charge Ready phase must not tick the native CastTimer.");
                Assert(noChargeState._powerBar.Progress == 0, "FishingAutomation no-charge Ready phase must not advance the progress circle.");

                ((LegacyFishingAutomationService)service).Configure(owner, new FishingAutomationOptions
                {
                    AnimationMode = FishingAnimationMode.FastCastPull,
                    AnimationMultiplier = 3,
                    CastChargeRatio = 0.5
                });
                var readyState = new FakeFishingReadyState();
                applyReadyCharge.Invoke(service, new object?[] { readyState });

                Assert(readyState._castTimer.TickCount == 1, "FishingAutomation Ready charge speed should tick the native CastTimer.");
                Assert(readyState._castTimer.LastDelta > 0.039 && readyState._castTimer.LastDelta < 0.041, "FishingAutomation Ready charge speed should add (multiplier-1)*fixedDeltaTime to CastTimer.");
                Assert(readyState._powerBar.Progress > 0.039 && readyState._powerBar.Progress < 0.041, "FishingAutomation Ready charge speed should refresh the native progress circle.");
                PropertyInfo lastSummaryProperty = serviceType.GetProperty("LastFishingAnimationSpeedSummary", BindingFlags.Instance | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("LegacyFishingAutomationService should expose its animation diagnostic summary.");
                string firstSummary = (string)(lastSummaryProperty.GetValue(service) ?? string.Empty);
                applyReadyCharge.Invoke(service, new object?[] { readyState });
                string secondSummary = (string)(lastSummaryProperty.GetValue(service) ?? string.Empty);
                Assert(ReferenceEquals(firstSummary, secondSummary), "Ready charge hot ticks after the first application should not rebuild diagnostic strings.");
                Assert(readyState._castTimer.TickCount == 2, "Eliminating Ready hot-path strings must not stop native charge acceleration.");
                for (int i = 0; i < 128; i++)
                    applyReadyCharge.Invoke(service, new object?[] { readyState });
                int readyAccessorBuilds = ((LegacyFishingAutomationService)service).ReadyAccessorBuildCount;
                long beforeAllocated = GC.GetAllocatedBytesForCurrentThread();
                for (int i = 0; i < 10000; i++)
                    ((LegacyFishingAutomationService)service).ApplyFishingReadyChargeSpeed(readyState);
                long readyAllocated = GC.GetAllocatedBytesForCurrentThread() - beforeAllocated;
                Assert(((LegacyFishingAutomationService)service).ReadyAccessorBuildCount == readyAccessorBuilds, "Warmed Ready charge frames must not rebuild native accessors.");
                Assert(readyAllocated == 0, "Warmed Ready charge frames should allocate zero bytes on the test thread, actual=" + readyAllocated + ".");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void FishingAutomationReadyChargeTargetControlsUseToolRelease()
        {
            Assembly bridgeAssembly = typeof(DolocTownGameBridge).Assembly;
            Type serviceType = bridgeAssembly.GetType("DTMAPI.GameBridge.DolocTown.LegacyFishingAutomationService")
                ?? throw new InvalidOperationException("LegacyFishingAutomationService type should exist.");

            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                StageCompatibilityHostFixture(dir);
                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                object service = Activator.CreateInstance(serviceType, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic, null, new object[] { runtime }, null)
                    ?? throw new InvalidOperationException("LegacyFishingAutomationService should be constructable for unit tests.");
                var owner = new ManifestModel
                {
                    Name = "AutoFishing Tests",
                    Author = "DTMAPI",
                    Version = "1.0.0",
                    UniqueID = "DTMAPI.Tests.AutoFishing",
                    Type = "RuntimeApi"
                };
                ((LegacyFishingAutomationService)service).Configure(owner, new FishingAutomationOptions
                {
                    CastChargeRatio = 0.5,
                    AnimationMode = FishingAnimationMode.FastCastPull,
                    AnimationMultiplier = 3
                });
                ((LegacyFishingAutomationService)service).SetEnabled(owner, true, "unit-test");
                MethodInfo applyReady = serviceType.GetMethod("ApplyFishingReadyAutomation", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("LegacyFishingAutomationService should expose Ready automation helper.");
                MethodInfo overrideInput = serviceType.GetMethod("TryOverrideFishingReadyChargeInput", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("LegacyFishingAutomationService should expose Ready input override helper.");

                var readyState = new FakeFishingReadyState();
                applyReady.Invoke(service, new object?[] { readyState });
                object?[] holdArgs = { "NormalUseToolInProgress", false };
                bool holdHandled = (bool)(overrideInput.Invoke(service, holdArgs) ?? false);
                bool holdValue = (bool)(holdArgs[1] ?? false);
                Assert(holdHandled && holdValue, "FishingAutomation should hold the native use-tool input before the configured charge target.");

                readyState._castTimer.Tick(0.6f);
                object?[] releaseArgs = { "NormalUseToolInProgress", false };
                bool releaseHandled = (bool)(overrideInput.Invoke(service, releaseArgs) ?? false);
                bool releaseValue = (bool)(releaseArgs[1] ?? true);
                Assert(releaseHandled && !releaseValue, "FishingAutomation should release the native use-tool input after reaching the configured charge target.");
                double releasedProgress = readyState._castTimer.Progress;
                applyReady.Invoke(service, new object?[] { readyState });
                Assert(Math.Abs(readyState._castTimer.Progress - releasedProgress) < 0.0001, "FastAnimations must stop adding Ready timer progress after the configured target releases, so the backswing cannot change final cast power.");

                ((LegacyFishingAutomationService)service).Configure(owner, new FishingAutomationOptions());
                var noChargeState = new FakeFishingReadyState();
                applyReady.Invoke(service, new object?[] { noChargeState });
                object?[] noChargeReleaseArgs = { "NormalUseToolInProgress", true };
                bool noChargeReleaseHandled = (bool)(overrideInput.Invoke(service, noChargeReleaseArgs) ?? false);
                bool noChargeReleaseValue = (bool)(noChargeReleaseArgs[1] ?? true);
                Assert(noChargeReleaseHandled && !noChargeReleaseValue, "FishingAutomation zero charge should release immediately so native Ready keeps the exact minimum-power target while its own animation gate preserves the backswing.");

                var missingTimerState = new object();
                applyReady.Invoke(service, new object?[] { missingTimerState });
                object?[] missingTimerArgs = { "NormalUseToolInProgress", true };
                bool missingTimerHandled = (bool)(overrideInput.Invoke(service, missingTimerArgs) ?? false);
                bool missingTimerValue = (bool)(missingTimerArgs[1] ?? true);
                Assert(missingTimerHandled && !missingTimerValue, "FishingAutomation should fail open and release Ready input when the native CastTimer cannot be read.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void AutoFishingModConfigPreservesCustomToggleKey()
        {
            var customConfig = new AutoFishingConfig { ToggleKey = "F7", AnimationMultiplier = 0, CastChargeRatio = 2 };
            customConfig.Normalize();
            Assert(customConfig.ToggleKey == "F7", "AutoFishing custom toggle key should not be reset to F6.");
            Assert(Math.Abs(customConfig.AnimationMultiplier - 3) < 0.0001, "AutoFishing missing animation multiplier should migrate to default three.");
            Assert(Math.Abs(customConfig.CastChargeRatio - 1) < 0.0001, "AutoFishing cast charge should clamp to full charge.");

            var missingConfig = new AutoFishingConfig { ToggleKey = "  ", AnimationMultiplier = 3 };
            missingConfig.Normalize();
            Assert(missingConfig.ToggleKey == "F6", "AutoFishing missing toggle key should migrate to default F6.");

            var noneConfig = new AutoFishingConfig { ToggleKey = "None", AnimationMultiplier = 3 };
            noneConfig.Normalize();
            Assert(noneConfig.ToggleKey == "None", "AutoFishing explicit None toggle key should remain disabled.");
        }

        private static void AutoFishingDecisionEngineKeepsProductOptionsIndependent()
        {
            var engine = new FishingDecisionEngine();
            DateTimeOffset now = DateTimeOffset.UtcNow;
            var idle = new FishingPrimitiveSnapshot(1, FishingPrimitivePhase.Idle, true, true, true, false, false, false, false, true, 0, 0, 0);
            Assert(engine.Decide(idle, instantBite: false, skipMiniGame: false, nowUtc: now, nextCastAtUtc: now).Action == FishingProductAction.Cast, "Idle due state should request a cast.");

            var wait = new FishingPrimitiveSnapshot(2, FishingPrimitivePhase.WaitPlayable, false, true, true, true, false, false, false, true, 0, 0, 0);
            Assert(engine.Decide(wait, instantBite: false, skipMiniGame: false, nowUtc: now, nextCastAtUtc: now).Action == FishingProductAction.None, "Default loop should keep the native bite wait.");
            Assert(engine.Decide(wait, instantBite: true, skipMiniGame: false, nowUtc: now, nextCastAtUtc: now).Action == FishingProductAction.PrepareNativeBite, "InstantBite should only change WaitPlayable behavior.");

            int combinations = 0;
            foreach (bool instant in new[] { false, true })
            {
                foreach (bool skip in new[] { false, true })
                {
                    foreach (bool fast in new[] { false, true })
                    {
                        var bite = new FishingPrimitiveSnapshot(3 + combinations, FishingPrimitivePhase.BiteReady, false, true, true, false, true, true, false, true, 0, 0, 0);
                        FishingProductAction action = engine.Decide(bite, instant, skip, now, now).Action;
                        Assert(action == (skip ? FishingProductAction.ReelSkipMiniGame : FishingProductAction.ReelVisibleMiniGame), "BiteReady result choice should depend only on SkipMiniGame across all eight option combinations; fast=" + fast + " instant=" + instant + ".");
                        combinations++;
                    }
                }
            }
            Assert(combinations == 8, "All three independent product switches should produce eight tested combinations.");

            Assert(engine.DecideMiniGameInput(new FishingMiniGameFrame(1, 1.5, FishingMiniGameNoteKind.Stable, 0, 1, 2, false)) == FishingSyntheticInputAction.Hold, "Stable notes should hold native use input.");
            Assert(engine.DecideMiniGameInput(new FishingMiniGameFrame(1, 1.5, FishingMiniGameNoteKind.Bonus, 1, 1, 2, false)) == FishingSyntheticInputAction.TapBonus, "Untapped bonus notes should tap once.");
            Assert(engine.DecideMiniGameInput(new FishingMiniGameFrame(1, 1.5, FishingMiniGameNoteKind.Bonus, 1, 1, 2, true)) == FishingSyntheticInputAction.Release, "Already-tapped bonus notes should release.");
            Assert(engine.DecideMiniGameInput(new FishingMiniGameFrame(1, 1.5, FishingMiniGameNoteKind.Avoid, 2, 1, 2, false)) == FishingSyntheticInputAction.Release, "Avoid notes should release native use input.");

            var defaults = new AutoFishingConfig();
            Assert(!defaults.InstantBite && !defaults.SkipMiniGame && !defaults.FastAnimations && Math.Abs(defaults.AnimationMultiplier - 3) < 0.0001 && Math.Abs(defaults.CastChargeRatio) < 0.0001, "First-party defaults should keep optional switches off, zero charge, and animation multiplier three.");
        }

        private static void AnimalViewerLocalizationGuardRecognizesUiLocalizationComponents()
        {
            Type serviceType = LoadCompatibilityBackendType("AnimalViewer");
            MethodInfo looksLikeLocalization = serviceType.GetMethod("LooksLikeLocalizationComponent", BindingFlags.Static | BindingFlags.NonPublic)
                ?? throw new InvalidOperationException("AnimalViewerService should keep a localization guard helper.");

            Assert((bool)(looksLikeLocalization.Invoke(null, new object[] { "DolocTown.UI.UILocalization" }) ?? false), "AnimalViewer localization guard should recognize Doloc UI localization components.");
            Assert((bool)(looksLikeLocalization.Invoke(null, new object[] { "Some.Namespace.LocalizeText" }) ?? false), "AnimalViewer localization guard should recognize Localize-style components.");
            Assert(!(bool)(looksLikeLocalization.Invoke(null, new object[] { "UnityEngine.UI.Text" }) ?? true), "AnimalViewer localization guard must not disable plain text components.");
            Assert(!(bool)(looksLikeLocalization.Invoke(null, new object[] { "DolocTown.UI.ProgressBar" }) ?? true), "AnimalViewer localization guard must not disable the ProgressBar component itself.");
        }

        private static void AnimalViewerNativeCloseBoundaryPublishesNeutralLifecycle()
        {
            Assembly bridgeAssembly = typeof(DolocTownGameBridge).Assembly;
            Type serviceType = LoadCompatibilityBackendType("AnimalViewer");
            Type hookBridgeType = bridgeAssembly.GetType("DTMAPI.GameBridge.DolocTown.AnimalViewerHookBridge")
                ?? throw new InvalidOperationException("AnimalViewerHookBridge type should exist.");
            MethodInfo close = serviceType.GetMethod("NotifyAnimalPanelUnregistered", BindingFlags.Instance | BindingFlags.NonPublic)
                ?? throw new InvalidOperationException("AnimalViewerService must expose the native panel close boundary internally.");
            FieldInfo nativeRows = serviceType.GetField("animalProgressRowsByData", BindingFlags.Instance | BindingFlags.NonPublic)
                ?? throw new InvalidOperationException("AnimalViewerService should retain derived native rows only for the current panel session.");
            Type renderRowType = serviceType.GetNestedType("AnimalProgressRenderRow", BindingFlags.NonPublic)
                ?? throw new InvalidOperationException("AnimalViewerService progress render row type should exist.");
            MethodInfo callback = typeof(DolocTownHookCallbacks).GetMethod("AnimalPanelUiStateUnregisterPostfix", BindingFlags.Public | BindingFlags.Static)
                ?? throw new InvalidOperationException("The native AnimalPanelUiState.Unregister postfix callback should exist.");
            PropertyInfo closePatched = hookBridgeType.GetProperty("PanelUnregisterPatched", BindingFlags.Instance | BindingFlags.NonPublic)
                ?? throw new InvalidOperationException("AnimalViewerHookBridge should track its native panel close patch.");

            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                StageCompatibilityHostFixture(dir);
                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                var bridge = new DolocTownGameBridge(runtime);
                FieldInfo featureField = typeof(DolocTownGameBridge).GetField("animalViewerFeature", BindingFlags.Instance | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("DolocTownGameBridge should retain its AnimalViewer feature for hook readiness projection.");
                object feature = featureField.GetValue(bridge)
                    ?? throw new InvalidOperationException("DolocTownGameBridge should initialize the AnimalViewer feature during API registration.");
                PropertyInfo hookBridgeProperty = feature.GetType().GetProperty("HookBridge", BindingFlags.Instance | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("AnimalViewerFeature should expose its hook bridge internally.");
                object hookBridge = hookBridgeProperty.GetValue(feature)
                    ?? throw new InvalidOperationException("AnimalViewerFeature hook bridge should exist.");
                PropertyInfo fullInfoPatched = hookBridgeType.GetProperty("FullInfoDataPatched", BindingFlags.Instance | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("AnimalViewerHookBridge should track its FullInfoData patch.");
                PropertyInfo showPrefixPatched = hookBridgeType.GetProperty("ViewerShowPrefixPatched", BindingFlags.Instance | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("AnimalViewerHookBridge should track its Viewer.Show prefix patch.");
                PropertyInfo showPatched = hookBridgeType.GetProperty("ViewerShowPatched", BindingFlags.Instance | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("AnimalViewerHookBridge should track its Viewer.Show postfix patch.");
                PropertyInfo hooksReady = hookBridgeType.GetProperty("HooksReady", BindingFlags.Instance | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("AnimalViewerHookBridge should expose aggregate readiness internally.");
                PropertyInfo globalPanelUnregisterPatched = typeof(DolocTownGameBridge).GetProperty("animalPanelUnregisterPatched", BindingFlags.Instance | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("DolocTownGameBridge must project the AnimalPanelUiState.Unregister hook into global readiness.");
                MethodInfo featureSummary = typeof(DolocTownGameBridge).GetMethod("BuildFeatureHookReadinessSummary", BindingFlags.Instance | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("DolocTownGameBridge should expose its feature hook readiness summary internally.");

                int ReadSummaryCount(string name)
                {
                    string summary = (string)(featureSummary.Invoke(bridge, Array.Empty<object>())
                        ?? throw new InvalidOperationException("Feature hook readiness summary should be available."));
                    string prefix = name + "=";
                    string token = summary.Split(';').Select(part => part.Trim()).Single(part => part.StartsWith(prefix, StringComparison.Ordinal));
                    return int.Parse(token.Substring(prefix.Length), CultureInfo.InvariantCulture);
                }

                int ReadyCount() => ReadSummaryCount("readyCount");

                int initialReady = ReadyCount();
                int initialTotal = ReadSummaryCount("total");
                fullInfoPatched.SetValue(hookBridge, true);
                showPatched.SetValue(hookBridge, true);
                Assert(!(bool)(hooksReady.GetValue(hookBridge) ?? true) && ReadyCount() == initialReady + 2,
                    "Global AnimalViewer readiness must not become ready when only the former FullInfoData and Viewer.Show postfix pair is installed.");
                showPrefixPatched.SetValue(hookBridge, true);
                Assert(!(bool)(hooksReady.GetValue(hookBridge) ?? true) && ReadyCount() == initialReady + 3,
                    "Global AnimalViewer readiness must count the Viewer.Show prefix while still requiring the native close hook.");
                closePatched.SetValue(hookBridge, true);
                Assert((bool)(hooksReady.GetValue(hookBridge) ?? false) &&
                    (bool)(globalPanelUnregisterPatched.GetValue(bridge) ?? false) &&
                    ReadyCount() == initialReady + 4 &&
                    ReadSummaryCount("total") == initialTotal &&
                    initialTotal >= 4,
                    "Global readiness must project and count all four AnimalViewer hooks without hard-coding unrelated product Hook totals.");

                object service = CompatibilityHostBroker.For(runtime).GetService("AnimalViewer");

                var retainedRows = (IDictionary)(nativeRows.GetValue(service)
                    ?? throw new InvalidOperationException("AnimalViewerService native row map should exist."));
                retainedRows.Add(new object(), Array.CreateInstance(renderRowType, 0));
                Assert(retainedRows.Count == 1, "The unit close test should begin with one retained native AnimalFullInfoData key.");

                close.Invoke(service, Array.Empty<object>());
                IHookStatusInfo status = runtime.Diagnostics.GetHookStatuses().Single(h => h.HookId == "Animals.ViewerNativeLifecycle");
                Assert(status.Status == "closed" && status.Details.Contains("Unregister", StringComparison.Ordinal),
                    "The native AnimalPanelUiState.Unregister boundary should publish a neutral closed receipt without QA evidence policy.");
                Assert(callback.GetParameters().Length == 0 && closePatched.PropertyType == typeof(bool),
                    "The close callback must match the zero-parameter native Unregister signature and be tracked as a required hook.");
                Assert(retainedRows.Count == 0,
                    "The native panel close boundary must release derived AnimalFullInfoData keys instead of retaining them across repeated UI sessions.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

        private static void AnimalViewerFeatureResetsCloneLifecycleOnBoundaries()
        {
            Assembly bridgeAssembly = typeof(DolocTownGameBridge).Assembly;
            Type featureType = bridgeAssembly.GetType("DTMAPI.GameBridge.DolocTown.AnimalViewerFeature")
                ?? throw new InvalidOperationException("AnimalViewerFeature type should exist.");

            string? previousRoot = UseTempPersistentRoot();
            try
            {
                string dir = NewTempGameDir();
                StageCompatibilityHostFixture(dir);
                var runtime = new DtmApiRuntime(new FakeHost(dir), new ConfigMenuRegistry());
                CompatibilityHostBroker.For(runtime).GetService("AnimalViewer");
                object feature = Activator.CreateInstance(featureType, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic, null, new object[] { runtime }, null)
                    ?? throw new InvalidOperationException("AnimalViewerFeature should be constructable for unit tests.");

                MethodInfo saveLoaded = featureType.GetMethod("SaveLoaded", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("AnimalViewerFeature.SaveLoaded should exist.");
                MethodInfo returnedToTitle = featureType.GetMethod("ReturnedToTitle", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("AnimalViewerFeature.ReturnedToTitle should exist.");
                MethodInfo environmentReset = featureType.GetMethod("EnvironmentReset", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)
                    ?? throw new InvalidOperationException("AnimalViewerFeature.EnvironmentReset should exist.");

                saveLoaded.Invoke(feature, new object[] { false });
                IHookStatusInfo saveStatus = runtime.Diagnostics.GetHookStatuses().Single(h => h.HookId == "Animals.ViewerRenderingLifecycle");
                Assert(saveStatus.Status == "reset" && saveStatus.Details.Contains("SaveLoaded", StringComparison.Ordinal), "AnimalViewer save-load boundary should reset cloned progress-bar runtime state.");

                returnedToTitle.Invoke(feature, Array.Empty<object>());
                IHookStatusInfo titleStatus = runtime.Diagnostics.GetHookStatuses().Single(h => h.HookId == "Animals.ViewerRenderingLifecycle");
                Assert(titleStatus.Status == "reset" && titleStatus.Details.Contains("ReturnedToTitle", StringComparison.Ordinal), "AnimalViewer title boundary should reset cloned progress-bar runtime state.");

                environmentReset.Invoke(feature, new object[] { "unit-test" });
                IHookStatusInfo resetStatus = runtime.Diagnostics.GetHookStatuses().Single(h => h.HookId == "Animals.ViewerRenderingLifecycle");
                Assert(resetStatus.Status == "observed" && resetStatus.Details.Contains("EnvironmentReset unit-test", StringComparison.Ordinal), "AnimalViewer environment reset should validate cloned progress-bar runtime state without destructively clearing a live session.");
            }
            finally
            {
                RestorePersistentRoot(previousRoot);
            }
        }

