        private sealed class FakeDebugConsoleMotionAbility
        {
            private float moveScaler;

            internal FakeDebugConsoleMotionAbility(float scaler)
            {
                moveScaler = scaler;
            }

            public float MoveScaler
            {
                get
                {
                    if (FailNextRead)
                    {
                        FailNextRead = false;
                        throw new InvalidOperationException(
                            "Injected movement readback failure.");
                    }
                    return moveScaler;
                }
            }

            internal float RawMoveScaler => moveScaler;
            internal bool FailNextSet { get; set; }
            internal bool FailNextRead { get; set; }
            internal bool
                ArmPostWriteReadAndRollbackFailure { get; set; }

            public void SetMoveScaler(float scaler)
            {
                if (FailNextSet)
                {
                    FailNextSet = false;
                    throw new InvalidOperationException(
                        "Injected movement restore failure.");
                }
                moveScaler = scaler;
                if (ArmPostWriteReadAndRollbackFailure)
                {
                    ArmPostWriteReadAndRollbackFailure = false;
                    FailNextRead = true;
                    FailNextSet = true;
                }
            }

            internal void ForceScaler(float scaler) =>
                moveScaler = scaler;
        }

